window.__Q=window.__Q||{};window.__Q["prev/5/A2"]=[{"q":"患者，女，16岁。左手食指因外伤发生伤口感染，感染灶局限，分泌物为金黄色脓液。进行细菌分离培养：血平板上菌落呈金黄色，周围出现完全透明的溶血环，凝固酶试验阳性。引起感染最可能的细菌是","o":["A群链球菌","表皮葡萄球菌","金黄色葡萄球菌","腐生葡萄球菌","肺炎链球菌"],"a":2,"e":"菌落金黄色、周围完全透明溶血环、血浆凝固酶阳性，是金黄色葡萄球菌的三项鉴定要点。表皮葡萄球菌菌落白色、凝固酶阴性；腐生葡萄球菌不分解甘露醇、对新生霉素耐药；A群链球菌虽为β溶血，但凝固酶阴性、杆菌肽敏感"},{"q":"患者，女，33岁，有吸毒史，近2年来反复复发带状疱疹5次。导致带状疱疹反复发作的最大原因可能是","o":["恶性肿瘤的感染导致的免疫力下降","疱疹病毒感染引起的免疫力低下","过度劳累导致的免疫力低下","HIV感染导致的免疫力低下","营养不良导致的免疫力低下"],"a":3,"e":"两年内反复复发带状疱疹5次，提示细胞免疫严重受损，结合吸毒史，最可能是HIV感染导致CD4+T细胞减少。恶性肿瘤、劳累与营养不良虽可降低免疫力，但短期内多次复发更提示持续性免疫缺陷；疱疹病毒本身不引起如此严重的免疫抑制"},{"q":"患者，女，38岁，寒战高热，右侧胸痛3天。查体：T39.4℃，意识模糊，右下肺呼吸音减弱。血常规14.3×109/L，胸片示右下肺大片浸润阴影。该患者最可能诊断是","o":["克雷白杆菌肺炎","肺炎链球菌肺炎","肺炎支原体肺炎","干酪性肺炎","病毒性肺炎"],"a":1,"e":"寒战高热、胸痛、意识模糊，右下肺大片浸润影，白细胞升高，为肺炎链球菌肺炎。克雷白杆菌肺炎多见于酗酒与老年，咳砖红色胶冻样痰、叶间裂下坠；肺炎支原体肺炎症状轻、以干咳为主；干酪性肺炎有结核中毒症状与空洞；病毒性肺炎白细胞多正常或降低"},{"q":"一高校男性大学生，与男性伴侣有不洁性生活史6个月有余。为排除HIV感染，首选的病原学检测是","o":["HIV分离培养","Western blot检测HIV抗体","ELISA检测HIV抗体","ELISA检测HIV p24抗原","QRT-PCR检测HIV核酸"],"a":2,"e":"高危性行为后排除HIV感染，首选ELISA检测HIV抗体作初筛，阳性者再以蛋白质印迹法确认。病毒分离培养技术要求高、不作为首选；Western blot属确认试验，不用于初筛；p24抗原与核酸检测用于窗口期早期诊断，成本高、非首选筛查手段"},{"q":"患者，男，55岁，狩猎管理员。曾在小溪岸边捡起一只死麝鼠。4天后，患者右手食指出现1、5cm疼痛性溃疡，右前额1cm溃疡，右腋窝疼痛。体检发现右腋窝淋巴结肿大。该患者很可能感染的病原体是","o":["布鲁氏菌属细菌","立克次体","伤寒沙门菌","土拉热弗朗西丝菌","破伤风梭菌"],"a":3,"e":"狩猎者接触病死麝鼠后，手指与额部出现疼痛性溃疡伴腋窝淋巴结肿大，为土拉热弗朗西丝菌经皮肤侵入所致，该菌为胞内寄生、感染力极强。布鲁氏菌病以波状热与关节痛为主，无皮肤溃疡；立克次体经虱蚤蜱螨叮咬传播；伤寒沙门菌引起肠热症；破伤风梭菌需厌氧伤口并引起肌强直"},{"q":"1986年，我国某地曾发生戊型肝炎的大流行。导致该病的病原体传播和流行的主要方式是","o":["粪-口途径","蚊虫叮咬","直接接触","性传播","血液和血制品"],"a":0,"e":"戊型肝炎病毒经粪-口途径传播，污染水源可引起暴发流行，1986年新疆大流行即因水源被粪便污染所致。蚊虫叮咬传播见于乙脑与登革热；性传播与血液制品传播为HBV、HCV的主要途径；直接接触传播见于狂犬病、疱疹病毒感染"},{"q":"患者一个月前感到疲劳、食欲减少、体重减轻、发热、咳嗽、痰带血丝。痰标本涂片抗酸染色可见红色分支状细菌，疑似可能为结核分枝杆菌，其具有的特殊结构是","o":["分枝菌酸","荚膜","芽孢","菌毛","鞭毛"],"a":1,"e":"结核分枝杆菌在细胞壁外有一层荚膜，主要成分为多糖，与抗吞噬及黏附有关。分枝菌酸是细胞壁脂质成分，不属特殊结构；该菌无芽胞、无鞭毛；菌毛非其典型结构，抗酸染色见红色分枝状杆菌为其形态特点"},{"q":"某患者，突然出现高热，乏力，伴有腓肠肌疼痛、眼结膜出血以及淋巴结肿大。印象诊断是钩体病。该病原体的主要传染源和储存宿主是","o":["猪和犬","羊和牛","鼠和犬","牛和马","鼠和猪"],"a":4,"e":"钩端螺旋体以鼠类和猪为主要传染源与储存宿主，带菌动物尿液污染水源、土壤与淤泥，人接触疫水经皮肤黏膜侵入。羊、牛主要与布鲁菌病有关；犬虽可带菌，但不是主要储存宿主；患者作为传染源的意义很小"},{"q":"患儿5岁，发烧、咽痛、咳嗽5天急诊入院，免疫接种史不详。查体：咽后壁、腭弓和悬雍垂等处发现灰白色膜状物，用灭菌棉拭子不易擦掉。初步诊断为","o":["白喉","急性咽炎","病毒性咽炎","扁桃体炎","支气管炎"],"a":0,"e":"白喉棒状杆菌在咽部繁殖产生外毒素，假膜由纤维蛋白、坏死上皮与菌体构成，与深部组织粘连紧密、不易擦去，为本病病理特征。急性咽炎与病毒性咽炎假膜易擦去或不形成假膜；扁桃体炎以隐窝脓性分泌物为主，无灰白色厚假膜"},{"q":"患者，男，35岁，因腹痛、脓血便2个月入院。患者2个多月前出差回来后突然发热达38℃，无寒战，同时有腹痛、腹泻，大便每日10余次，为少量脓血便，伴里急后重；曾到附近医院，化验大便有多数白细胞，口服几次庆大霉素和黄连素好转。以后虽间断服用黄连素，但仍有黏液性便，左下腹不适，自觉日渐乏力，遂来诊。化验：大便常规为黏液脓性便，白细胞20～30个/HP，偶见成堆脓球，尿常规（－）。初步诊断：慢性菌痢。引起该病的病原菌能够合成的代谢产物是","o":["硫化氢","凝固酶","溶血素","几丁质","热原质"],"a":4,"e":"志贺菌为革兰阴性菌，其细胞壁脂多糖即内毒素，也是热原质，注入体内引起发热，是菌痢发热与中毒症状的基础。凝固酶由金黄色葡萄球菌产生；溶血素见于A群链球菌等；硫化氢主要由沙门菌、变形杆菌产生"},{"q":"患者，女，43岁，因高热15天就诊。血常规：白细胞3、5×109/L。肝肋下触及1cm，脾肋下触及2cm。肥达反应结果为TO 1∶160，TH 1∶320，PA 1∶40，PB 1∶40。为明确诊断，应做哪项检查","o":["抗O试验","协同凝集试验","外斐反应","取血液或骨髓直接进行革兰氏染色","取粪便进行培养"],"a":4,"e":"伤寒病程第2周起病原菌经胆道排入肠道，粪便培养阳性率升高，取粪便分离培养可确诊。血培养以第1周阳性率最高，骨髓培养全程阳性率最高但需穿刺；直接涂片革兰染色因菌量少无诊断价值。抗O试验用于风湿热，外斐反应用于立克次体病"},{"q":"在英国牧场中，一些牛近来出现明显的运动失调、震颤、恐惧、狂躁等症状。这些病牛最可能罹患的疾病是","o":["TME","CWD","BSE","FSE","CJD"],"a":2,"e":"牛海绵状脑病由朊粒引起，1986年首现于英国，病牛表现运动失调、震颤、感觉过敏、恐惧与狂躁，病理见脑组织海绵状空泡变。TME为传染性水貂脑病；CWD为鹿与麋鹿的慢性消耗病；FSE为猫海绵状脑病；CJD为人类克雅病。四者同属朊粒病，但宿主与名称各异"},{"q":"暴风雨过后，某岛上一位50岁的渔民和他的妻子出现腹泻症状，同岛其他人也有轻度腹泻。随后，渔民的妻子出现严重水样腹泻、呕吐，继而肾衰竭，呼吸和心脏功能衰竭。对她进行抗生素治疗和补液疗法效果很好。从患者粪便标本中分离到革兰阴性弧菌。最可能的病原体是下列哪一种","o":["空肠弯曲菌","肠炎沙门菌","福氏志贺菌","霍乱弧菌","幽门螺杆菌"],"a":3,"e":"霍乱肠毒素激活肠黏膜上皮细胞腺苷酸环化酶，使cAMP升高，隐窝细胞分泌氯离子与碳酸氢根增加、绒毛吸收受抑，产生大量米泔水样便，导致脱水与肾衰竭。空肠弯曲菌多致血便且需微需氧培养；肠产毒素型大肠埃希菌不耐热肠毒素机制相似，但病情轻、无米泔水样便"},{"q":"患者，男，75岁，多年高血压及糖尿病史。脑血管意外后卧床2月余，近期出现尿路感染表现，但抗菌治疗无效。中段尿接种到沙保培养基，菌落乳白色奶油样，镜检圆形或卵圆形，有芽生孢子。以下药物可以选择的是","o":["氨苄西林","阿莫西林","苯唑西林","氟康唑","氧氟沙星"],"a":3,"e":"卧床老年患者尿路感染抗菌治疗无效，沙保培养基长出乳白色酵母样菌落、镜检见芽生孢子，为白念珠菌感染，应选氟康唑抑制麦角固醇合成。氨苄西林、阿莫西林与苯唑西林为β-内酰胺类，氧氟沙星为喹诺酮类，均对真菌无效；两性霉素B用于重症或耐药株"},{"q":"患者，男，75岁，以肺部感染及呼衰入院。患者发热、咳嗽、咳痰伴心悸、气短，双下肺湿啰音，痰为黄色、不易咳出。痰标本接种至沙保培养基35℃培养，菌落呈绒毛状，表面呈深绿色、烟绿色，背面淡黄色，棉兰染色可见分生孢子头短柱状，分生孢子梗壁光滑，带淡绿色，顶囊呈烧瓶状，小梗单层，分布在顶囊的上半部，分生孢子球形，绿色，有小刺。该患者可能感染的真菌是","o":["许兰毛癣菌","烟曲霉","放线菌","申克孢子丝菌","诺卡菌"],"a":1,"e":"烟曲霉菌落呈深绿或烟绿色绒毛状，顶囊烧瓶状，小梗单层分布于顶囊上半部，分生孢子球形、绿色、有小刺。黄曲霉顶囊球形、小梗双层布满顶囊表面；黑曲霉孢子黑褐色；构巢曲霉顶囊半球形、小梗双层"},{"q":"患者，女，20岁，个体户。反复头痛已半年，多处诊治，服药5～10日可减轻。近1个月来头痛加重，痛剧时伴恶心、呕吐。检查除颈稍抵抗、Kernig（＋）外，余无阳性征。腰穿CSF压力250mmH2O，细胞50×106/L，蛋白0、86g/L，按病毒性脑膜炎治疗2周无效。查血RPR1∶32，TPHA1∶2560。腰穿CSF230mmH2O，细胞70×106/L，蛋白1.02g/L，RPR1∶2，TPHA1∶1280。经青霉素治疗一疗程，头痛渐轻，最后消失出院。该患者患的疾病最可能为","o":["梅毒性脑膜炎","化脓性脑膜炎","结核性脑膜炎","隐球菌性脑膜炎","流脑"],"a":0,"e":"血RPR1∶32、TPHA1∶2560提示梅毒感染，脑脊液淋巴细胞增多、蛋白升高且RPR、TPHA均阳性，为神经梅毒的脑膜炎型，青霉素治疗有效。结核性脑膜炎以氯化物显著降低、蛋白明显升高为特点；隐球菌脑膜炎墨汁染色见厚荚膜酵母菌；流脑为化脓性、中性粒细胞为主"},{"q":"一脑膜炎患者，疑为新生隐球菌感染。镜检脑脊液离心后的沉渣涂片，应选择的染色方法是","o":["瑞氏染色","革兰染色","墨汁负染法","棉蓝染色","吉姆萨染色"],"a":2,"e":"新型隐球菌在脑脊液中形成酵母型菌体，外包肥厚荚膜，荚膜不着色，墨汁负染时黑色背景中显现透亮荚膜晕圈，是最简便的初诊方法。革兰染色可显示菌体但不显现荚膜；瑞氏与吉姆萨染色用于观察细胞形态及疟原虫，对荚膜显示不佳；棉蓝染色用于真菌菌丝与孢子的形态观察，不用于脑脊液隐球菌荚膜显示"},{"q":"某地区发生数百人食物中毒的公共卫生事件，从患者的呕吐物中分离出革兰阳性、凝固酶阳性的球菌，可疑的病原菌最可能是","o":["希氏沙门菌","大肠埃希菌","C群链球菌","金黄色葡萄球菌","副溶血性弧菌"],"a":3,"e":"食物中毒事件中自呕吐物分离出革兰阳性、凝固酶阳性球菌，为金黄色葡萄球菌肠毒素所致，潜伏期1～6小时、以呕吐为突出表现。希氏沙门菌与大肠埃希菌为革兰阴性杆菌；C群链球菌触酶阴性、链状排列；副溶血性弧菌为革兰阴性弧菌、嗜盐，多与海产品有关"},{"q":"患者，男，36岁，野外作业中受伤。因伤口严重感染入院治疗。患者经林可霉素和头孢菌素治疗4天后，出现血水样腹泻并排出假膜，伴有发热、白细胞增多等全身中毒表现。初步诊断为假膜性结肠炎，可能由下列哪种病原体引起","o":["艰难梭菌","脆弱拟杆菌","产气荚膜梭菌","金黄色葡萄球菌","志贺菌"],"a":0,"e":"林可霉素与头孢菌素使用后出现血水样腹泻并排出假膜，为艰难梭菌毒素A、B所致假膜性结肠炎，是抗生素相关腹泻最重要的病原。脆弱拟杆菌为肠道常驻厌氧菌，不产此类毒素；产气荚膜梭菌引起气性坏疽与坏死性肠炎；金黄色葡萄球菌食物中毒病程短；志贺菌引起脓血便但无假膜"},{"q":"某年秋季，山西某地连续报告流行性乙型脑炎病例数十例，病例呈散发，主要集中于农村地区，以下对该病的最主要预防措施是","o":["隔离乙脑感染病人","人群注射Sabin疫苗","人群注射Salk疫苗","对流行区幼猪进行疫苗接种","防鼠灭鼠"],"a":3,"e":"猪是乙脑病毒的主要扩增宿主，对流行区幼猪接种疫苗可切断猪—蚊—人循环，是预防乙脑的关键措施。Sabin疫苗与Salk疫苗分别预防脊髓灰质炎；隔离病人意义有限，因人仅为终末宿主，蚊才是媒介与储存宿主；灭鼠与乙脑无关"},{"q":"患者，男，40岁，农场工人。主诉全身无力，每日体温规律性升高再降低，夜里盗汗。取患者外周血，培养两周后发现革兰阴性小杆菌。该患者感染的病原体最有可能的是","o":["羊布鲁氏菌","空肠弯曲菌","大肠埃希菌","肠炎沙门菌","痢疾志贺菌"],"a":0,"e":"农场工人有牛羊接触史，波状热、盗汗、乏力，血培养2周后长出革兰阴性小杆菌，符合羊布鲁氏菌感染。空肠弯曲菌多经禽肉传播，引起腹泻与吉兰-巴雷综合征；大肠埃希菌与肠炎沙门菌均为消化道感染、以腹泻为主；痢疾志贺菌引起脓血便与里急后重，血培养极少阳性"},{"q":"患者，男，29岁。在婚检中检出HIV抗体阳性。经询问，否认外伤史、输血手术史、吸毒史等，但回忆在17岁时有过一次嫖娼史。自述平常身体无任何异样。经检测CD4＋T细胞600个/μl，外周血病毒拷贝数低于20拷贝数/ml。关于该病例说法错误的是","o":["该患者可以不用进行抗病毒治疗","该患者仍具有传染性","该患者可能是“长期不进展者”","该患者可以结婚并生下健康的孩子","该患者曾感染了HIV，但现已自愈"],"a":4,"e":"HIV逆转录后整合入宿主细胞基因组形成前病毒，终身携带，不可能自愈；该患者CD4+T细胞600个/μl、病毒载量低于20拷贝/ml，属长期不进展者，但仍有传染性。规范抗病毒治疗与母婴阻断可使其结婚并生育健康婴儿，故暂缓治疗与婚育两项说法成立"},{"q":"患儿，女，3岁。一周前感冒，发热，3天后口腔黏膜起疱，破溃，疼痛。最可能的诊断是","o":["疱疹性龈口炎","流行性感冒","猩红热","水痘","麻疹"],"a":0,"e":"儿童原发感染单纯疱疹病毒1型，表现为发热后口腔黏膜出现水疱、破溃成浅溃疡，疼痛明显，即疱疹性龈口炎。水痘为向心性分布、分批出现的水疱；麻疹有科氏斑与全身斑丘疹；猩红热有杨梅舌与口周苍白圈，均无水疱性口炎表现"},{"q":"患者有丛林接触史，腿部皮肤被叮咬，局部出现溃疡。突发高热，皮疹。经过医院相关检查诊断为立克次体感染。立克次体与革兰阴性菌相似，其中最重要的是","o":["都具有细胞壁","细胞壁中有肽聚糖和脂多糖","可在人工培养基上生长","均为二分裂方式繁殖","均具有DNA和RNA"],"a":1,"e":"立克次体细胞壁含肽聚糖与脂多糖，与革兰阴性菌相似，其脂多糖具内毒素活性，是致病与血清学交叉的基础。立克次体专性细胞内寄生，不能在人工培养基上生长；二分裂繁殖虽同于革兰阴性菌，但并非最重要的相似点；所有细胞型微生物均含DNA与RNA，缺乏鉴别意义"},{"q":"患者，女，38岁。外科创伤修复手术后，手术部位出现剧烈胀痛并伴随高热，血液培养分离出凝固酶阴性革兰染色阳性球菌。引起上述感染的可能性最大的病原菌是","o":["表皮葡萄球菌","金黄色葡萄球菌","肺炎链球菌","脑膜炎奈瑟菌","铜绿假单胞菌"],"a":0,"e":"术后感染、血浆凝固酶阴性的革兰阳性球菌，最可能为表皮葡萄球菌，它是植入物与导管相关感染最常见的凝固酶阴性葡萄球菌。金黄色葡萄球菌凝固酶阳性、脓汁稠厚；肺炎链球菌为双球菌、α溶血；脑膜炎奈瑟菌为革兰阴性双球菌；铜绿假单胞菌为革兰阴性杆菌、产绿色素"},{"q":"患者，男，45岁。近半个月来尿道口轻度红肿，晨起有少许稀薄分泌物。淋球菌培养阴性，沙眼衣原体检查阴性。尿道口棉拭子取样接种支原体液体培养基培养，能分解精氨酸，不分解尿素。固体培养可见“油煎蛋”样菌落。最可能的病原体是","o":["人型支原体","解脲支原体","肺炎支原体","生殖支原体","发酵支原体"],"a":0,"e":"人型支原体分解精氨酸、不分解尿素，固体培养基上呈荷包蛋样菌落，引起尿道炎、盆腔炎与产褥热。解脲脲原体分解尿素而不分解精氨酸；肺炎支原体发酵葡萄糖；生殖支原体发酵葡萄糖、不利用精氨酸与尿素"},{"q":"患者，男，24岁。一天前突然出现腹泻。开始几次为黄色稀便，后转为白色米泔水样便，约每小时一次，无脓血便。无明显腹痛，无里急后重，无恶心、发热、头痛。几小时前，尿量明显减少，无腰痛。查体：体温35℃，血压80/50mmHg，脉搏110次/min；眼睑及双下肢无水肿，腹软，无压痛反跳痛，肾区无压痛、叩痛。引起该病的病原菌生化反应特点是","o":["吲哚试验阳性","尿素酶试验阳性","硫化氢试验阳性","分解葡萄糖产酸产气","枸橼酸盐利用试验阳性"],"a":0,"e":"无痛性剧烈水样泻、迅速脱水、血压下降，符合霍乱；霍乱弧菌分解色氨酸生成吲哚，吲哚试验阳性。尿素酶阳性为变形杆菌与幽门螺杆菌；硫化氢阳性为沙门菌与变形杆菌；多数肠杆菌科细菌分解葡萄糖产酸产气，霍乱弧菌发酵糖类不产气；枸橼酸盐利用阳性为肠杆菌属等"},{"q":"患儿，男，9岁。急性发热，体温持续39℃以上，咳嗽无痰，全身酸痛，稍气促，无发绀，双肺呼吸音粗，可闻及少量细湿啰音。血常规检查显示白细胞总数降低。血生化检查肌酸激酶、乳酸脱氢酶、天门冬氨酸氨基转移酶、丙氨酸氨基转移酶均升高。该患儿近期有病死禽密切接触史，捡到1只麻雀并饲养但是几天后死亡。该患儿最可能的诊断是","o":["普通感冒","大叶性肺炎","人感染高致病性禽流感","肺结核","严重急性呼吸综合征（SARS）"],"a":2,"e":"病禽与病死麻雀接触史，持续高热、咳嗽气促，白细胞降低而肌酸激酶与转氨酶升高，符合人感染高致病性禽流感。普通感冒全身症状轻、无肺炎与酶学升高；大叶性肺炎多为肺炎链球菌所致，白细胞升高、咳铁锈色痰；肺结核为慢性低热盗汗；SARS有明确接触史且以肺间质渗出为主"},{"q":"患儿，男，8岁。发热伴皮疹5天，最先在前躯干部出现斑丘疹或水疱疹，后迅速向全身发展，呈向心性分布。最可能的诊断是","o":["麻疹","唇疱疹","斑疹伤寒","水痘","猩红热"],"a":3,"e":"皮疹先见于躯干、呈向心性分布，由斑丘疹迅速转为水疱疹，为水痘-带状疱疹病毒原发感染。麻疹皮疹自耳后发际开始、为斑丘疹且不退化为水疱；唇疱疹为局限性成群水疱；斑疹伤寒为全身斑丘疹、无疱疹；猩红热为弥漫充血性皮疹伴草莓舌"},{"q":"患者，女，19岁，因咳嗽、发热、乏力就诊。拍胸片发现右肺有片状阴影，痰标本抗酸染色阳性，诊断为肺结核病。以下说法正确的是","o":["常见病原体为牛型结核分枝杆菌","可经呼吸道途径传播","可经蚊虫叮咬传播","原发肺结核病灶易形成空洞","继发肺结核只能是外源性感染"],"a":1,"e":"痰抗酸染色阳性的肺结核经呼吸道飞沫核传播，是结核最主要的传播途径。人型结核分枝杆菌为主要病原，牛型少见；蚊虫叮咬不传播结核；原发肺结核以原发综合征为特征，空洞多见于继发型；继发型肺结核可为内源性复发，并非只能外源性再感染"},{"q":"患者，男，35岁，一周前从东南亚入境，3天前因突然剧烈呕吐、腹泻而入院。腹泻物呈米泔样，便检发现穿梭状运动的细菌。请问致病菌可能是","o":["肠侵袭性大肠埃希菌","伤寒沙门菌","变形杆菌","猪霍乱沙门菌","霍乱弧菌"],"a":4,"e":"来自东南亚、剧烈吐泻、米泔水样便，便检见穿梭状运动的细菌，为霍乱弧菌，其单鞭毛使菌体运动极活泼。肠侵袭性大肠埃希菌引起脓血便；伤寒沙门菌有持续发热与相对缓脉；变形杆菌为条件致病菌、呈迁徙生长；猪霍乱沙门菌引起败血症与局灶性感染"},{"q":"患者，男，35岁，屠宰工人。因发热、头痛、腓肠肌疼痛就诊。查体：体温39℃，眼结膜充血，浅表淋巴结肿大。行MAT检查，凝集效价为1∶800。注射大剂量青霉素治疗后出现寒战高热，血压下降。该症状出现的可能与下列哪种因素有关","o":["流感病毒包膜","新生隐球菌荚膜","钩端螺旋体释放的毒性物质及可溶性抗原","支原体神经毒素","立克次体脂多糖"],"a":2,"e":"大剂量青霉素迅速杀灭钩端螺旋体，菌体裂解释放大量毒性物质与可溶性抗原，引起寒战、高热、血压下降的赫氏反应。流感病毒包膜与支原体神经毒素均与钩体病无关；新生隐球菌荚膜为抗吞噬结构，不引起此类反应；立克次体脂多糖具内毒素样作用，但本例病原已由MAT效价1∶800确认为钩端螺旋体"},{"q":"某幼儿园某日出现数十例集体性流感样症状患者，经胶体金法初筛A型流感阳性。如需进行流感病毒核酸分亚型检测，可采集的临床标本是","o":["鼻咽拭子","血浆标本","尿液","肛拭子","血清标本"],"a":0,"e":"流感病毒侵犯呼吸道上皮，鼻咽拭子含病毒量最高，是核酸检测与病毒分离分亚型的首选标本，咽漱液亦可采用。血浆与血清用于抗体检测，不能直接分亚型；尿液与肛拭子不含呼吸道病毒，无检测价值；粪便标本仅用于肠道病毒分离"},{"q":"患儿，男，1个月，因多发皮疹入院。皮疹呈圆形，外周有丘疹，带有鳞屑，掌拓部有大疱。患儿母亲吸毒，母血RPR阳性。该患儿最有可能的诊断是","o":["梅毒","HIV垂直感染","风疹病毒感染","淋病","疱疹病毒"],"a":0,"e":"母亲RPR阳性且有吸毒史，患儿生后皮疹呈圆形伴鳞屑、掌跖出现大疱，为胎传梅毒的典型皮损。HIV垂直感染不出现掌跖大疱与鳞屑性丘疹；风疹病毒感染表现为先天性白内障、耳聋与心脏畸形；淋病奈瑟菌经产道感染引起新生儿化脓性结膜炎；疱疹病毒多为生后水疱与角膜炎，与母血RPR阳性不符"},{"q":"某女青年因咳嗽发热就诊，胸片发现右肺有片状阴影，结核菌素试验红肿直径大于2、0cm，该患者可能是","o":["机体对结核无免疫能力","结核病恢复期","结核病活动期","注射过卡介苗","感染过结核"],"a":2,"e":"胸片见肺部片状阴影，PPD红肿直径大于2.0cm呈强阳性，提示体内存在活动性结核病灶。仅PPD阳性而无病灶者为感染过结核；卡介苗接种后多为弱阳性；恢复期病灶稳定、无活动性影像表现；无免疫能力者PPD多为阴性"},{"q":"患者，女，40岁，体检中发现其宫颈细胞有高度上皮间瘤样病变。有多个性伴侣和衣原体感染，已有5年未做过阴道细胞涂片检查。与该病例最有可能存在关联性的病毒是","o":["副黏病毒","黄病毒","人乳头瘤病毒","细小DNA病毒","风疹病毒"],"a":2,"e":"宫颈高度上皮内瘤变，伴多个性伴侣与衣原体感染，与人乳头瘤病毒16、18型持续感染密切相关，其E6、E7蛋白分别灭活p53与Rb。副黏病毒引起麻疹、腮腺炎；黄病毒中的HCV与肝癌相关，乙脑病毒引起脑炎；细小病毒B19引起传染性红斑；风疹病毒致畸但不致癌"},{"q":"患者，女，32岁。食用毛蚶后出现发热、黄疸、厌油和肝大，诊断为“急性甲型肝炎”。该患者从体内排出病毒最多、传染性最强的时期是","o":["感染后1周内","发病2周后","发病前后2周内","发病后1个月","恢复期"],"a":2,"e":"甲型肝炎病毒在潜伏期末至发病初期经胆汁排入肠道，粪便排毒高峰在发病前后2周内，此期传染性最强。发病2周后抗-HAV IgM与IgA产生，粪便不再排毒；感染后1周内尚处潜伏期，排毒未达高峰；发病后1个月与恢复期已无传染性。HAV极少经血传播"},{"q":"患者，28岁，因足底外伤，继而发热、惊厥、牙关紧闭呈苦笑面容入院，诊断为破伤风。引起上述症状的破伤风梭菌具有诊断意义的特殊结构是","o":["芽孢","菌毛","鞭毛","荚膜","性菌毛"],"a":0,"e":"破伤风梭菌芽胞位于菌体顶端、使菌体呈鼓槌状，抵抗力强、耐煮沸与消毒剂，是能在土壤中长期存活并经伤口感染的特殊结构，具有诊断与防治意义。菌毛与性菌毛介导黏附与接合；鞭毛与运动有关；荚膜并非该菌结构"},{"q":"患儿，女，4岁，因发烧、游走性关节炎和心肌炎而入院。其父母陈述大约两周前，该患儿出现严重的喉痛，伴发烧和胃痛，但病情几天后自然地消退。入院前两天，患儿开始出现面部、颈部和四肢奇怪的运动，这些在检查中发现是无意识、无目的、不适当的运动。实验室检查显示白细胞增多，蛋白水平升高，血沉速度升高，常规血培养结果阴性，但患儿血清中发现高滴度抗链球菌溶血素O抗体。该患儿最可能患的是","o":["急性风湿热","链球菌性的心内膜炎","破伤风","白喉","小儿麻痹症"],"a":0,"e":"链球菌咽峡炎后2～3周出现游走性关节炎、心肌炎与舞蹈症，ASO滴度升高而血培养阴性，为急性风湿热，属Ⅱ型超敏反应性免疫损伤。链球菌性心内膜炎有心脏杂音且血培养阳性；破伤风有牙关紧闭与角弓反张，无游走性关节炎"},{"q":"患者，女，50岁。高热、剧烈头痛、肌肉酸痛4天，皮疹1天入院。查体见患者眼结膜及面部充血，颈部有直径大约3～4mm斑丘疹。外斐反应（变形杆菌OX19）效价为1∶320。引起该病的病原体可能是","o":["贝纳柯克斯体","普氏立克次体","汉塞巴通体","汉坦病毒","恙虫病东方体"],"a":1,"e":"高热、剧烈头痛与肌痛、结膜及面部充血，外斐反应OX19 1∶320，为普氏立克次体所致流行性斑疹伤寒。斑疹伤寒立克次体（地方性）滴度较低、以鼠蚤为媒介；恙虫病东方体为OXK阳性；贝纳柯克斯体外斐反应阴性、引起Q热；汉坦病毒引起肾综合征出血热，无外斐反应交叉"},{"q":"取患者脑脊液离心沉渣做墨汁负染色镜检，发现下列哪些典型结构或形态可初步诊断为新型隐球菌性脑膜炎","o":["卵圆形菌体及厚膜孢子","厚膜孢子及芽生孢子","厚膜孢子及假菌丝","芽生孢子及宽厚荚膜","假菌丝及芽生孢子"],"a":3,"e":"新型隐球菌在墨汁负染中显示圆形菌体、出芽及外周一圈宽厚荚膜，为脑脊液检查的确诊依据。厚膜孢子与假菌丝见于白念珠菌；宽大无隔菌丝见于毛霉、根霉；卵圆形菌体伴厚膜孢子并非隐球菌特征"},{"q":"患儿，男，2岁。因腹泻住院，广谱抗菌药物治疗6天后症状明显好转停药，第9天再次发生腹泻，怀疑发生真菌所致二重感染。为确诊，正确的检查方法是","o":["显微镜检查","血清学试验","动物实验","核酸检测","真菌分离培养"],"a":4,"e":"广谱抗生素使用后腹泻再发，疑二重感染，确诊需真菌分离培养并结合形态鉴定，沙保培养基上的菌落性状与镜下孢子、假菌丝可确定菌种。直接镜检只能提示真菌存在，难以区分定植与感染；血清学试验特异性不足；动物实验与核酸检测非常规确诊手段"},{"q":"患儿，女，5岁。低热，口咽部疼痛，口腔黏膜、牙龈、咽部、嘴唇以及手和脚后跟边缘呈较多水疱状病变，水疱内不含巨细胞或异常细菌。患儿最可能感染的病原体是","o":["麻疹病毒","恙虫病东方体","柯萨奇病毒","水痘-带状疱疹病毒","单纯疱疹病毒"],"a":2,"e":"柯萨奇病毒A16等经粪-口途径传播，在口腔黏膜及手、足出现水疱，疱液清亮、不含巨细胞，即手足口病。水痘-带状疱疹病毒皮疹呈向心性分布、疱液含多核巨细胞；单纯疱疹病毒致龈口炎或唇疱疹，不累及手足"},{"q":"患者，男，22岁，因打架斗殴入狱。在入狱前例行体检中检出HIV抗体阳性。经询问，该患者多次嫖娼，多次聚众吸毒，曾因打架受伤接受过输血治疗。经检测CD4＋ T细胞低于200个/μl。关于该病例说法不正确的是","o":["该患者可能经由性接触感染HIV","该患者处于无症状潜伏期","该患者可能经由输血途径感染HIV","该患者可能经由吸毒共用针管感染HIV","该患者目前免疫力低下"],"a":1,"e":"CD4+T细胞低于200个/μl已进入艾滋病期，此期病毒载量高、免疫严重缺陷，可发生机会性感染与肿瘤，故“处于无症状潜伏期”不成立。无症状期CD4多在200以上、逐年下降且无明显症状。性接触、共用注射器与输血均为HIV明确传播途径，本例三种暴露并存；CD4低于200本身即说明免疫力低下"},{"q":"患者，男，36岁，鸟语林工作人员。突然高热达40℃，剧烈头痛，伴恶心呕吐入院。查体：咽部充血疼痛，伴咳嗽，肺部听诊有湿啰音。胸片可见支气管炎型的肺浸润灶，以下叶为多。初步诊断为间质性肺炎，最可能是","o":["肺炎支原体感染","肺炎嗜衣原体感染","沙眼衣原体血清型D-K感染","鹦鹉热嗜衣原体感染","沙眼衣原体血清型A、B、Ba、C感染"],"a":3,"e":"鹦鹉热嗜衣原体寄生于鸟类，人吸入病鸟排泄物气溶胶后感染，表现为高热、剧烈头痛、干咳及下叶支气管肺炎。肺炎衣原体经人—人呼吸道传播、症状轻；沙眼衣原体D～K型致泌尿生殖道感染与新生儿肺炎"},{"q":"一新生儿患脓毒血症，脓汁标本经涂片革兰染色镜检发现葡萄球菌。经鉴定该菌属金黄色葡萄球菌。从患儿体内分离的该菌可具有的特殊结构是","o":["普通菌毛","性菌毛","芽孢","荚膜","鞭毛"],"a":3,"e":"金黄色葡萄球菌有荚膜，无芽胞、无鞭毛，革兰阳性、呈葡萄串状排列。芽胞为梭菌属与芽胞杆菌属所有；鞭毛见于大肠埃希菌、霍乱弧菌等；性菌毛仅见于革兰阴性菌，普通菌毛黏附力弱、非其特殊结构"},{"q":"一新生儿室暴发脓毒血症，脓汁标本经涂片、革兰染色镜检发现大量葡萄球菌。为确定该菌是否有致病力，应检查","o":["血浆凝固酶","触酶","DNA聚合酶","尿素酶","磷酸酯酶"],"a":0,"e":"判断葡萄球菌致病力强弱主要看血浆凝固酶，该酶使纤维蛋白原转变为纤维蛋白包绕菌体、抵抗吞噬，凝固酶阳性者致病力强。触酶用于区分葡萄球菌与链球菌，不能判断致病力；DNA聚合酶、尿素酶与磷酸酯酶均非致病力指标"},{"q":"患者持续发热12天到医院就诊，精神萎靡，反应淡漠，持续高热。体温39、5℃，心率80次/min，肝肋下1.5cm，脾肋下2cm。白细胞 3.4×109/L，肥达反应结果显示O 1∶80、H 1∶160，HBsAg阴性。为确定诊断，应进行检查的项目是","o":["乙型肝炎病毒抗体","甲型肝炎病毒抗体","取外周血分离培养","丙型肝炎病毒抗体","标本取骨髓液，分离培养"],"a":4,"e":"伤寒第1～3周骨髓培养阳性率最高，且不受已用抗菌药物影响，疑诊肠热症时应取骨髓液分离培养。肥达反应仅为辅助诊断，不能替代病原学检查；病程12天时外周血培养阳性率已明显下降；乙肝、甲肝、丙肝抗体与本例无关"},{"q":"患者，男，24岁，有不洁性接触史，因近2日尿急、尿频、排尿刺痛而来院就诊。查体见尿道口有白色脓性分泌物。分泌物涂片染色，镜下见到G－成双排列的球菌。该患感染可能是由哪种细菌引起","o":["肺炎链球菌","淋病奈瑟菌","葡萄球菌","链球菌","脑膜炎奈瑟菌"],"a":1,"e":"不洁性交后尿急尿痛、尿道口白色脓性分泌物，涂片见革兰阴性双球菌，为淋病奈瑟菌。肺炎链球菌为革兰阳性双球菌、引起肺炎；葡萄球菌与链球菌为革兰阳性球菌；脑膜炎奈瑟菌经呼吸道传播引起流脑，不引起尿道炎"},{"q":"20岁在校大学生，寒假前往北方某地游玩，突发头痛、恶心呕吐，伴有腹部痉挛性疼痛和水样便，无发热。电镜下粪便中可见大量球形病毒颗粒，具有双层衣壳，形似车轮状。对于该病毒的特性描述正确的是","o":["基因组分11个节段","不会引起动物腹泻","胰酶作用可使其感染性消失","致病机制是导致肠黏膜出血性坏死","目前无有效疫苗加以预防"],"a":0,"e":"电镜下双层衣壳、车轮状颗粒为轮状病毒，其基因组由11个节段的双链RNA组成，各节段可独立重组。该病毒可感染动物引起腹泻；胰酶处理可增强其感染性而非使之消失；致病机制为侵犯小肠绒毛上皮细胞致吸收障碍与分泌增加，不是出血性坏死；已有口服减毒活疫苗"},{"q":"患者，18岁，头痛剧烈，喷射性呕吐，体温40℃，皮肤呈出血性淤斑。查脑膜刺激征（＋）。培养此病原菌应选用","o":["远藤氏培养基","博-金氏培养基","巧克力色培养基","吕氏培养基","罗氏培养基"],"a":2,"e":"高热、头痛、喷射性呕吐、皮肤出血性瘀斑、脑膜刺激征阳性，为脑膜炎奈瑟菌引起的流行性脑脊髓膜炎；该菌营养要求高，须用巧克力色血平板在5%CO₂中培养。远端氏培养基用于肠道菌；鲍-金培养基用于百日咳鲍特菌；吕氏培养基用于白喉棒状杆菌；罗氏培养基用于结核分枝杆菌"},{"q":"患者，女，26岁，在剖宫产的术前例行检查中检出HIV抗体阳性。经询问，其丈夫为吸毒人员。对于该病例说法错误的是","o":["该患者的丈夫极有可能也是HIV感染者","患者的胎儿极有可能感染HIV","该患者可以正常母乳喂养婴儿","该患者的手术器械应严格的消毒灭菌","该患者的胎盘等组织块应彻底销毁"],"a":2,"e":"HIV可经乳汁传播，感染母亲应避免母乳喂养，改用配方奶，以防产后垂直传播。胎盘等组织与手术器械须严格消毒灭菌或销毁，以防职业暴露；HIV抗体阳性孕妇所生婴儿存在垂直感染风险，需母婴阻断并随访"},{"q":"患者，女，27岁。家里养一只小狗。患者因前额、颈部多发环状红斑14天来院就诊。皮肤专科检查：前额及颈部共四个黄豆至铜钱大小皮损，略呈圆形斑块，周围稍高起，中央较平坦，皮损边缘活跃，见有密集的红色小丘疹及领圈样鳞屑，中央皮肤淡红或正常肤色。真菌学检查：取皮损边缘鳞屑，10%KOH制片直接镜检可见如图所示结构，箭头所指结构为","o":["生殖菌丝","结节菌丝","球拍状菌丝","有隔菌丝","螺旋状菌丝"],"a":3,"e":"本题原题配有图片，图片未随文档保留，以下解析依文字线索推断：题干涉及图片/信息缺失，无法作答。皮肤癣菌及多数致病真菌的菌丝有横隔，10%KOH镜检见分枝、有隔菌丝即可诊断癣病。无隔菌丝见于毛霉、根霉等接合菌；球拍状菌丝、结节菌丝与螺旋状菌丝均为部分皮肤癣菌的形态变异，不作定种依据\n\n官方题库中缺失图片"},{"q":"患者，男，26岁，军官，参加抗洪抢险，天气酷暑炎热，口渴难忍，喝了老百姓送来的矿泉水，2小时后剧烈腹部绞痛，水样便腹泻伴呕吐4次，继之出现米泔水样便。查体：疲倦面容，皮肤、唇舌干燥，眼窝深陷。血压53/37mmHg。取呕吐物和米泔水样便悬滴法镜检，见鱼群样细菌穿梭样运动。病原体可能为","o":["螺旋体","病毒","真菌","细菌","立克次体"],"a":3,"e":"饮生水后剧烈腹泻、米泔水样便、重度脱水，悬滴镜检见鱼群样穿梭运动的细菌，为霍乱弧菌，属细菌。螺旋体细长呈螺旋状、运动方式不同；病毒无细胞结构、须在活细胞内增殖；真菌以菌丝与孢子繁殖；立克次体专性细胞内寄生、经节肢动物传播，均不引起此类表现"},{"q":"患儿，男，出生63天。自出生第3天起出现黄疸，第10天左右黄疸基本消退，但1个月前又出现明显黄疸，精神、食欲尚可，无其他明显症状。其黄疸最可能的原因是","o":["生理性黄疸","甲型肝炎病毒感染","乙型肝炎病毒感染","黄病毒感染","人巨细胞病毒感染"],"a":4,"e":"生后黄疸消退后再次出现并持续，而精神食欲尚可，为婴儿肝炎综合征表现，人巨细胞病毒经胎盘或产道感染、在肝胆系统复制是常见原因。生理性黄疸多在生后2周内消退；甲型与戊型肝炎极少经垂直传播；黄病毒感染无母婴垂直传播的典型表现"},{"q":"春季，一幼儿园数名儿童先后出现发热，流泪、流涕，眼结膜充血，咳嗽，面部、躯干及上肢皮肤呈米糠样斑丘疹。这些患儿最可能的诊断是","o":["风疹","麻疹","猩红热","伤寒","莱姆病"],"a":1,"e":"麻疹病毒经飞沫传播，冬春季在托幼机构易暴发，前驱期有发热、流泪、结膜充血与咳嗽，出疹期见米糠样红色斑丘疹。风疹皮疹细小、伴耳后淋巴结肿大、全身症状轻；猩红热为弥漫充血性皮疹，伴杨梅舌、口周苍白圈与帕氏线"},{"q":"患者，男，26岁。自诉7月在某森林探险后，突然发热，头痛、恶心、无食欲。体检发现：面神经轻瘫，表情淡漠，有脑膜刺激征。血液检测示白细胞总数升高，中性粒细胞显著增高。在下列病原微生物中，患者最有可能感染的是","o":["登革病毒","汉坦病毒","流行性感冒病毒","脊髓灰质炎病毒","森林脑炎病毒"],"a":4,"e":"森林脑炎病毒经蜱叮咬传播，夏秋季林区多见，表现为高热、头痛、恶心、脑膜刺激征及肩胛带弛缓性麻痹。登革病毒由伊蚊传播，以高热、皮疹、骨痛为主；汉坦病毒致肾综合征出血热，有出血与肾损害"},{"q":"患儿，男，3个月。口服脊髓灰质炎减毒活疫苗11天后，开始出现发热伴轻度咳嗽，无寒战、抽搐。退热后发生下运动神经元不对称性麻痹，脑脊液示蛋白-细胞分离，肌电图示神经源性受损，脊髓、头部MRI未见异常。该患儿最可能的诊断是","o":["海绵状脑病","流行性乙型脑炎","肉毒毒素中毒","疫苗相关麻痹型脊髓灰质炎","无菌性脑膜炎"],"a":3,"e":"口服Sabin减毒活疫苗后11天出现发热及不对称弛缓性麻痹，脑脊液呈蛋白-细胞分离，符合疫苗相关麻痹型脊髓灰质炎，多见于免疫功能低下儿童。乙型脑炎以高热、意识障碍为主且无服疫苗史；肉毒中毒为对称性下行性弛缓性麻痹，脑脊液正常"},{"q":"患者，男，28岁。近1周出现尿道口轻度红肿，晨起有少许稀薄分泌物。淋球菌培养阴性，支原体检查阴性，疑为衣原体感染。为确诊，下列处理方法中，错误的是","o":["尿道口拭子标本做衣原体核酸检测","尿道口拭子标本经抗生素无菌处理后鸡胚培养","尿道口拭子标本用膜式滤菌器除菌后做细胞培养","标本涂片用直接免疫荧光法镜检","标本涂片吉姆萨染色镜检"],"a":1,"e":"衣原体严格细胞内寄生，分离培养须接种敏感活细胞（McCoy、HeLa），尿道拭子经抗生素处理后直接接种鸡胚不能替代细胞培养，故该项处理方法错误。核酸检测、直接免疫荧光与吉姆萨染色查包涵体均为有效确诊手段；膜式滤菌器可除去杂菌而保留衣原体，滤液用于细胞培养"},{"q":"患儿，男，10岁。右足底被铁锈钉刺伤10天。突然出现张嘴困难，继之出现苦笑面容，角弓反张，声响及触碰患儿可诱发上述症状。患儿神志清楚，不发热。患儿所患疾病的致病菌属于","o":["革兰染色阴性大肠杆菌","革兰染色阴性变形杆菌","革兰染色阴性厌氧拟杆菌","革兰染色阳性无芽孢厌氧菌","革兰染色阳性厌氧芽孢杆菌"],"a":4,"e":"破伤风梭菌为革兰阳性厌氧芽胞杆菌，芽胞位于菌体顶端呈鼓槌状，专性厌氧，伤口深窄时芽胞发芽产毒。大肠埃希菌与变形杆菌为革兰阴性兼性厌氧菌；拟杆菌为革兰阴性无芽胞厌氧菌；革兰阳性无芽胞厌氧菌如丙酸杆菌不产生痉挛毒素"},{"q":"患者，男，30岁，海南人。10月22～25日突然出现畏寒、发热，体温38、5℃，伴有头痛、眼眶痛及眼结膜充血。自10月25日起病情突然加重，体温39℃，皮肤出现大片紫癜及瘀斑，并出现黑便，粪便潜血试验阳性，血常规显示血小板数目为10×109/L，尿常规正常。该患者最可能感染的病原体是","o":["登革病毒","汉坦病毒","钩端螺旋体","沙门氏菌","脑膜炎奈瑟菌"],"a":3,"e":"官方答案为【沙门氏菌】，但依据教材，正确答案为【登革病毒】。10月海南、急起畏寒高热、头痛、眼眶痛、结膜充血，继而大片紫癜瘀斑、血小板降至10×10⁹/L，符合登革热重型，教材明确其表现为皮肤大片紫癜及瘀斑、鼻衄与消化道出血。沙门菌感染以持续发热、相对缓脉、玫瑰疹与白细胞减少为特征，不出现眼眶痛与血小板锐减"},{"q":"某女性患者因肺部细菌感染入院接受治疗。常规抗生素治疗效果不佳，考虑到可能是存在L型细菌的感染。此时，制作细菌培养基时，应考虑到","o":["细菌菌体内的渗透压","细菌菌体表面积大小","细菌的带电现象","细菌的化学组成","细菌的光学性质"],"a":0,"e":"L型细菌失去细胞壁，丧失对胞内高渗的抵抗，须在含高渗蔗糖或明胶的低琼脂培养基中才能存活与生长，故培养基设计首要是补偿菌体内渗透压。菌体表面积、带电现象与化学组成不决定培养基渗透压；光学性质与培养无关；在普通培养基中L型易胀裂死亡"},{"q":"患儿，8岁，半年前在脸、躯干及四肢等处出现大量皮肤小突起，不痛不痒，中心凹陷，内有干酪样塞物。涂抹多种药膏均无效。后上述突起自行消退。初步诊断该疾病是","o":["跖疣","传染性软疣","扁平疣","鲍温样丘疹","寻常疣"],"a":1,"e":"传染性软疣病毒经皮肤接触传播，儿童多见，皮损为中央凹陷、内含干酪样物的半球形丘疹，可自行消退、不留瘢痕。寻常疣与跖疣由人乳头瘤病毒引起，表面粗糙角化、无中央脐凹；扁平疣为扁平丘疹，好发于面部与手背"},{"q":"成年男性，因被流浪猫抓伤小腿（伤口很深）而来到社区医院就诊。对该病例不恰当的处理方式是","o":["应立即对伤口深部进行灌流清洗，并用碘酊消毒","可联合使用抗狂犬病免疫球蛋白","肌肉注射大剂量的青霉素","局部注射抗狂犬病病毒血清","接种狂犬病病毒灭活疫苗"],"a":2,"e":"狂犬病暴露处置为立即冲洗伤口深部并用碘酊消毒、接种灭活疫苗，深部伤口还需局部浸润抗狂犬病血清或免疫球蛋白。青霉素对狂犬病病毒无效，也不能替代暴露后免疫，肌注大剂量青霉素属错误处理。冲洗消毒是首要步骤，被动免疫制剂与疫苗需联合使用"},{"q":"患者，男，15岁，学生。3天前突然高热达39℃，伴发冷和寒战，同时出现剧烈头痛，频繁呕吐，呈喷射性，吐出食物和胆汁，无上腹部不适，进食少，二便正常。查体见皮肤散在少量出血点和脑膜刺激征。既往体健，无胃病和结核病史，无药物过敏史，所在学校有类似患者发生。取淤斑涂片镜检可见G－双球菌。临床诊断为流行性脑脊髓膜炎。建议首选的治疗药物是","o":["青霉素G","磺胺药物","红霉素","核苷类似物","阿德福韦"],"a":0,"e":"流脑瘀斑涂片见革兰阴性双球菌，病原为脑膜炎奈瑟菌，治疗首选青霉素G，过敏者改用红霉素或第三代头孢。磺胺药仅用于流行期预防性投药，耐药株多见；核苷类似物与阿德福韦为抗病毒药，对细菌无效；红霉素属替代用药而非首选"},{"q":"患者，男，45岁。患有慢性乙肝，3个月前因吸毒与他人共用针头导致感染HDV。此患者易于发展的结果是","o":["急性肝炎","慢性肝炎","慢性活动性肝炎","重型肝炎","原发性肝癌"],"a":3,"e":"慢性乙肝基础上重叠感染HDV，HDAg与HBV包膜共存，双重病毒复制使肝细胞损伤加重，易发展为重型肝炎并促发肝硬化、肝癌。急性肝炎多见于初次感染且病程自限；慢性肝炎指病程超过半年；原发性肝癌需长期随访与影像学证据，不是本例的直接转归"},{"q":"患儿，男，10岁。右足底被铁锈钉刺伤10天。突然出现张嘴困难，继之出现苦笑面容，角弓反张，声响及触碰患儿可诱发上述症状。患儿神志清楚，不发热。患儿所患疾病为","o":["毒血症","败血症","菌血症","脓血症","脓毒血症"],"a":0,"e":"破伤风痉挛毒素入血并沿神经上行至中枢，细菌局限于伤口而毒素引起全身症状，故为毒血症，患儿神志清楚、不发热亦相合。败血症为细菌入血繁殖并伴全身中毒；菌血症血中仅有细菌而无明显中毒表现；脓毒血症为化脓菌入血并形成迁移性脓肿"},{"q":"患儿，男，10岁，发热出疹3天。红疹始于面部，后向肢体扩散。A族链球菌抗原检测阴性，诊断为传染性红斑。最可能导致该病的病原体是","o":["风疹病毒","痘病毒","人乳头瘤病毒","单纯疱疹病毒","细小DNA病毒"],"a":4,"e":"细小病毒B19经呼吸道传播，儿童感染表现为面颊部巴掌样红斑并向躯干四肢扩展的传染性红斑，可伴低热与关节痛。风疹病毒皮疹伴耳后及枕下淋巴结肿大；人乳头瘤病毒致多种疣；痘病毒致天花与传染性软疣"},{"q":"一女性患者47岁，自制盐腌花生米与海产品存贮在同一冰箱，食入后引起上腹部阵发性绞痛，继而腹泻、有血样便。后出现恶心、呕吐，体温38.2℃，发病6小时后症状减轻，12小时症状消失痊愈。该女士可能感染下列哪种病原菌","o":["霍乱弧菌","副溶血性弧菌","幽门螺旋杆菌","空肠弯曲菌","蜡样芽孢杆菌"],"a":1,"e":"盐腌花生米与海产品同贮，食后阵发性腹绞痛、血水样便、发热，6小时后缓解，病程自限，为副溶血性弧菌食物中毒，该菌嗜盐、存在于海产品。霍乱为无痛性米泔水样泻；幽门螺杆菌引起慢性胃炎与溃疡；空肠弯曲菌多为水样便转血便、病程数日；蜡样芽孢杆菌食物中毒潜伏期更短"},{"q":"患者，男，40岁，一周前出现高热，维持在39、5～40℃，全身乏力，大便次数增多，每天5～6次。肥达反应：TO 1∶160，TH 1∶320，PA 1∶40，PB 1∶40。引起这种疾病的病原体可能是","o":["霍乱弧菌","伤寒沙门菌","克雷伯菌","福氏志贺菌","变形杆菌"],"a":1,"e":"肥达反应O效价1∶160、H效价1∶320，提示伤寒沙门菌感染，持续高热、乏力与腹泻符合肠热症。霍乱弧菌致米泔水样便，肥达反应阴性；福氏志贺菌致菌痢，以脓血便、里急后重为主；变形杆菌的O抗原与立克次体交叉，用于外斐反应"},{"q":"患儿首次服脊髓灰质炎减毒活疫苗后，第21天出现发热、肢体乏力。查体显示四肢肌力0级，肌张力低，颈部以下皮肤痛觉缺失。麻痹第5天大便标本分离到脊髓灰质炎Ⅰ型病毒疫苗株，实验室检查未发现其他病原体感染，磁共振检查显示延髓、颈段、下胸段脊髓多发病变，胸11椎体水平以下脊神经前根强化较显著。该患儿最可能的诊断是","o":["海绵状脑病","流行性乙型脑炎","肉毒毒素中毒","无菌性脑膜炎","疫苗相关麻痹型脊髓灰质炎"],"a":4,"e":"服脊灰减毒活疫苗后21天出现发热与不对称弛缓性瘫痪，粪便分离到Ⅰ型疫苗株，为疫苗相关麻痹型脊髓灰质炎，疫苗株在肠道回复突变后侵犯脊髓前角。乙型脑炎有意识障碍与脑膜刺激征、非弛缓性瘫；肉毒毒素中毒为对称性下行性麻痹；海绵状脑病为进行性痴呆；无菌性脑膜炎无肢体瘫痪"},{"q":"两名大学生在路边摊食用臭豆腐48小时后，相继自觉乏力、头痛，继而出现复视、眼睑下垂、吞咽和说话困难，以及呼吸困难等症状，初步诊断引起患者此种症状的病原体是","o":["破伤风梭菌","产气荚膜梭菌","肉毒梭菌","艰难梭菌","炭疽杆菌"],"a":2,"e":"肉毒毒素为神经毒素，抑制胆碱能神经末梢释放乙酰胆碱，引起对称性弛缓性麻痹，以眼肌、咽肌受累为先，胃肠道症状轻微。破伤风痉挛毒素阻断抑制性递质释放，表现为牙关紧闭与角弓反张；产气荚膜梭菌α毒素致溶血与组织坏死，引起气性坏疽"},{"q":"某老年男性患者，肺部感染入院。常规治疗后，疗效不佳。考虑到可能出现了耐药性菌株感染。此时，做抗生素敏感试验时，应选择细菌增殖的","o":["迟缓期早期","对数生长期","稳定期后期","稳定期中期","衰亡期早期"],"a":1,"e":"对数生长期细菌形态、染色性与生理活性典型，对抗生素最为敏感，药敏试验与生化鉴定均应取该期细菌。迟缓期细菌代谢尚未活跃，接种后需适应环境；稳定期细菌代谢尚未活跃；与衰亡期活菌数下降、耐药表型改变，结果不可靠"},{"q":"患者，男，29岁。平素体健，自诉1天前面部出现点状充血疹，不痒，畏光流泪，无诱因高热头疼。就诊时查体见耳后、面颈、躯干、四肢见颜色深浅不一的点片状皮疹，压之褪色，结膜充血，咽充血，咽后壁淋巴滤泡增生，口颊黏膜现散在细白沙粒样黏膜斑。血常规白细胞数不高，异常淋巴细胞0.03。血细菌培养（－），麻疹特异性抗体IgM（－）。该患者最可能的诊断是","o":["风疹","鹅口疮","猩红热","伤寒","麻疹"],"a":4,"e":"发热、卡他症状、结膜充血、颊黏膜白色黏膜斑，以及自耳后发际向躯干四肢扩展的皮疹，为麻疹典型过程；特异性IgM在出疹后数日才转阳。风疹皮疹细小、无科氏斑、耳后淋巴结肿大；猩红热皮疹为弥漫充血性、压之退色并伴杨梅舌"},{"q":"患儿，男，5岁，咳嗽3个月余。初起有发热、喷嚏、轻咳等症状。现已热退，但咳嗽日渐加重，尤以夜间为重，为阵发性痉咳伴有鸡鸣样吼声。查体：患儿精神萎靡，面部水肿，眼结膜出血，舌系带溃疡，肺部未闻及啰音。实验室检查：白细胞总数高达30×109/L。经红霉素治疗3天后症状减轻。其最可能感染的病原体是","o":["立克次体","螺旋体","真菌","病毒","细菌"],"a":4,"e":"阵发性痉咳伴鸡鸣样吼声，白细胞高达30×10⁹/L，红霉素治疗有效，为百日咳鲍特菌所致，该菌是革兰阴性球杆菌，属细菌。立克次体专性细胞内寄生、经虱蚤蜱螨传播；螺旋体细长螺旋状、运动活泼；真菌以菌丝与孢子繁殖；病毒无细胞结构、须在活细胞内增殖，抗菌药物无效"},{"q":"患者，女，25岁。外阴红肿、瘙痒、有脓性分泌物，伴尿频、尿痛3天。采集患者分泌物，涂片镜检，中性粒细胞内外均可见G－双球菌。临床诊断为淋病。该患可能经何种途径感染","o":["粪-口途径","呼吸道","性接触","蚊虫叮咬","输血"],"a":2,"e":"淋病奈瑟菌存在于脓性分泌物中，经性接触直接侵犯尿道与宫颈，成人几乎均由此途径感染，潜伏期2～5天。粪-口途径传播霍乱、甲肝等；输血传播HBV、HCV与HIV；蚊虫叮咬传播乙脑、登革热"},{"q":"患儿，男，出生后27天。出生后1天即出现发热，经抗菌治疗，效果不佳。B超检查显示双肾肿大，肾实质内多发大小不等脓腔；取脓肿内容物进行培养，菌落呈黄绿色，镜检可见有隔菌丝，分生孢子梗顶端膨大形成球形顶囊，小梗双层，顶端的分生孢子呈链状排列，表面粗糙。该患儿可能是下列哪种病原体感染","o":["烟曲霉","杂色曲霉","黄曲霉","新型隐球菌","白假丝酵母菌"],"a":2,"e":"黄曲霉菌落呈黄色，镜下顶囊球形或近球形、小梗双层且第一层长并布满顶囊表面，分生孢子球形或梨形、表面有小棘成链排列，与脓液所见相符。烟曲霉顶囊呈烧瓶状、小梗单层，菌落为绿色或深绿色；新型隐球菌为酵母型，墨汁负染见厚荚膜而不形成顶囊；白假丝酵母菌只产生芽生孢子与假菌丝"},{"q":"患者，男，20岁。乏力、低热、咳嗽月余，胸部X片显示在右肺上叶有炎性浸润灶，取痰标本抗酸染色阳性。最可能的诊断是","o":["肺脓肿","大叶性肺炎","葡萄球菌性肺炎","肺结核","肺癌"],"a":3,"e":"结核分枝杆菌抗酸染色阳性，右肺上叶浸润灶，伴低热、乏力、咳嗽月余及痰中带血，符合继发性肺结核。大叶性肺炎由肺炎链球菌引起，急性高热、铁锈色痰；肺脓肿多为厌氧菌混合感染，咳大量脓臭痰并有空洞液平；肺癌痰脱落细胞可查见癌细胞"},{"q":"某地一幼儿园通过采集咽拭子标本及粪便标本，进行RT-PCR病毒核酸筛查发现一例脊髓灰质炎隐性感染病例。对该幼儿园其他儿童，可采取的预防脊髓灰质炎的特异性措施是","o":["注射抗生素","注射胎盘球蛋白或丙种球蛋白","服用脊髓灰质炎减毒活疫苗","注射抗病毒药物","消毒患儿排泄物，严格水和饮食卫生管理"],"a":2,"e":"脊髓灰质炎的特异性预防为口服减毒活疫苗，可诱导肠道局部sIgA与全身免疫、形成群体屏障，应急接种能阻断传播。抗生素与抗病毒药物对病毒性感染无效；胎盘球蛋白与丙种球蛋白为非特异性被动免疫，仅短期保护；消毒与卫生管理属一般预防措施"},{"q":"某患者急起畏寒、高热持续3天，头痛剧烈、全身酸痛、乏力，伴咽痛、干咳（无痰）等呼吸道症状，以及呕吐、腹泻等胃肠道症状。患者所在地近期有H3N2流行感冒的流行。血常规检查显示白细胞总数不高。如初步诊断为流感，可采用的血清学检测方法不包括","o":["ELISA试验","血凝抑制试验","中和试验","血凝试验","胶体金标记免疫层析法"],"a":3,"e":"血凝试验直接检测病毒血凝素，属病毒抗原检测，不属血清学抗体检测。ELISA、血凝抑制试验、中和试验与胶体金免疫层析法均检测血清中特异性抗体，可用于流感诊断与流行病学调查；血凝抑制试验还可区分流感病毒的型别"},{"q":"患儿，男，7岁。发热伴头晕、呕吐、腹痛，嗜睡，精神差，双侧腮腺以耳垂为中心弥漫性肿大，表面皮肤正常，有触痛。双颌下腺轻度肿大，扁桃体Ⅰ度肿大，双侧睾丸肿痛、阴囊肿大。血常规白细胞轻度增高，血尿淀粉酶明显升高。头部CT右侧额叶可见局限性低密度影。该患儿最可能的疾病是","o":["流行性乙型脑炎","结核性脑膜炎","新型隐球菌脑膜炎","流行性脑膜炎","流行性腮腺炎并发脑膜炎及睾丸炎"],"a":4,"e":"腮腺炎病毒经飞沫传播，以腮腺非化脓性肿大为特征，儿童易并发脑膜脑炎，青春期后感染者易并发睾丸炎或卵巢炎。乙型脑炎无腮腺肿大，以高热、惊厥为主；化脓性腮腺炎为细菌感染，挤压腺体可见脓液，血淀粉酶不升高"},{"q":"患者，男，21岁。畏寒、高热，咳嗽伴左胸痛5天。查体：BP 80/50mmHg，心率120次/min。胸部X线片见左肺下叶大片状致密影。实验室检查：血WBC 12.2×109/L。该患者最可能感染的病原体是","o":["肺炎支原体","肺炎链球菌","军团菌","金黄色葡萄球菌","结核分枝杆菌"],"a":1,"e":"青年男性寒战高热、咳嗽胸痛，X线见左下肺大片致密影，伴血压下降，为肺炎链球菌肺炎。肺炎支原体肺炎以干咳为主、肺部体征轻；军团菌肺炎多伴腹泻、意识障碍与低钠血症；金黄色葡萄球菌肺炎常继发于流感，易形成肺脓肿与脓气胸；结核分枝杆菌感染为慢性低热、盗汗"},{"q":"患者，女，35岁，患肺结核已3年，治疗不规则。2天前受凉后发热，体温38℃，体检无明显异常。胸片示两上肺斑片状阴影，伴不规则透亮区。为判断肺结核是否活动，可采取下列哪种方法","o":["痰结核杆菌检查","革兰染色","Elek平板毒力实验","糖发酵试验","胆汁溶解试验"],"a":0,"e":"判断肺结核是否活动，关键在痰中检出结核分枝杆菌，痰涂片抗酸染色与培养阳性提示排菌与活动性。革兰染色不能使分枝杆菌着色；Elek平板毒力试验用于白喉棒状杆菌产毒株鉴定；糖发酵试验用于肠杆菌科生化鉴定；胆汁溶解试验用于鉴别肺炎链球菌与甲型溶血性链球菌"},{"q":"一个5岁男孩因发烧、游走性关节炎和心肌炎而入院，该男孩出现严重的喉痛，伴发热。入院前两天，出现面部、颈部和四肢的无意识、无目的、不适当的运动，实验室检查显示白细胞增多，蛋白水平升高，血沉速度升高，常规血培养结果阴性，但患者血清中发现高滴度抗链球菌溶素O抗体。患者出现心脏损害的主要原因是","o":["链球菌溶素O介导的心脏组织的直接损伤","白喉毒素侵犯心肌细胞和神经细胞","破伤风痉挛毒素侵犯心瓣膜和神经细胞","由抗链球菌抗体与心瓣膜抗原结合引起的免疫损伤","细菌在心瓣膜上生长繁殖"],"a":3,"e":"A群链球菌的M蛋白与心肌、心瓣膜存在交叉抗原，抗M蛋白抗体与瓣膜组织结合后激活补体，造成Ⅱ型超敏反应性免疫损伤；菌体抗原抗体复合物沉积血管基底膜则为Ⅲ型。血培养阴性说明并非细菌在瓣膜上繁殖，可排除感染性心内膜炎"},{"q":"患者，男，23岁。乏力，食欲缺乏，尿黄4天。双侧颈部淋巴结肿大，肝略大，脾肋下6cm。骨髓穿刺提示异型淋巴细胞＞50%，VCA-IgG（＋）。最可能的诊断是","o":["淋巴组织增生性疾病","急性感染性淋巴细胞增多症","急性淋巴细胞性白血病","病毒性肝炎","传染性单核细胞增多症"],"a":4,"e":"发热、咽痛、淋巴结与肝脾肿大，骨髓异型淋巴细胞超过50%，VCA-IgG阳性，为EBV所致传染性单核细胞增多症。急性淋巴细胞白血病骨髓为原始淋巴细胞增生，而非异型淋巴细胞；病毒性肝炎以转氨酶升高与黄疸为主；淋巴组织增生性疾病需病理诊断，无VCA抗体依据"},{"q":"患者，女，38岁。因发热、黄疸、腹胀、乏力入院，诊断为“急性甲型肝炎”。引起该病的病原体的主要传播途径是","o":["血液传播","消化道传播","呼吸道传播","密切接触传播","性接触传播"],"a":1,"e":"甲型肝炎病毒经粪-口途径传播，污染水源与食物（如毛蚶）可引起暴发流行，1988年上海因食用未煮熟的毛蚶造成30余万例发病。乙型、丙型、丁型肝炎病毒主要经血液、性接触与母婴传播；呼吸道传播是流感、麻疹等呼吸道病毒的途径"},{"q":"对某腹泻患者进行粪便培养，可疑菌落镜检到革兰染色阴性中等大小的杆菌，在半固体培养基中扩散生长。由此可推断该菌具有的结构为","o":["菌毛","荚膜","性菌毛","鞭毛","芽孢"],"a":3,"e":"半固体培养基中沿穿刺线向四周扩散生长，说明细菌借鞭毛在低黏度介质中游动；无鞭毛菌只沿穿刺线呈线状生长。菌毛与荚膜不提供运动能力，荚膜为抗吞噬结构；性菌毛介导接合传递质粒；芽孢为休眠体，与运动无关"},{"q":"一患者因咳嗽、咯血就诊，痰涂片染色镜检为结核分枝杆菌阳性。请问该菌应采用的染色方法是","o":["革兰染色","复红染色","棉兰染色","抗酸染色","墨汁染色"],"a":3,"e":"结核分枝杆菌细胞壁富含分枝菌酸，苯酚复红加温染色后能抵抗3%盐酸乙醇脱色，经亚甲蓝复染呈红色，为抗酸染色阳性，是痰涂片诊断的基础。革兰染色不易使其着色；棉蓝染色用于真菌；墨汁负染用于隐球菌荚膜；单纯复红染色不能显示抗酸性"},{"q":"患者，女，35岁。近5天出现乏力、厌油、肝大及尿色加深，诊断为“急性乙型肝炎”。该患者血液存在的物质中，具有感染性的成分是","o":["Dane颗粒","小球形颗粒","管形颗粒","HBeAg","HBV-DNA"],"a":0,"e":"Dane颗粒为完整HBV，直径42nm，含环状双股DNA与DNA聚合酶，是具感染性的病毒颗粒。小球形与管形颗粒仅由HBsAg组成、不含核酸，无感染性；HBeAg为可溶性蛋白，是复制活跃标志；HBV-DNA检测反映病毒复制水平"},{"q":"患儿，女，8岁。咽痛、干咳、胸痛、发热3天，体温38、5℃，刺激性咳嗽明显。查体：右肺呼吸音低，无啰音。血常规：白细胞9.0 × 109/L，中性粒细胞65％。X线检查显示左下肺薄片状阴影。冷凝集试验结果阳性。最可能的诊断为","o":["腺病毒肺炎","呼吸道合胞病毒肺炎","肺炎支原体肺炎","金黄色葡萄球菌肺炎","肺炎链球菌肺炎"],"a":2,"e":"学龄儿童刺激性干咳、发热、肺部体征轻而X线见薄片状阴影，冷凝集试验阳性，为肺炎支原体肺炎。腺病毒与呼吸道合胞病毒肺炎多见于婴幼儿、有喘息或高热；金黄色葡萄球菌肺炎易形成肺脓肿与脓气胸；肺炎链球菌肺炎有肺实变与铁锈色痰"},{"q":"某5个月婴儿，便秘、头颈部肌肉软弱、吮乳无力、吞咽困难入院。查：眼睑下垂，全身肌张力减退。入院后多项检查提示“婴儿肉毒病”。引起此病的病原菌","o":["在有氧和无氧环境中都能生长","菌体内缺少过氧化物酶","属于自养菌范畴","通过光合作用获得能量","最适生长温度为10～20℃"],"a":1,"e":"婴儿肉毒病由摄入肉毒梭菌芽胞、芽胞在肠道发芽产毒所致，该菌为专性厌氧菌，缺乏过氧化氢酶与过氧化物酶，不能清除有毒氧基团，只能于无氧环境繁殖。有氧无氧均能生长者如兼性厌氧的肠杆菌科细菌；自养与光合作用为自养菌特征；其最适生长温度为30～35℃"},{"q":"患儿，女，5岁，饭后6小时出现恶心、呕吐和腹泻等症状，粪便直接涂片显示革兰阳性球菌，进一步分离培养凝固酶玻片凝集试验阳性。可疑感染的细菌为","o":["A群链球菌","金黄色葡萄球菌","表皮葡萄球菌","腐生性葡萄球菌","奈瑟球菌"],"a":1,"e":"饭后6小时呕吐腹泻，粪便涂片见革兰阳性球菌，凝固酶玻片凝集阳性，为金黄色葡萄球菌肠毒素食物中毒。A群链球菌触酶阴性、呈链状排列且不产肠毒素；表皮葡萄球菌与腐生葡萄球菌凝固酶阴性、不产肠毒素；奈瑟球菌为革兰阴性双球菌"},{"q":"患儿，男，4岁。发热，精神差，营养良好，口腔黏膜现多个水疱状病变，双手和脚掌可见红色斑丘疹，伴口腔黏膜溃疡，呈昏睡状态，对外界刺激几乎无反应。其所在幼儿园近期有类似病例出现。该患儿最可能的诊断是","o":["手足口病","水痘","麻疹","带状疱疹","风疹"],"a":0,"e":"肠道病毒71型与柯萨奇A16型经粪-口及呼吸道传播，引起手、足、口腔疱疹，可伴脑干脑炎与嗜睡等重症表现，托幼机构易聚集发病。水痘皮疹呈向心性分布、疱液含多核巨细胞；麻疹有科氏斑及全身斑丘疹"},{"q":"患者，男，20岁，咳嗽数周。1个月前开始感到疲劳，食欲减退，发热2周后咳痰中带血丝，体重减轻，体温38℃。临床怀疑患肺结核，取痰做下列处置，哪项是错误的","o":["做结核菌素试验","痰浓缩集菌涂片进行抗酸染色","PCR查结核分枝杆菌核酸","痰结核分枝杆菌培养","痰培养物接种豚鼠进行动物实验"],"a":0,"e":"结核菌素试验阳性仅提示曾感染结核或接种过卡介苗，不能确诊活动性肺结核，对已怀疑肺结核者无诊断价值。痰抗酸染色、分枝杆菌培养与PCR查核酸可直接检出病原；豚鼠接种可鉴定菌株致病力"},{"q":"患儿，男，5岁，随母亲旅游时在外就餐，吃未煮透牛排之后，出现发烧、呕吐、剧烈腹痛、大便次数增加伴血便，同时血小板减少。判断其可能的细菌感染是","o":["伤寒沙门菌","鲍氏志贺菌","肠出血性大肠埃希菌","痢疾杆菌","霍乱弧菌"],"a":2,"e":"肠出血性大肠埃希菌产志贺毒素，经未煮透牛肉传播，引起剧烈腹痛与血便，约10%儿童并发溶血尿毒综合征，出现血小板减少、溶血性贫血与急性肾衰竭。伤寒沙门菌以持续发热、玫瑰疹为特征；痢疾志贺菌致脓血便伴里急后重，少见血小板减少"},{"q":"医院接诊一对父子，自述连续3日食用自制瓶装酸肉作为晚餐，第3日父亲开始出现恶心、呕吐、腹泻、腹痛等症状。第4日早晨儿子也开始出现上述症状，并伴有视物模糊。父子二人在当地诊所治疗后好转，但父亲从第6日开始出现吞咽困难、睁眼困难、视力模糊加重、言语不清及声音嘶哑、饮水呛咳等症状。初步诊断为肉毒梭菌感染所致，下面哪项实验可以确诊","o":["取可疑食物作为样本，进行染色镜检，发现芽孢杆菌","将患者血清与不同型别的肉毒梭菌孵育，随后与对照组分别注射小鼠。根据小鼠存活状况判断所感染菌株","取患者消化道排泄物为标本，接种于SS选择培养基中，发现无色透明菌落","患者排泄物中所含微生物为抗酸染色阳性细菌","取可疑食物进行分离培养，选取可疑菌落，接种于牛奶培养基中，出现汹涌发酵现象"],"a":1,"e":"肉毒毒素型别鉴定依靠小白鼠中和试验，将标本与各型抗毒素作用后接种小鼠，观察保护情况以定型。染色镜检见芽胞杆菌只能提示梭菌属，不能分型；SS培养基用于肠道杆菌；汹涌发酵是产气荚膜梭菌在牛乳培养基中的表现"},{"q":"患者3天前开始感觉前额痛，入院当天上午高热、寒战，下午起开始出现神志不清、晕厥，随即送入医院。查体：T 41℃，BP 70/30mmHg，P 140次/min，R 24次/min，患者间断清醒，躯干有几处淤斑，鼻腔、口腔有出血，颈部柔软，无脑膜刺激征，心脏未闻及杂音，腹部除见左上四分之一象限脾切除手术瘢痕外无异常发现。胸部X光：心、肺无异常。实验室检查：血培养可见革兰染色阳性、柳叶刀状双球菌。血琼脂再次培养可见细小、半透明的、呈α-溶血环的菌落，该菌可被胆汁溶解，并可被奥普托辛（optochin）抑制。用含有抗83型肺炎链球菌的抗体的全血清做荚膜肿胀试验阳性。最有可能引起该患者败血症的病原菌是","o":["脑膜炎球菌","肺炎链球菌","流感嗜血杆菌","A群链球菌","金黄色葡萄球菌"],"a":1,"e":"肺炎链球菌为革兰阳性柳叶刀状双球菌，血平板呈α溶血，可被胆汁溶解、对奥普托辛敏感，荚膜肿胀试验可确定血清型。脑膜炎奈瑟菌为革兰阴性双球菌、氧化酶阳性；A群链球菌杆菌肽敏感、不被胆汁溶解；流感嗜血杆菌为革兰阴性小杆菌、需X和V因子"},{"q":"8岁儿童因突发剧烈恶心、呕吐以及腹泻紧急入院就诊。患儿家长诉起病前4小时参加家庭生日聚会，患儿食用两大块生日蛋糕。检查患儿体温正常，入院观察后病情很快好转，未见明显后遗症。采集患儿呕吐物检测，染色镜检发现革兰阳性球菌。该患儿很可能是下列哪种病原菌感染","o":["淋病奈瑟菌","肺炎链球菌","金黄色葡萄球菌","表皮葡萄球菌","A群链球菌"],"a":2,"e":"食生日蛋糕后4小时出现剧烈呕吐与腹泻，体温正常、病程短、恢复快，为金黄色葡萄球菌肠毒素所致食物中毒，该毒素耐热，一般加热不能破坏。淋病奈瑟菌与肺炎链球菌不引起食物中毒；表皮葡萄球菌凝固酶阴性、不产肠毒素；A群链球菌为链状排列、β溶血"},{"q":"患者一个月前感到疲劳、食欲减少、体重减轻、发热、咳嗽、痰带血丝。欲取痰标本涂片染色镜检，对该菌应采用的染色方法应该首选","o":["革兰氏染色","抗酸染色","棉兰染色","复红染色","墨汁染色"],"a":1,"e":"结核分枝杆菌细胞壁富含分枝菌酸，能与石炭酸复红牢固结合，经3%盐酸乙醇脱色仍呈红色，为抗酸染色阳性。革兰染色对其着色不良、无鉴别意义；墨汁染色用于观察隐球菌荚膜；棉兰染色用于真菌"},{"q":"某建筑工地工人被掉下的钢筋扎入手臂，送入急诊室治疗，对伤口进行正确得当的处理后，收入院继续观察治疗。住院期间，为确诊该患者是否存在破伤风细菌的感染，实验室应采用的细菌培养基是","o":["罗氏培养基","吕氏培养基","庖肉培养基","双糖铁培养基","巧克力色培养基"],"a":2,"e":"破伤风梭菌为专性厌氧菌，庖肉培养基含肉渣并覆凡士林隔绝空气，最适于其厌氧培养，接种后置37℃厌氧环境观察生长。罗氏培养基用于结核分枝杆菌；吕氏血清斜面用于白喉棒状杆菌；巧克力色培养基用于奈瑟菌与流感嗜血杆菌"},{"q":"患儿，女，3岁。持续性发热，腹泻，不对称性麻痹，右下肢肌力Ⅰ级，腱反射消失，病理征阴性；60天后残留麻痹，肌肉萎肌肉萎缩、腱反射减弱或消失，无病理征。该患儿最可能患的疾病是","o":["无菌性脑膜炎","流行性脑脊髓膜炎","新型隐球菌脑膜炎","流行性乙型脑炎","脊髓灰质炎"],"a":4,"e":"发热后出现不对称性弛缓性瘫痪，右下肢肌力Ⅰ级、腱反射消失而病理征阴性，60天后仍残留肌肉萎缩，为脊髓灰质炎病毒侵犯脊髓前角运动神经元所致。吉兰-巴雷综合征多为对称性上升性瘫痪并有前驱感染；流脑有脑膜刺激征与瘀斑；隐球菌脑膜炎墨汁染色阳性；乙脑有意识障碍与病理征"},{"q":"患者，男，20岁，农民，高热、全身肌肉酸痛、乏力7天。查体：眼结膜充血，巩膜黄染，肝肋下1、5cm，腓肠肌压痛明显。尿蛋白（＋）。血清胆红素和丙氨酸转氨酶均明显升高。肥达反应O 1∶40、H 1∶80，钩体显微镜凝集试验1∶400。外斐反应OX2、OX19、OXK均小于1∶80。最可能的诊断是","o":["伤寒","钩端螺旋体病","甲型急性黄疸型病毒性肝炎","斑疹伤寒","流行性出血热"],"a":1,"e":"钩端螺旋体病表现为发热、眼结膜充血、腓肠肌压痛与黄疸，显微镜凝集试验效价1∶400有诊断意义。伤寒肥达反应滴度低且无腓肠肌压痛；斑疹伤寒需外斐反应OX19阳性；肾综合征出血热以出血、肾损害为主，腓肠肌压痛与黄疸少见"},{"q":"患者，男，有不洁性交史。2个月前出现生殖器皮肤的无痛性溃疡，1个月后自然愈合。近日出现全身皮肤红疹，伴有淋巴结肿大。该患者可能患有","o":["猩红热","梅毒","麻疹","性病淋巴肉芽肿","风疹"],"a":1,"e":"不洁性交后出现无痛性硬下疳并自行愈合，1个月后全身皮疹伴淋巴结肿大，为梅毒螺旋体所致Ⅱ期梅毒。猩红热有草莓舌、口周苍白圈与弥漫充血性皮疹；麻疹有卡他症状与科氏斑；性病淋巴肉芽肿为一侧腹股沟淋巴结化脓、无全身皮疹；风疹皮疹伴耳后淋巴结肿大，无硬下疳史"},{"q":"某院外科医生在给一位乙型肝炎病毒（HBV）携带者手术时，不慎被手术剪刀割伤手指。为预防乙型肝炎病毒感染，应首先采取的措施是","o":["注射乙型肝炎疫苗","注射抗生素","注射丙种球蛋白","注射HBIg","注射α-干扰素"],"a":3,"e":"被HBV污染锐器刺伤后应立即注射乙型肝炎免疫球蛋白，直接提供抗-HBs中和病毒，属被动免疫，越早越好。乙肝疫苗为主动免疫，产生抗体需数周，单用不足以阻断本次暴露；丙种球蛋白抗-HBs含量低；抗生素与干扰素对暴露后预防无效；可同时接种疫苗建立长期免疫"},{"q":"一艾滋病患者，最近出现发热、咳嗽、胸闷等肺部感染症状。继发感染应优先考虑的最常见病原体是","o":["李斯特菌","巨细胞病毒","肺孢子菌","白假丝酵母菌","结核分枝杆菌"],"a":2,"e":"艾滋病患者CD4+T细胞低于200个/μl时，肺孢子菌肺炎最常见，表现为发热、干咳、胸闷及双肺磨玻璃影。结核分枝杆菌感染多有空洞或粟粒状阴影；巨细胞病毒肺炎多见于CD4+T细胞低于50个/μl者；白念珠菌以口腔食管炎为主"},{"q":"患者，男，33岁。自述每次吃饭后都出现反酸、腹胀和隐痛的现象。曾在当地的医院做过胃镜检查，诊断为胃炎。氧化酶、过氧化氢酶、脲酶分解试验均呈阳性。此患者可能感染的病原体可能为","o":["空肠弯曲菌","幽门螺杆菌","解脲脲原体","乙型肝炎病毒","金黄色葡萄球菌"],"a":1,"e":"幽门螺杆菌脲酶、氧化酶与过氧化氢酶均阳性，定植胃黏膜引起慢性胃炎与消化性溃疡，尿素酶分解尿素产氨以中和胃酸。空肠弯曲菌脲酶阴性、需微需氧培养；金黄色葡萄球菌氧化酶阴性，且不寄居胃黏膜"},{"q":"一烧伤患者入院后2天出现寒战、高热，体温40～41℃，呈弛张热，创面渗出绿色脓液伴有生姜味。实验室检查：白细胞总数和中性粒细胞升高，核左移并出现细胞内中毒性颗粒，嗜酸性粒细胞减少。临床诊断败血症，其病原菌可能是","o":["大肠埃希菌","金黄色葡萄球菌","变形杆菌","铜绿假单胞菌","白假丝酵母菌"],"a":3,"e":"烧伤创面感染，脓液呈绿色并有生姜样臭味，弛张热，为铜绿假单胞菌败血症，该菌产生绿脓菌素以及内毒素、外毒素A。大肠埃希菌脓液无绿色素；金黄色葡萄球菌脓汁稠厚呈金黄色；变形杆菌迁徙生长并有氨味；白假丝酵母菌为真菌，脓液稀薄呈渣样"},{"q":"患儿，男，6岁，未接种过DPT疫苗，春季末因咳嗽于呼吸科就诊。2周前，患儿出现咳嗽和鼻塞，症状持续，无发热和寒战。3天前，患儿出现夜间咳醒，咳嗽剧烈，咳嗽后出现呕吐和呼吸困难，扁桃体无肿大，无脓性分泌物。次日，患儿咳嗽依然存在，再次因剧烈咳嗽而咳醒，咳嗽持续约10分钟，吸气出现吼声。该患儿最可能感染何种病原体","o":["百日咳鲍特菌","肺炎支原体","白喉棒状杆菌","肺炎链球菌","结核分枝杆菌"],"a":0,"e":"未接种DPT的学龄儿童，卡他期后出现阵发性痉咳、咳后呕吐与吸气吼声，为百日咳典型表现。肺炎支原体肺炎以刺激性干咳为主，无吼声与咳后呕吐；白喉有咽部灰白色假膜与扁桃体肿大；肺炎链球菌肺炎起病急、有高热与肺实变体征；结核分枝杆菌感染为低热、盗汗、消瘦的慢性过程"},{"q":"患儿，男，12岁。3周前，不慎被锐器扎伤右足根部，未经医生处理，自行包扎。两周后张嘴感觉下颌关节发紧，住院治疗。查体：T 38.6℃，苦笑面容，口角稍下垂，牙关紧，张口困难，颜面、口唇无发绀，脊柱和四肢无畸形，上肢活动尚可，下肢步态不稳，迈步困难，关节活动不利，右下肢肌肉间断性抽搐，足跟伤口周围红肿明显，有脓性分泌物。引起该病的病原菌生物学特点是","o":["不形成芽孢","生长最适pH为8.8～9","最适生长温度为22℃","能够进行需氧呼吸","唯一产能途径是糖酵解"],"a":4,"e":"破伤风梭菌为专性厌氧菌，缺乏细胞色素与过氧化物酶，只能经糖酵解途径产能，不进行氧化磷酸化。最适生长温度37℃、最适pH7.0～7.4；该菌能形成顶端芽胞，故不形成芽胞、最适温度22℃等说法均不符"},{"q":"某肝炎患者，血清学检查结果为：抗HAV IgM（－），抗HBsAb（＋），抗HCV-IgG（＋），抗HDV-IgM（－），抗HEV-IgM（－）。最可能感染的病原体是","o":["甲型肝炎病毒","乙型肝炎病毒","丙型肝炎病毒","丁型肝炎病毒","戊型肝炎病毒"],"a":2,"e":"抗HCV-IgG阳性而甲、丁、戊型标志均阴性，抗-HBs阳性提示疫苗接种或既往感染已获免疫，故现症感染为丙型肝炎病毒。抗HAV IgM阴性排除甲肝；抗HBs阳性而无HBsAg，不支持乙肝现症感染；抗HDV IgM阴性排除丁肝；抗HEV IgM阴性排除戊肝"},{"q":"患者，男，32岁，消瘦，出现腹胀、轻微腹泻达3个月，有同性恋史。体检发现鹅口疮。首先考虑应做的检查是","o":["乙肝病原学检查","粪便培养检测肠道致病菌","消化道钡餐造影","肥达反应检测","HIV抗体检测"],"a":4,"e":"消瘦、慢性腹泻3个月伴鹅口疮，有同性恋史，提示细胞免疫缺陷，应首选HIV抗体检测明确是否感染。乙肝病原学检查不能解释鹅口疮与慢性腹泻；粪便培养只针对肠道致病菌；肥达反应用于肠热症；钡餐造影无助于病原诊断；鹅口疮为念珠菌感染，本身即是免疫低下的信号"},{"q":"患儿，2月龄。喂服第1粒脊髓灰质炎减毒活疫苗后，第16天开始持续性发热，第21天发现右下肢活动不便。查体见右下肢肌力Ⅰ级，膝反射减弱，其余肢体无异常。初步诊断为疫苗相关麻痹性脊髓灰质炎（VAPP），为避免类似临床不良事件发生，可采取的措施是","o":["不使用减毒活疫苗","不使用灭活疫苗","先使用灭活疫苗，再使用减毒活疫苗","先使用减毒活疫苗，再使用灭活疫苗","灭活疫苗和减毒活疫苗同时使用"],"a":2,"e":"疫苗相关麻痹性脊髓灰质炎由口服减毒活疫苗株在肠道内回复突变、侵袭脊髓前角所致，预防关键在于先用灭活疫苗建立基础免疫，再服减毒活疫苗，以消除首剂服苗的麻痹风险。单用灭活疫苗肠道局部免疫弱；先服活疫苗再加灭活疫苗仍不能避免首剂发病；两苗同时接种无此方案；不用活疫苗则失去肠道免疫与群体屏障"},{"q":"患者，女，58岁。进食自制豆豉后3天，觉头晕、复视、乏力、眼睑下垂、吞咽困难、呕吐、气短、腹胀、便秘、尿潴留等，在当地治疗无效，上述症状加重，并出现全身瘫痪，急转院治疗。查体：言语困难、眼睑下垂、眼球水平移动困难，双瞳孔直径8mm，光反射极迟钝，颈软，心肺听诊无异常，肠鸣音减弱。初步诊断该患者是","o":["风湿热","毒性休克综合征","食物肉毒中毒","破伤风","炭疽"],"a":2,"e":"进食自制豆豉后出现头晕、复视、眼睑下垂、吞咽困难与全身瘫痪，瞳孔散大、肠鸣音减弱，为肉毒毒素阻断胆碱能神经末梢释放乙酰胆碱所致。破伤风为肌强直痉挛而非弛缓性麻痹；风湿热为关节与心脏受累；毒性休克综合征有高热、皮疹与低血压；炭疽有皮肤焦痂或肺门淋巴结肿大"},{"q":"患儿，女，5岁，因高热、意识模糊而入院。查体发现患儿面色苍白，昏迷，时有惊厥，两瞳孔不等大，呼吸微弱。粪检有脓细胞4个，白细胞数16×109/L，脑脊液正常。常规粪便培养发现有革兰阴性杆菌，无动力。临床诊断为中毒型痢疾。该患儿所感染病原体的主要致病物质是","o":["芽孢","鞭毛","菌毛","内毒素和外毒素","外毒素"],"a":3,"e":"志贺菌的致病物质包括菌毛（黏附结肠黏膜）、内毒素（破坏肠黏膜、致微循环障碍与中毒性休克）及志贺毒素（外毒素，抑制蛋白合成并致神经症状）。芽胞与鞭毛非志贺菌所有；单用外毒素不能解释内毒素引起的高热、休克与DIC"},{"q":"20岁青年摘除扁桃体后，发热，出现心力衰竭。采血培养细菌，血平板有草绿色溶血环小菌落形成。涂片染色为G＋链状排列球菌，诊断为甲型溶血性链球菌心内膜炎。下列还有哪种菌能形成草绿色溶血环菌落","o":["金黄色葡萄球菌","乙型溶血链球菌","表皮葡萄球菌","丙型链球菌","肺炎链球菌"],"a":4,"e":"甲型溶血性链球菌形成草绿色溶血环，肺炎链球菌同样呈α溶血，且胆汁溶菌与奥普托欣试验阳性、分解菊糖，可资鉴别。金黄色葡萄球菌与表皮葡萄球菌呈β溶血或不溶血；乙型溶血链球菌呈完全透明溶血环；丙型链球菌无溶血环"},{"q":"患儿，男，7岁，突起高热、头痛、呕吐及意识障碍，脑膜刺激征阳性，血清学检查显示乙型脑炎病毒IgM（＋）。对于该病特点的描述，正确的是","o":["患者及隐性感染者为主要传染源","库蚊为传播媒介和储存宿主","绝大多数表现为显性感染","绝大多数患者可出现中枢神经系统的症状","不易获得牢固的免疫力"],"a":1,"e":"乙型脑炎病毒由三带喙库蚊叮咬传播，蚊可经卵传递并越冬，既是传播媒介又是储存宿主。主要传染源是幼猪，而非患者与隐性感染者；人群感染后绝大多数为隐性感染；仅少数出现中枢神经系统症状；病后免疫力持久牢固"},{"q":"患者，女，40岁，长期使用外用洗剂冲洗阴道，现出现外阴及阴道瘙痒，白带增多，宫颈分泌物直接涂片镜检如图所示，将白带接种于沙保培养基上培养3天长出乳白色奶油状菌落，菌落下有菌丝样结构生长，该病原体最可能是","o":["类白喉棒状杆菌","新型隐球菌","白假丝酵母菌","苍白密螺旋体苍白亚种","解脲脲原体"],"a":2,"e":"本题原题配有图片，图片未随文档保留，以下解析依文字线索推断：题干涉及图片/信息缺失，无法作答。白念珠菌在沙保培养基上形成乳白色奶油状酵母型菌落，镜下见芽生孢子与假菌丝；长期阴道冲洗破坏正常菌群后易发病。新型隐球菌有宽厚荚膜、墨汁染色阳性；苍白密螺旋体需镀银染色且不能人工培养\n\n官方题库中缺失图片"},{"q":"患者，男，65岁。因乏力、厌油、呕吐、腹胀及黄疸入院治疗，诊断为“急性乙型肝炎”。在其感染过程中，参与肝细胞损伤的免疫病理反应最可能包括","o":["Ⅰ型和Ⅱ型超敏反应","Ⅱ型和Ⅲ型超敏反应","Ⅰ型和Ⅳ型超敏反应","Ⅱ型和Ⅳ型超敏反应","Ⅰ型、Ⅱ型和Ⅲ型超敏反应"],"a":1,"e":"乙型肝炎的肝细胞损伤由免疫病理介导，抗病毒抗体与肝细胞表面抗原结合激活补体属Ⅱ型超敏反应，抗原抗体复合物沉积于血管内皮属Ⅲ型。Ⅰ型由IgE介导，见于过敏性疾病与寄生虫感染；Ⅳ型为T细胞介导的迟发型超敏，典型见于结核分枝杆菌等胞内菌感染"},{"q":"患者，男，25岁，广州籍民工，因持续发热10天入院。主诉12天前低烧，后体温逐渐升高持续39～40.2℃，腹部饱胀，呕吐，腹泻，肝肋下触及1cm，脾肋下触及2cm。血常规：白细胞3.1×109/L。对该患者进行进一步诊断和治疗方案，哪项是不正确的","o":["肥达试验进一步确诊","进行血液或粪便培养","静脉滴注谷氨酸或精氨酸","及时补液，抗菌治疗","标本分离物接种于肠道选择性培养基"],"a":2,"e":"伤寒治疗以病原治疗与补液支持为主，喹诺酮类或第三代头孢为常用药物，血、骨髓、粪便培养及肥达试验有助诊断。静脉滴注谷氨酸或精氨酸用于肝性脑病降血氨，对伤寒无治疗作用，还可能加重代谢负担。肠道选择性培养基用于分离沙门菌"},{"q":"幼儿园刚放暑假，一名3岁男孩突然出现水样腹泻，伴有咽痛、咳嗽和轻度发热，无呕吐。最可能的感染病原体是","o":["G组轮状病毒","B组轮状病毒","肠道腺病毒","杯状病毒","柯萨奇病毒"],"a":2,"e":"肠道腺病毒40、41型经粪-口与呼吸道传播，腹泻为水样便或稀便，伴咽痛、咳嗽与低热。轮状病毒以呕吐、蛋花汤样便为主，呼吸道症状少；杯状病毒（诺如病毒）多在集体机构暴发、呕吐突出、病程仅1～3天"},{"q":"某患者剧烈咳嗽入院，怀疑病原菌感染，经鲍-金培养基培养后形成细小、光滑、表面隆起、灰白色、不透明的珍珠样菌落，最可能是哪种病原体感染","o":["破伤风梭菌","白喉棒状杆菌","百日咳鲍特菌","结核分枝杆菌","流感嗜血杆菌"],"a":2,"e":"鲍-金培养基含甘油、马铃薯浸液与血液，百日咳鲍特菌在其上形成细小、光滑、隆起、灰白不透明的珍珠样菌落，为典型培养特征。白喉棒状杆菌用吕氏血清培养基、菌落灰黑色；结核分枝杆菌用罗氏培养基、生长缓慢呈菜花状；流感嗜血杆菌需巧克力平板并现卫星现象；破伤风梭菌专性厌氧，普通培养不生长"},{"q":"患者，女，35岁，农民，突起高热，伴头痛、肌痛、眼眶痛，胸颈部可见斑片状皮疹，初步诊断为“登革热”，该病最可能的传染源是","o":["幼猪及携带病毒的家畜家禽","患者及隐性感染者","鼠类等啮齿动物","白纹伊蚊","硬蜱"],"a":1,"e":"登革病毒经埃及伊蚊、白纹伊蚊传播，传染源为患者及隐性感染者，发病前1天至发病后5天的病毒血症期具传染性。白纹伊蚊是传播媒介而非传染源；鼠类是肾综合征出血热的传染源；幼猪是乙型脑炎病毒的扩增宿主"},{"q":"一位在珠海拱北口岸入境的旅客出现剧烈腹痛、腹泻、呕吐等症状。经流行病学调查及患者临床症状和体征，结合实验室检测结果，确定该患者为副溶血性弧菌所致。该菌的培养特性是","o":["培养时应在培养基中加入黄绿","必须采用厌氧培养基培养","只能在巧克力色培养基上生长","培养3～4周形成肉眼可见菌落","在无盐培养基上不能生长"],"a":4,"e":"副溶血性弧菌具嗜盐性，在含35g/L氯化钠的培养基中生长最佳，无盐不能生长，氯化钠高于80g/L亦不能生长。霍乱弧菌可在无盐培养基生长；厌氧培养为梭菌属的要求；巧克力色平板用于奈瑟菌与流感嗜血杆菌"},{"q":"一名未接种过卡介苗的健康中年人，做结核菌素试验是阳性，下列哪项解释不正确","o":["需要接种卡介苗","不需要接种卡介苗","对结核病有免疫力","细胞免疫功能正常","感染过结核分枝杆菌"],"a":0,"e":"未接种卡介苗者PPD阳性说明已感染过结核分枝杆菌，特异性T细胞介导的Ⅳ型超敏反应已建立，细胞免疫功能正常，对结核具一定免疫力，无需再接种卡介苗。需接种卡介苗的是PPD阴性的未感染者。该试验不能区分自然感染与卡介苗接种，故接种成功者亦呈阳性，本例未接种，其阳性只能归于感染"},{"q":"某患者，肌肉酸痛，高热，剧烈头痛，入院。体格检查、外斐反应结果诊断为立克次体感染。试问预防立克次体病最重要的是","o":["注射疫苗","服用抗生素","控制和消灭传播媒介和储存宿主","灭蚊、灭蝇，防止蚊蝇叮咬","避免与病人接触"],"a":2,"e":"立克次体病为节肢动物传播的自然疫源性疾病，防制核心是灭虱、灭蚤、灭蜱、灭螨与灭鼠，切断传播环节。疫苗保护力有限、非首选；抗生素用于治疗而非预防；灭蚊灭蝇针对蚊媒病毒病，如乙脑与登革热"},{"q":"患者，男，46岁，务农。入院前半个月，患者打赤脚在地里挖荸荠，当时不慎损伤右足大脚趾皮肤，但未作处理，伤口自行愈合。因乏力、头晕、头痛、咀嚼无力、反射亢进、肌肉牵拉、抽搐及强直、张口不便，入院治疗。体温38.5℃，外周血白细胞13×109/L。初步怀疑该男子是由哪种病原体感染致病","o":["产气荚膜梭菌","破伤风梭菌","肉毒梭菌","炭疽芽孢杆菌","麻风分枝杆菌"],"a":1,"e":"赤脚劳动致皮肤损伤，泥土中破伤风梭菌芽胞侵入厌氧伤口发芽产毒，毒素沿神经轴突上行，出现咀嚼无力、张口不便、肌强直与反射亢进。产气荚膜梭菌引起气性坏疽、局部有捻发感；肉毒梭菌引起弛缓性麻痹；炭疽芽孢杆菌引起皮肤焦痂与水肿；麻风分枝杆菌侵犯皮肤与外周神经"},{"q":"某急性肝炎患者，血清学检查显示HBsAg（＋），HBeAg（＋），抗-HBc IgM（＋）。以下对于HBeAg的叙述，错误的是","o":["血清阳性表示传染性高","存在于Dane颗粒的最外层","疾病慢性化可表现为血清持续阳性","化学成分为可溶性蛋白","其相应抗体有一定保护作用"],"a":1,"e":"HBeAg为前C基因编码的可溶性蛋白，游离于血清中，并非Dane颗粒表面成分；其阳性提示病毒复制活跃、传染性强。Dane颗粒最外层为HBsAg组成的包膜；抗-HBe有一定保护作用；慢性化时HBeAg可长期阳性"},{"q":"患者，男，65岁。两周前体检发现肝酶升高，约为正常上限的三倍，无黄疸，肝脾无肿大，无门脉高压。自诉既往无异常。否认酗酒或吸毒，没有正在服用其它药物。否认黄疸病史。45岁时曾因胃溃疡出血住院，手术治疗，输血4U；无并发症，无复发。有乙肝疫苗接种史。其它未发现异常。造成其肝功能检查异常最有可能的病原体是","o":["HAV","HBV","HCV","HDV","HEV"],"a":2,"e":"有输血史、肝酶轻中度升高而无黄疸，已接种乙肝疫苗，HCV主要经血及血制品传播且极易慢性化，为最可能病因。HAV与HEV经粪-口传播，多为急性自限性肝炎；HBV有疫苗保护且无输血后发病的典型；HDV需以HBsAg阳性为前提"},{"q":"患者，男，32岁，经常出入酒吧、KTV，因下腹不适3周来就诊。查体：外生殖器见无痛性硬下疳，溃疡处有渗出液，初步诊断为梅毒。该病原体属于","o":["原核细胞型微生物","真核细胞型微生物","非细胞型微生物","朊病毒","亚病毒"],"a":0,"e":"梅毒螺旋体有细胞壁、核糖体与拟核，无核膜与完整细胞器，以二分裂方式繁殖，属原核细胞型微生物。真菌属真核细胞型，有核膜与细胞器；病毒为非细胞型，仅含一种核酸；朊粒为不含核酸的蛋白感染因子；亚病毒包括类病毒与卫星RNA，均与螺旋体不同"},{"q":"一位38岁男性旅游者从非洲归来，突发疾病，恶心、呕吐、腹泻。去医院就诊，常规镜检可见黏液和少许红细胞、白细胞。取粪便或早期培养物涂片作革兰染色镜检，可见革兰阴性弧菌。悬滴检查或暗视野显微镜检，可见运动活泼呈穿梭状的弧菌。该旅游者可能感染","o":["霍乱弧菌","破伤风梭菌","肠产毒性大肠埃希菌","福氏志贺菌","伤寒沙门菌"],"a":0,"e":"从非洲归来，吐泻后镜检见革兰阴性弧菌、悬滴法见穿梭运动，为霍乱弧菌。破伤风梭菌为革兰阳性芽胞杆菌、引起肌强直；肠产毒性大肠埃希菌为革兰阴性杆菌、无弧菌形态；福氏志贺菌动力阴性、引起脓血便；伤寒沙门菌有周鞭毛但形态非弧菌"},{"q":"患者，男，40岁，到海滨城市旅游，食用海鲜24小时后出现呕吐、腹泻、头痛，诊断为急性胃肠炎。最可能感染的病原体是","o":["星状病毒","诺如病毒","肠道病毒71型","甲型肝炎病毒","A组轮状病毒"],"a":1,"e":"诺如病毒经污染的海产品与水源传播，潜伏期24～48小时，起病急，以呕吐、水样泻与腹痛为主，病程1～3天。轮状病毒主要感染婴幼儿；甲肝虽可经海产品传播，但潜伏期约30天并出现黄疸与肝损害"},{"q":"某中学，发生10例以发热、呕吐、腹泻为主的病例，并伴有里急后重、黏液脓血便的症状，临床诊断疑似细菌性痢疾，可能感染","o":["伤寒沙门菌","肠炎沙门菌","霍乱弧菌","志贺菌","肉毒梭菌"],"a":3,"e":"发热、呕吐腹泻伴里急后重与黏液脓血便，为志贺菌侵袭结肠黏膜所致细菌性痢疾。伤寒沙门菌引起持续发热与相对缓脉，腹泻多为水样；肠炎沙门菌以食物中毒性胃肠炎为主；霍乱为无痛性米泔水样泻；肉毒梭菌引起弛缓性麻痹而非脓血便"},{"q":"患儿，女，3岁。高热、咽痛、流涎、厌食、呕吐等。入院查体发现咽部充血，在咽腭弓、软腭、悬雍垂的黏膜上可见数个2～4mm大小灰白色的疱疹，周围有红晕，2日后破溃形成小溃疡。继发乙型流感。该患儿最可能的诊断是","o":["麻疹","手足口病","水痘","疱疹性咽峡炎","鹅口疮"],"a":3,"e":"高热、咽痛、流涎，咽腭弓与软腭、悬雍垂处灰白色疱疹并破溃成溃疡，为柯萨奇A组2～6、8、10型所致疱疹性咽峡炎。手足口病皮疹位于手、足、口腔，由EV-A71与CVA16引起；麻疹有科氏斑与自耳后开始的皮疹；水痘皮疹向心性分布、分批出现；鹅口疮为白色凝乳状斑片"},{"q":"一成年男性，25岁，未婚，在出国体检中检出HIV抗体阳性。经询问，自认为身体无任何异常，否认吸毒史、同性恋史，但在两年前与几位女网友有过几次无防护性行为。关于该病例说法错误的是","o":["该患者可能处于无症状潜伏期","如不及时治疗可能发展为AIDS期","该患者血中的病毒量可能不高","该患者目前很难检出HIV p24抗原阳性","该患者有可能曾感染了HIV，但现已痊愈"],"a":4,"e":"HIV抗体阳性者即使无症状也处于持续感染状态，不会自行痊愈，故该说法错误。抗体阳性而CD4尚可者多为无症状潜伏期，此期病毒低水平复制、血中病毒载量不高，p24抗原常难检出，随免疫缺陷加重可进展为艾滋病期"},{"q":"患者，女，20岁。旅行归来的次日出现低热，食欲缺乏，然后水样便达15次之多，无里急后重感，腹痛为轻中度，伴有恶心和乏力。有轻度脱水，体温38℃。便常规：镜下未见红、白细胞。血常规：白细胞5.6×109/L，中性粒细胞占0.8。此患者最有可能的感染是","o":["沙门菌感染","肠产毒素型大肠埃希菌","霍乱弧菌","肠出血型大肠埃希菌","志贺菌感染"],"a":1,"e":"肠产毒素型大肠埃希菌经污染食物与水源传播，不耐热肠毒素激活腺苷酸环化酶、升高cAMP，引起分泌性水泻，镜检无红白细胞。霍乱弧菌排出米泔水样便、脱水严重；肠侵袭性大肠埃希菌与志贺菌侵袭肠黏膜，粪便见大量白细胞与红细胞；肠出血性大肠埃希菌致血便伴肾损害"},{"q":"患者，男，35岁。发热5天，最高体温40℃，急性重病容，酒醉貌，少尿，初步诊断为流行性出血热。以下有助于诊断的实验室检查不包括","o":["白细胞计数增高","血小板减少","血液浓缩","蛋白尿","小三阳"],"a":4,"e":"发热、酒醉貌、少尿，疑肾综合征出血热，诊断依据包括白细胞增高、血小板减少、血液浓缩与蛋白尿，而乙肝“小三阳”只反映HBV感染状态，与出血热诊断无关。血液浓缩与蛋白尿提示血浆外渗；血小板减少是出血热的特征之一"},{"q":"患者，男，35岁，因输血感染HBV。其进行血清学检查时，通常不能检测到的成分是","o":["HBsAg","抗-HBs","HBeAg","抗-HBe","HBcAg"],"a":4,"e":"HBcAg组装于病毒衣壳内，不游离于血液，常规血清学方法难以检出，故输血感染者的血清学检查中通常测不到。HBsAg与HBeAg为可溶性抗原，抗-HBs与抗-HBe为相应抗体，均可在血清中测出。抗-HBc出现早、持续时间长，是感染的重要标志，亦属常规检测项目"},{"q":"某急性乙型肝炎患者，用拉米夫定和干扰素治疗2个月后，血清HBV抗原抗体检查结果如下：HBsAg（＋），抗HBs（－），HBeAg（－），抗HBe（＋），抗HBc-IgM（－），抗HBc IgG（＋）。对该结果最好的解释是","o":["HBV感染急性期","病毒复制减弱，处于恢复期","无症状携带者","HBV复制活跃，血清传染性强","HBV已被清除"],"a":1,"e":"治疗后HBeAg阴转、抗-HBe阳转，抗-HBc由IgM转为IgG，而HBsAg仍阳性，说明病毒复制减弱、进入恢复阶段。急性期应有HBeAg与抗-HBc IgM阳性；复制活跃、传染性强者HBeAg阳性且HBV DNA高；无症状携带者肝功能正常；HBsAg仍阳性说明病毒尚未被清除"},{"q":"患儿，女，5岁，在当地一家快餐店参加生日聚会。约48小时后，她出现发热，剧烈腹痛伴血便，次日因为持续腹痛腹泻、少尿到急诊科就诊。最有可能导致该患儿患病的病原体是","o":["肠出血性大肠杆菌","伤寒沙门菌","肠致病型大肠埃希菌","葡萄球菌","志贺菌"],"a":0,"e":"肠出血性大肠埃希菌经污染牛肉传播，产志贺毒素损伤肠黏膜与肾内皮细胞，引起血便、少尿及溶血尿毒综合征。肠致病型大肠埃希菌致婴儿水样泻、无血便；志贺菌致菌痢以里急后重、脓血便为主；金黄色葡萄球菌食物中毒以剧烈呕吐为突出表现"},{"q":"一患者，近来突然出现神经兴奋性增高，吞咽、饮水，甚至听到流水声等轻微刺激均可引起痉挛。该患者最可能罹患的疾病是","o":["破伤风","鼠疫","肉毒中毒","博尔纳病","狂犬病"],"a":4,"e":"吞咽及饮水时咽喉肌痉挛，甚至听到流水声即诱发，为恐水症，是狂犬病病毒侵犯中枢神经系统的典型表现。破伤风为牙关紧闭、苦笑面容与全身肌强直，声光刺激亦可诱发但无恐水；肉毒中毒为弛缓性麻痹、瞳孔散大；鼠疫有腺肿与败血症表现"},{"q":"患者有丛林接触史，腿部皮肤被叮咬，局部出现溃疡，突发高热、皮疹。用变形杆菌OXk株作抗原与患者血清进行定量凝集试验，抗体效价为1∶320。该患者以上表现可能是由何种病原体引起","o":["普氏立克次体","恙虫病立克次体","斑疹伤寒立克次体","鹦鹉热衣原体","贝纳氏柯克斯体"],"a":1,"e":"丛林接触、叮咬处溃疡（焦痂）、高热皮疹，外斐反应OXk 1∶320而OX19阴性，为恙虫病东方体感染。普氏与斑疹伤寒立克次体OX19、OX2阳性而OXK阴性；鹦鹉热衣原体经呼吸道吸入感染、无焦痂；贝纳柯克斯体引起Q热，外斐反应阴性"},{"q":"患儿，女，6月龄，持续性高热，伴咳嗽、流涕，吃奶及饮水时呛咳明显，声音嘶哑，气促明显，颜面及躯干可见红色斑丘疹，四肢皮疹不明显，双眼结膜充血，眼部分泌物较多，咽部充血，双侧颊黏膜可见中心灰白周围红色特征斑，双肺呼吸音粗，可及较多中细湿啰音。否认麻疹接触史，按时按序接种疫苗。胸片示双肺纹理粗，右下肺可见斑片状渗出影。血常规示白细胞升高。该患儿最可能的诊断是","o":["风疹","副伤寒","麻疹合并支气管肺炎","猩红热","白假丝酵母菌致鹅口疮合并肺炎"],"a":2,"e":"6月龄婴儿未完成麻疹疫苗免疫，发热、卡他症状、颊黏膜科氏斑及自面颈向躯干扩展的皮疹符合麻疹，肺部湿啰音与斑片影提示合并支气管肺炎。风疹无科氏斑、全身症状轻；猩红热皮疹为弥漫充血性并伴杨梅舌"},{"q":"一男性青年发热休克，3天前开始头痛入院，当日意识不清，昏迷，体温41℃，血压70/30mmHg，躯干皮肤出现红色斑点。用药后血压仍继续下降，入院第3天死亡。血培养发现革兰阴性肾性双球菌生长。请问该病原菌的主要致病物质为","o":["荚膜","菌毛","外毒素","内毒素","芽孢"],"a":3,"e":"血培养为革兰阴性双球菌，休克伴皮肤瘀斑，为脑膜炎奈瑟菌，其致病物质主要是内毒素即脂多糖，引起发热、休克与DIC。荚膜与菌毛分别参与抗吞噬和黏附，不是休克主因；外毒素主要由革兰阳性菌产生；芽胞为休眠结构、不参与致病，该菌亦无芽胞"},{"q":"患者，男，36岁。主诉尿痛、尿道流脓性分泌物2天，尿道口痛性脓肿3天。发病1周前曾有过多次非婚性接触史，2天后感尿道疼痛，尤其小便时为甚，尿道口有脓性分泌物流出。入院后，经各项检查符合淋病奈瑟菌引起的尿道炎诊断。培养淋病奈瑟菌时应注意","o":["初次分离培养时应提供5%～10%的二氧化碳气体","培养基中形成羽毛养菌落即为该菌的典型特征","应在培养基中加入蛋黄、孔雀绿等必要的成分","此菌在液体培养基中生长加入胆盐后菌体自溶","在培养基中加入适量青霉素菌体呈串珠样改变"],"a":0,"e":"淋病奈瑟菌初次分离须在5%～10%二氧化碳环境、巧克力血琼脂平板上生长，形成凸起、圆形、灰白色光滑型小菌落。SS培养基用于肠道致病菌筛选；蛋黄与孔雀绿为罗氏培养基成分；青霉素不用于培养，且耐药株普遍"},{"q":"患儿，男，7岁。肌阵挛抽动伴认知功能下降3月余，既往发育阶段各标志不明显，有认知功能损害。刚出生1个月时，曾患麻疹，很快痊愈。脑电图显示节律性活动。颅脑MRI检查显示大脑白质内不均匀的高信号。血常规白细胞数不高。该患儿最可能的诊断是","o":["海绵状脑病","流行性脑脊髓膜炎","流行性乙型脑炎","亚急性硬化性全脑炎","急性脑膜炎"],"a":3,"e":"麻疹病毒在脑内持续潜伏，病愈后5～15年发生亚急性硬化性全脑炎，表现为肌阵挛抽动、认知下降、脑电图节律性放电。克-雅病由朊粒引起，多见于中老年、进展更快且无麻疹史；流行性乙型脑炎为急性期高热惊厥，无长期潜伏过程"},{"q":"某大学同宿舍4名同学外出在一家路边小餐馆聚餐后，晚自习时，3名同学出现剧烈呕吐、腹泻，同时伴有中上腹部疼痛。急诊入院，初步诊断为金黄色葡萄球菌引起的“食物中毒”。此菌能够合成的代谢产物是","o":["维生素","抗生素","内毒素","外毒素","水溶性色素"],"a":3,"e":"金黄色葡萄球菌肠毒素为外毒素，耐热，100℃30分钟不被破坏，作用于呕吐中枢，食后1～6小时出现剧烈呕吐。内毒素为革兰阴性菌脂多糖，本菌为革兰阳性；水溶性色素如金黄色素与致病无关"},{"q":"患儿，男，9岁，夏天玩耍时踩中生锈的铁钉被刺伤，铁钉穿透他的运动鞋，刺入他的右脚，但是他没有告诉父母，因为刺伤处出血很少，晚饭时就止住了。一个星期后，患儿开始喉咙痛；４天以后，患儿出现吞咽、说话、呼吸困难，同时出现肌肉痉挛，父母不得不带他去看医生，医生怀疑其为破伤风梭菌感染，并检测了其破伤风梭菌免疫球蛋白。医生询问其父母该患儿上次接种破伤风疫苗的时间，父母表示不知道。一周后患儿因为呼吸衰竭而死亡。病原体的基本特征是","o":["致病微生物，破伤风梭菌，是一种严格的厌氧菌","致病微生物，破伤风梭菌，是一种严格需氧菌","致病微生物，破伤风梭菌，产生一种非热稳定性的毒素","致病微生物，破伤风梭菌，产生芽孢，产生一种非热稳定性的毒素","致病微生物，破伤风梭菌，产生芽孢，是一种严格需氧菌，产生一种非热稳定性的毒素"],"a":3,"e":"破伤风梭菌为革兰阳性厌氧芽胞杆菌，芽胞位于菌体顶端呈鼓槌状，产生的痉挛毒素属外毒素、不耐热，60℃30分钟即被破坏。专性需氧与梭菌属的厌氧特性矛盾；未提及芽胞的选项不能概括其基本特征"},{"q":"患儿，女，5岁，因间断咳嗽气喘2个月，加重1周就诊。查体：咽红充血，双肺呼吸音粗，可闻及痰鸣、喘鸣及中小湿啰音。胸片提示支气管肺炎。取呼吸道分泌物进行支原体培养，能分解葡萄糖，但不分解尿素及精氨酸；固体培养基培养3天，显微镜下可见“荷包蛋”样菌落。请问引起本病的病原体最可能是","o":["解脲脲原体","人型支原体","肺炎支原体","肺炎嗜衣原体","流感嗜血杆菌"],"a":2,"e":"肺炎支原体发酵葡萄糖、不利用精氨酸与尿素，固体培养基上呈荷包蛋样菌落，是儿童支气管肺炎与阵发性干咳的常见病原。人型支原体分解精氨酸而不分解尿素；解脲脲原体分解尿素而不分解糖类；肺炎嗜衣原体为专性细胞内寄生"},{"q":"患者，男，27岁，教师。3年前戒毒，近1年来双下肢麻木、乏力，进行性加重，近1个月不能行走，便秘，排尿不畅。当地颅脑及胸腰椎CT（－）。检查：双下肢肌力4°，胸10以下痛觉减退，关节位置及音叉觉正常，下肢腱反射亢进，Babinski（＋）。腰穿CSF压力160mmH2O，细胞35×106/L，蛋白1275mg/L，按脊髓炎治疗无效。查血RPR 1∶32，TPHA 1∶2560；腰穿CSF细胞25×106/L，蛋白1344mg/L，RPR 1∶2，TPHA 1∶1280。该患者最有可能是什么疾病","o":["化脓性脊髓炎","脊髓钩端螺旋体病","脊髓血管梅毒","病毒性脊髓炎","结核性脊髓炎"],"a":2,"e":"双下肢进行性无力伴深感觉障碍、Babinski征阳性，血与脑脊液RPR、TPHA均阳性，为神经梅毒中的脊髓血管梅毒。化脓性脊髓炎起病急、脑脊液中性粒细胞升高且梅毒血清学阴性；钩端螺旋体病有疫水接触与腓肠肌压痛；病毒性脊髓炎无梅毒血清学证据；结核性脊髓炎脑脊液糖低、蛋白高"},{"q":"患儿，男，12岁，昨晚在外就餐，今晨开始畏寒、发热，腹痛，腹泻伴明显里急后重；大便8次，初为稀便，继之为黏液脓血便。此病例的诊断为","o":["阿米巴痢疾","急性细菌性痢疾","急性中毒性细菌性痢疾","急性胃肠炎","慢性细菌性痢疾"],"a":1,"e":"志贺菌经污染食物感染，表现为发热、腹痛、里急后重及黏液脓血便，属急性普通型菌痢。阿米巴痢疾起病缓、粪呈果酱样、右下腹压痛；中毒型菌痢多见于2～7岁，以高热惊厥、休克为主而肠道症状轻微；慢性菌痢病程超过2个月"},{"q":"患者，女，45岁，因食入河鱼引起腹泻，去医院就诊。病程以急剧腹泻、呕吐开始，腹泻为无痛性，伴有因腹直肌痉挛而引起的腹痛；大便开始为泥浆样，迅速成为“米泔水”样，含大量片状黏液；大便量多，每次可超过1000ml，每日10余次；呕吐常为喷射性和连续性，呕吐物先为胃内容物，继而为清水样。涂片染色取粪便及呕吐物涂片作革兰染色镜检，可见革兰阴性弧菌。怀疑该患者患何种疾病","o":["胃肠炎","霍乱","伤寒","细菌性痢疾","大肠埃希菌感染"],"a":1,"e":"食入河鱼后剧烈无痛性腹泻、喷射性呕吐，大便迅速转为米泔水样且量多，涂片见革兰阴性弧菌，符合霍乱。伤寒为持续发热、相对缓脉与玫瑰疹；细菌性痢疾有里急后重与黏液脓血便；大肠埃希菌感染多为水样泻或脓血便，无米泔水样表现；胃肠炎为笼统诊断，不能解释重度脱水与弧菌形态"},{"q":"患者，35岁，发热5天，面部、前胸皮肤充血潮红，腋下见针尖样出血点，血常规示白细胞计数13.12×109/L，血小板计数39×109/L，肾功能检查尿素氮18.6mmol/L，血肌酐491.9mmol/L。该病例可诊断的疾病是","o":["急性肾小球肾炎","肾综合征出血热","肠热症","登革热","钩体病"],"a":1,"e":"汉坦病毒经带毒鼠类的排泄物气溶胶传播，表现为发热、充血出血、低血压与急性肾损害，血小板减少、尿素氮与肌酐升高为典型改变。钩端螺旋体病有腓肠肌压痛与黄疸；登革热以高热、皮疹、骨关节痛为主，肾损害轻微"},{"q":"患者，男，22岁，因高热、咳嗽5天急诊入院。患者5天前洗澡受凉后出现寒战，体温高达40℃，伴咳嗽、咳痰，痰少呈铁锈色，无痰中带血，无胸痛。口服先锋霉素Ⅵ及止咳、退热剂3天后不见好转，体温仍波动于38、5～40℃。查体：急性热病容，神志清楚，无皮疹，浅表淋巴结无肿大，巩膜无黄染，咽（－），气管居中，左中上肺叩浊音，语颤增强，可闻湿性啰音，叩诊心界不大，心率100次/min，律齐，无杂音，腹平软，肝脾未及，病理反射未引出。实验室检查：Hb 140g/L，WBC 12×109/L，N 82%，L 18%，PLT 180×109/L；尿常规（－）；粪便常规（－）。初步诊断为大叶性肺炎。该病原体的主要致病物质是","o":["荚膜","脂质","鞭毛","内毒素","菌毛"],"a":0,"e":"铁锈色痰、左中上肺实变体征、白细胞与中性粒细胞升高，为大叶性肺炎，病原为肺炎链球菌，荚膜多糖抗吞噬是其首要毒力因子。脂质与内毒素为革兰阴性菌成分；鞭毛与菌毛分别与运动和黏附有关，均非该菌主要致病物质；该菌本身无鞭毛"},{"q":"急性细菌性痢病程第5日，婴儿出现溶血性贫血、急性肾衰竭和血小板减少。这种被称为溶血性尿毒综合征的临床三联征是起因于","o":["志贺毒素的作用","肠壁广泛性受损","细菌入血并释放内毒素","不耐热肠毒素的作用","细菌的侵袭力"],"a":0,"e":"志贺毒素由痢疾志贺菌产生，具细胞毒、肠毒与神经毒作用，可损伤肾小球内皮细胞，引起溶血性贫血、血小板减少与急性肾衰竭组成的HUS。内毒素入血引起发热、休克与DIC，不产生该三联征；不耐热肠毒素为ETEC所致水样泻的致病物质，只激活腺苷酸环化酶；侵袭力决定细菌能否侵入结肠上皮，是脓血便与里急后重的基础；肠壁广泛受损表现为溃疡出血，不累及肾小球"},{"q":"患者，男，76岁。慢性支气管炎急性发作，伴发热，体温39℃。头孢他啶治疗2周，症状有所缓解；但近两天再次出现发热并伴咳嗽咳痰。取痰标本进行病原体分离培养及鉴定，检出革兰阳性病原体，圆形、卵圆形菌体，鉴定为白假丝酵母菌。应选用下列哪种药物进行治疗","o":["氟康唑","罗红霉素","诺氟沙星","头孢哌酮钠","青霉素"],"a":0,"e":"长期头孢他啶治疗后出现白假丝酵母菌感染，应选氟康唑，其抑制真菌羊毛固醇14α-去甲基化酶，阻断麦角固醇合成。罗红霉素、诺氟沙星、头孢哌酮与青霉素均作用于细菌，对真菌无效。两性霉素B与卡泊芬净用于重症或耐药株，本例首选氟康唑"},{"q":"患儿，男，12天龄，出生体重1、5kg。患儿早产（孕7个月），并诊断为：先天性白内障、血小板减少、听觉诱发电位平直、无波形（可疑中枢性耳聋）、免疫性溶血、新生儿肺炎、病毒性脑炎等。其母亲，28岁，查出怀孕前3天发热，伴出红色斑丘疹，医院诊断为荨麻疹。怀孕7个月产下双胞胎，一胎死亡。该患儿胎内最可能感染的病原体是","o":["麻疹病毒","水痘-带状疱疹病毒","风疹病毒","柯萨奇病毒","普氏立克次体"],"a":2,"e":"孕早期感染风疹病毒，病毒经胎盘垂直传播并抑制细胞分裂，引起先天性风疹综合征，表现为白内障、耳聋、血小板减少、溶血与肺炎。麻疹病毒与水痘-带状疱疹病毒亦可致流产、早产，但罕见白内障三联征；柯萨奇病毒引起心肌炎与脑膜脑炎；普氏立克次体经虱传播，不引起先天畸形"},{"q":"一青年近3天咳嗽，高热39℃，铁锈色痰，WBC18.5×109/L，X线胸片发现右肺中叶有大片阴影，临床诊断为大叶性肺炎、请问该致病菌的主要致病物质是","o":["鞭毛","荚膜","外毒素","内毒素","菌毛"],"a":1,"e":"铁锈色痰、右肺大片阴影、白细胞升高，为大叶性肺炎，病原为肺炎链球菌，其荚膜抗吞噬、是主要毒力因子，失去荚膜则毒力显著减弱。内毒素为革兰阴性菌的致病物质，本菌为革兰阳性；外毒素由白喉、破伤风等产生；鞭毛与菌毛分别与运动、黏附有关，非本病主因"},{"q":"患儿，男，13个月。发热3天，突发阵发性全身性抽搐，频繁呕吐，烦躁，外周血白细胞数正常，无动物接触史。其乳母近期曾患“龈口炎”。该患儿最可能的诊断是","o":["流行性乙型脑炎","巨细胞病毒性脑炎","流行性脑脊髓膜炎","森林脑炎","单纯疱疹性脑炎"],"a":4,"e":"婴幼儿发热、抽搐、意识障碍，乳母近期患疱疹性龈口炎，提示HSV-1经密切接触传播，为单纯疱疹病毒性脑炎，病变多累及颞叶。乙型脑炎有严格季节性并经蚊传播；巨细胞病毒脑炎多见于免疫缺陷者；流脑有瘀斑与脑脊液化脓性改变；森林脑炎有蜱咬史与地区性"},{"q":"患者，女，56岁。反复上腹部隐痛并伴嗳气，咽部梗噎感，食欲减退6个月。胃液检查发现幽门螺杆菌，诊断为慢性胃窦炎及溃疡。对诊断有确诊价值的菌体形态是","o":["蚕豆形的球菌","U形、S形或W形的螺杆菌","海鸥状的弧菌","飞蝇状的球杆菌","鱼群状的梭菌"],"a":1,"e":"幽门螺杆菌为革兰阴性、菌体弯曲呈U形、S形或W形的螺杆菌，一端有数根鞭毛，黏附于胃窦黏膜，是慢性胃炎与消化性溃疡的病原。蚕豆形球菌为奈瑟菌；海鸥展翅状为弯曲菌属的典型形态；鱼群状是霍乱弧菌悬滴镜下的运动排列；飞蝇状为肉毒梭菌芽胞与菌体的特征"},{"q":"患儿，男，5岁，因发热伴出疹症状就诊。其父母主诉小孩患“重感冒”多天并服用小儿感冒药多天，畏光。红色斑丘疹从患儿的耳后、前额、颈部扩散到身体的其他部分，部分部位皮疹变暗。查体发现该患儿还患有细支气管炎。尿检和颊部疹子刮取物镜检发现包涵体和多核巨细胞，咽喉拭子常规细菌培养阴性，抗链球菌溶素O试验阴性。该患儿所患疾病最可能的是","o":["药疹","水痘","风疹","麻疹","猩红热"],"a":3,"e":"发热、畏光、卡他症状后自耳后发际开始出现红色斑丘疹，颊黏膜刮片见多核巨细胞与包涵体，为麻疹病毒。药疹有明确用药史、无科氏斑与多核巨细胞；水痘皮疹为向心性水疱疹；风疹皮疹消退快、无包涵体；猩红热有草莓舌与抗链O升高"},{"q":"患儿，男，2岁，因发热1天伴抽搐3次入院。查体：体温39.1℃，皮肤出现出血性淤斑。皮肤淤斑涂片镜检可见革兰染色阴性双球菌。该菌在固体培养基上生长形成","o":["露滴样菌落","菜花样菌落","羽毛样菌落","粗糙型菌落","油煎蛋样菌落"],"a":0,"e":"2岁患儿高热、抽搐、皮肤瘀斑，涂片见革兰阴性双球菌，为脑膜炎奈瑟菌，在巧克力平板上形成透明似露滴状菌落。菜花样菌落见于结核分枝杆菌；羽毛状生长为半固体培养基中有鞭毛菌的表现；粗糙型菌落为荚膜丢失或变异者；油煎蛋样菌落为支原体特征"},{"q":"患者，女，35岁，羊毛加工工人。因发烧、全身乏力、肌肉疼痛就诊，自述发烧3天，每天下午高烧，晚上体温下降。从患者血中分离到牛布鲁氏菌。关于牛布鲁氏菌的描述，正确的是","o":["是人类的条件致病菌","根兰阴性杆菌，主要通过肠毒素引起腹泻","有氧和无氧条件下均可生长，属于口腔正常菌群","通常感染牛，需要5%～10%CO2条件下培养","通常通过动物咬伤感染人类，引起人类出血热"],"a":3,"e":"牛布鲁氏菌主要感染牛，为革兰阴性小杆菌，初次分离需5%～10%CO₂环境，生长缓慢，血培养常需2周以上。该菌是重要人畜共患病原而非条件致病菌；不产肠毒素、不引起腹泻；并非口腔正常菌群；不经动物咬伤传播，也不引起出血热，后者由汉坦病毒所致"},{"q":"一老年男性患有慢性基础疾病且行动不便，在中央空调房间内长期生活，出现了发热、寒战、头痛和肌肉痛的症状，伴有咳嗽、胸痛，全身症状明显，诊断为嗜肺军团菌感染，其感染的临床类型属于","o":["流感型","肺炎型","肺外感染型","菌血症","继发型"],"a":1,"e":"嗜肺军团菌经气溶胶吸入肺泡巨噬细胞内增殖，肺炎型即军团病，起病急骤，高热寒战、咳嗽胸痛，伴多器官损害。流感样型又称庞蒂亚克热，无肺炎征象、3～5天自愈；肺外感染型以心内膜炎、透析通路感染为主"},{"q":"一年轻女性，近3天出现排尿困难和排尿次数增加。无发热、无皮疹。尿检发现每高倍镜下10～15个白细胞和大量细菌，细菌经染色为革兰阴性杆菌。可能为哪种细菌感染","o":["大肠埃希菌","志贺菌","伤寒沙门菌","解脲脲原体","淋病奈瑟菌"],"a":0,"e":"年轻女性尿频、尿痛、排尿困难，尿中白细胞与细菌增多，为尿路致病性大肠埃希菌引起的急性膀胱炎，其P菌毛与溶血素是定植并损伤尿路上皮的关键。志贺菌与伤寒沙门菌经消化道感染，引起腹泻或肠热症，不表现尿路刺激征；解脲脲原体无细胞壁、革兰染色不着色；淋病奈瑟菌为革兰阴性双球菌"},{"q":"农村患儿5岁，突起高热，体温40℃，头痛、恶心呕吐、嗜睡，查体有颈项强直，未见明显皮疹。最可能的疾病是","o":["登革热","流行性感冒","流行性乙型脑炎","出血热","麻疹"],"a":2,"e":"农村儿童突起高热、头痛呕吐、嗜睡、颈项强直，为流行性乙型脑炎，病毒经蚊叮咬侵入中枢神经系统。登革热以骨关节与肌肉剧痛、皮疹、出血为特征；流感以呼吸道症状为主、无脑膜刺激征；出血热有酒醉貌、结膜充血与肾损害；麻疹有卡他症状与科氏斑，皮疹自耳后发际开始"},{"q":"地震时，某学生被埋在废墟下，3天3夜才被救出。左下肢开放性伤口，污染大量泥土，部分肌肉组织已出现坏死。入院后被诊断为气性坏疽。引起气性坏疽的病原菌在繁殖过程中能够","o":["合成抗生素","合成内毒素","合成维生素","合成卵磷脂酶","合成金黄色色素"],"a":3,"e":"产气荚膜梭菌α毒素即卵磷脂酶，分解细胞膜卵磷脂，造成溶血、血管通透性增加与组织坏死，是气性坏疽形成的主要毒素。内毒素为革兰阴性菌细胞壁脂多糖，本菌为革兰阳性；金黄色色素由金黄色葡萄球菌产生；合成维生素与抗生素非其致病方式"},{"q":"患者，男，21岁，面部皮肤肿胀，双臂皮损广泛，痛触觉消失，指甲增厚，眉毛脱落。体检皮肤刮片抗酸染色可见胞浆呈泡沫状，临床诊断可能为何种病原体感染所致","o":["结核分枝杆菌","真菌","麻风分枝杆菌","肉毒梭菌","产气荚膜梭菌"],"a":2,"e":"皮肤广泛皮损伴痛触觉消失、指甲增厚、眉毛脱落，刮片抗酸染色见胞浆呈泡沫状的麻风细胞，为麻风分枝杆菌感染，该菌侵犯皮肤、黏膜与外周神经。结核分枝杆菌多引起肺部病变，皮损少见且无感觉丧失；真菌感染可见菌丝或孢子；肉毒梭菌与产气荚膜梭菌为厌氧芽胞杆菌"},{"q":"新生儿出生1周，出现全身弥漫性红疹。刮取红疹部位涂片革兰染色镜检发现革兰染色阳性、凝固酶阳性的球菌。引起该疾病的病原菌是","o":["金黄色葡萄球菌","表皮葡萄球菌","腐生性葡萄球菌","人葡萄球菌","B群链球菌"],"a":0,"e":"新生儿全身弥漫性红疹，刮片见革兰阳性、凝固酶阳性球菌，为金黄色葡萄球菌所致新生儿剥脱性皮炎样感染。表皮葡萄球菌与腐生葡萄球菌凝固酶均阴性、致病力弱；人葡萄球菌亦为凝固酶阴性；B群链球菌为革兰阳性链状排列、触酶阴性，引起新生儿败血症与脑膜炎，并非凝固酶阳性球菌"},{"q":"患者，男，29岁。因尿道口轻度红肿并有少许稀薄分泌物1周就诊。根据症状和相关检查初步诊断为解脲支原体感染引起的非淋病性尿道炎。以下哪项对该病例确诊有意义","o":["巧克力培养基做病原体培养","取尿道分泌物做涂片染色镜检","特异性抗血清做生长抑制试验","冷凝聚试验","外斐反应检测"],"a":2,"e":"支原体鉴定依靠特异性抗血清抑制其生长与代谢，生长抑制试验阳性可确诊解脲脲原体。巧克力平板用于奈瑟菌与流感嗜血杆菌；涂片革兰染色不能显示无细胞壁的支原体；冷凝集试验用于支原体肺炎的辅助诊断，非病原确诊；外斐反应用于立克次体病"},{"q":"患者青年男性，出现发热、不适、全身疼痛等症状。一天前出现持续高热，入院。查：患者相对缓脉，肝脾肿大，皮肤出现玫瑰疹，外周血白细胞明显下降，初步诊断为“肠热症”。引起该病的病原菌生化反应结果是","o":["分解乳糖只产酸","凝固酶试验阳性","尿素酶实验阳性","分解葡萄糖产酸不产气","枸橼酸盐利用试验阳性"],"a":3,"e":"持续高热、相对缓脉、肝脾大、玫瑰疹与白细胞减少，为伤寒沙门菌所致肠热症，该菌发酵葡萄糖只产酸不产气，是与其他沙门菌鉴别的要点。分解乳糖只产酸见于部分非致病菌；凝固酶阳性为金黄色葡萄球菌；尿素酶阳性为变形杆菌与幽门螺杆菌；枸橼酸盐利用阳性见于肠杆菌属等"},{"q":"患儿，男，2岁。发热伴咳嗽，诊断为链球菌肺炎。用抗生素治疗的疗程应持续至体温正常后","o":["2～4天","5～7天","8～10天","11～13天","16～21天"],"a":3,"e":"链球菌肺炎抗菌治疗须足疗程，体温恢复正常后仍需继续用药11～13天，以彻底清除病灶内残存细菌、减少复发与并发症。2～4天与5～7天疗程过短，易致病情反复；16～21天适用于金黄色葡萄球菌肺炎等易形成脓肿、迁延难愈者；疗程不足还可诱导耐药"},{"q":"2岁男孩，突然发热、呕吐及腹泻1天，排出大量水样便，其所在幼儿园也有数名幼儿出现类似症状，但教师中无类似病例。初步判断最可能的感染病原体是","o":["A组轮状病毒","肠侵袭性大肠埃希菌","痢疾志贺菌","柯萨奇病毒","诺如病毒"],"a":0,"e":"A组轮状病毒是婴幼儿秋季腹泻的首位病原，经粪-口传播，在托幼机构引起聚集发病，成人多呈隐性感染，故教师少发病。诺如病毒各年龄组普遍易感、常同时累及成人；肠侵袭性大肠埃希菌与痢疾志贺菌侵袭肠黏膜，粪便带脓血并有里急后重"},{"q":"患儿5岁，近来活动减少，乏力、食欲减退、盗汗。胸透见右肺上叶下部片状阴影，右肺门淋巴结肿大，应考虑诊断为","o":["小叶性肺炎","原发性肺结核病","支原体肺炎","病毒性肺炎","干酪样肺炎"],"a":1,"e":"儿童乏力、盗汗、食欲减退，右肺上叶下部片状阴影伴右肺门淋巴结肿大，为原发综合征表现，即原发性肺结核。小叶性肺炎以细支气管为中心的斑片影、无肺门淋巴结肿大；支原体肺炎症状轻、冷凝集试验阳性；病毒性肺炎多为间质性改变；干酪样肺炎见于反应强烈的继发型肺结核"},{"q":"患者起病急，高热，多为弛张热，伴寒战、严重头痛及全身肌肉酸痛，经实验室检查诊断为贝纳氏柯克斯体感染。下列疾病由贝纳氏柯克斯体引起的是","o":["波浪热","出血热","猩红热","战壕热","Q热"],"a":4,"e":"贝纳柯克斯体即Q热柯克斯体，人经呼吸道吸入含菌气溶胶或饮用污染乳感染，急性期高热、剧烈头痛与肌痛，可并发心内膜炎与肉芽肿性肝炎。波浪热为布鲁菌病；战壕热由五日热巴尔通体引起；猩红热由A群链球菌引起"},{"q":"患者，女，52岁，农民。因“咳嗽、胸闷、气喘进行性加重9个月”就诊。患者住房条件较差，近一个月其卧室堆放了大量未干透的稻草。经一系列检查，初步诊断为农民肺。农民肺的发病机制是","o":["吸入真菌孢子或菌丝引起的肺部致病真菌感染性疾病","吸入真菌孢子或菌丝引起的超敏反应性疾病","吸入真菌孢子或菌丝引起的真菌毒素中毒","吸入真菌孢子或菌丝引起的肺部条件致病真菌感染性疾病","细菌感染引起的肺炎"],"a":1,"e":"农民肺由吸入霉稻草中嗜热放线菌及真菌孢子引起，属Ⅲ型兼Ⅳ型超敏反应，为外源性变应性肺泡炎，并非感染。真菌毒素中毒由食入毒素引起肝、肾损害；条件致病真菌感染多见于免疫低下者，病理为侵袭性炎症与肉芽肿"},{"q":"一女性患者在无照诊所输液后不久，出现发热反应症状。导致该患者发热最有可能的成分是","o":["外毒素","肠毒素","细胞毒素","肉毒毒素","热原质"],"a":4,"e":"热原质是革兰阴性菌细胞壁脂多糖，注入人体即引起发热，耐高压蒸汽灭菌，须250℃干烤才能破坏。外毒素为蛋白质、不耐热，由活菌合成并分泌；肠毒素与细胞毒素均属外毒素，作用有组织选择性"},{"q":"患者，男，同性恋，被确诊为HIV感染者，病后5年患者出现明显的消瘦衰竭，反复发生肺部感染，造成其免疫功能低下的机制主要是","o":["树突状细胞减少","吞噬细胞被破坏","中和抗体保护作用下降","CD4+T淋巴细胞被大量破坏","CD8+T淋巴细胞被大量破坏"],"a":3,"e":"HIV以CD4分子为受体，通过直接损伤、合胞体形成及诱导凋亡使CD4+T淋巴细胞大量破坏，CD4+T细胞减少与功能下降是免疫缺陷的核心。CD8+T细胞参与抗病毒免疫而非主要靶细胞；中和抗体下降是免疫缺陷的结果而非原因"},{"q":"患者，女，62岁，农民。右前臂结节、溃疡、淋巴结肿大2个月余，有木刺刺伤史，当地医院给予头孢他啶及局部换药治疗，症状无缓解。取皮肤组织进行真菌培养，菌落灰褐色皱膜状，显微镜下可见有隔菌丝及梨状小分生孢子，口服碘化钾治疗后症状缓解。该患者最可能感染的真菌是","o":["红色毛癣菌","白假丝酵母菌","申克孢子丝菌","新型隐球菌","烟曲霉"],"a":2,"e":"申克孢子丝菌经木刺等外伤植入皮下，沿淋巴管呈链状结节，培养见棕色有隔菌丝及梨状小分生孢子，碘化钾治疗有效。红色毛癣菌仅侵犯角质层致体癣；白念珠菌为酵母型、形成假菌丝；烟曲霉致肺曲霉病"},{"q":"患者，男，发热、休克。3日前开始头痛，入院。当日意识不清，昏迷，体温41℃，血压70/30mmHg，躯干皮肤出现红色斑点。用药后血压仍继续下降，第3天死亡。血培养发现G－茅头状双球菌生长。请问其感染的病原菌可能是","o":["溶血性链球菌","脑膜炎奈瑟菌","肠侵袭性大肠杆菌","肺炎链球菌","金黄色葡萄球菌"],"a":1,"e":"脑膜炎奈瑟菌为革兰阴性肾形双球菌，内毒素致微血管栓塞，出现皮肤瘀斑、血压下降与休克，暴发型病死率高。肺炎链球菌为革兰阳性有荚膜双球菌；流感嗜血杆菌为革兰阴性小杆菌，需X、V因子；金黄色葡萄球菌成葡萄串状排列"},{"q":"患者，男，63岁，近半年来出现进行性发展的痴呆、肌痉挛、小脑共济失调、运动性失语，并迅速发展为半瘫、癫痫。该患者最终死于中枢神经系统功能衰竭。对于该病最可能的诊断是","o":["CJD","BSE","TME","FFI","CWD"],"a":0,"e":"克-雅病由朊粒引起，表现为迅速进展的痴呆、肌阵挛、共济失调与失明，脑组织呈海绵状改变，症状出现后平均生存4～5个月。致死性家族性失眠以家族性失眠为特征；牛海绵状脑病为牛病；慢性消耗病见于鹿"},{"q":"患者，男，27岁。发热5天，最高体温39.5℃，咳嗽，少痰，伴有头痛、肌肉酸痛和全身不适，出现呼吸困难，无胸痛。患者居住村庄近期出现大量禽类病死疫情。血常规检查显示白细胞总数减少；红细胞凝集试验阳性；胸片显示右下肺多发磨玻璃影及肺实变影像，合并少量胸腔积液。该患者最可能的诊断是","o":["肺结核","普通感冒","大叶性肺炎","人感染高致病性禽流感","严重急性呼吸综合征（SARS）"],"a":3,"e":"禽流感病毒H5N1等经密切接触病死禽传播，表现为高热、咳嗽、呼吸困难，白细胞减少，肺部磨玻璃影迅速进展为ARDS。SARS以发热、腹泻及家庭与医院聚集为特点；普通感冒症状轻、无肺炎；大叶性肺炎为细菌性，白细胞升高"},{"q":"患者，男，45岁，因咳嗽、发热、头痛、咽喉痛4天就诊。查体：咽红充血，体温38.5℃。白细胞9×109/L，X线胸片显示左下肺薄片状阴影，冷凝聚试验（＋）。最可能的诊断是","o":["呼吸道合胞病毒肺炎","肺炎链球菌肺炎","肺炎衣原体肺炎","肺炎支原体肺炎","流感嗜血杆菌肺炎"],"a":3,"e":"咳嗽、发热、头痛咽痛，胸片薄片状阴影而体征轻，冷凝集试验阳性，为肺炎支原体肺炎，其P1蛋白黏附呼吸道上皮。肺炎链球菌肺炎有肺实变、铁锈色痰与白细胞升高；呼吸道合胞病毒肺炎多见于婴幼儿、有喘息；肺炎衣原体肺炎冷凝集试验阴性；流感嗜血杆菌肺炎多有基础肺病"},{"q":"患儿，男，7岁。因“头顶部脓肿、糜烂1个月、发热2天”入院。查体可见头顶部约3cm×4cm斑块，表面糜烂，高低不平，有脓液溢出，基底发红，周围散在脓疱。取脓疱液涂片后棉蓝染色可见如箭头 所示结构。该类微生物细胞壁的主要成份是","o":["肽聚糖","脂蛋白","糖蛋白","几丁质","糖肽"],"a":3,"e":"棉蓝染色显示的是真菌菌丝与孢子，真菌细胞壁的纤维网骨架由几丁质与葡聚糖构成，几丁质为β-1,4糖苷键连接的N-乙酰葡糖胺聚合物。肽聚糖是细菌细胞壁的骨架成分；脂蛋白、糖蛋白与糖肽为细菌细胞壁或细胞膜组分，均不构成真菌细胞壁骨架"},{"q":"患儿，3岁，就诊时中度发热，咳嗽、流涕、流泪、咽部充血等，以眼症状突出，包括结膜炎、眼睑水肿、眼泪增多、畏光，下眼睑边缘有一条明显充血横线（Stimson线），口腔两颊内侧黏膜查现Koplik斑。该患儿最可能的诊断是","o":["麻风","莱姆病","猩红热","副伤寒","麻疹"],"a":4,"e":"麻疹前驱期有发热、咳嗽、流涕、结膜充血与畏光，Stimson线与科氏斑为早期诊断依据，随后出现自耳后发际向全身扩展的斑丘疹。风疹全身症状轻、耳后淋巴结肿大、无科氏斑；猩红热有杨梅舌与口周苍白圈，无口腔黏膜斑"},{"q":"患儿，女，6岁。突起高热、头痛、呕吐伴有意识障碍，经血清学检查及脑脊液RT-PCR检查，诊断为“乙型脑炎”。引起该病的病原体的主要传播途径是","o":["消化道传播","输血传播","虫媒传播","呼吸道传播","直接接触传播"],"a":2,"e":"乙型脑炎病毒为虫媒病毒，由三带喙库蚊叮咬传播，病毒经血流入脑，引起高热、意识障碍与脑膜刺激征。消化道传播见于甲型与戊型肝炎、霍乱；输血传播主要见于HBV、HCV与HIV；呼吸道传播见于流感、麻疹；直接接触传播见于狂犬病、布鲁氏菌病，均非乙脑途径"},{"q":"某急性肝炎患者，血清学检测显示HBsAg（＋），HBeAg（＋），抗-HBc（＋）。传播该病原体的途径不包括","o":["粪-口途径","分娩和哺乳","共用牙刷、剃须刀等","性接触","输血、血浆及血液制品"],"a":0,"e":"HBV经血液、性接触与母婴（分娩、哺乳）传播，共用牙刷、剃须刀可经微量血液感染，输血及血制品、不安全注射亦是重要途径。粪-口途径是甲型与戊型肝炎病毒的传播方式，经此途径不能传播HBV"},{"q":"患者，女，45岁，东南某地农民。因“剧烈头痛、肌肉酸痛、高热2天”就诊。查体：全身点状红疹，衣物和头发内发现体虱数只。体温39.5℃。外斐反应结果：OX19（1∶640），OX2（1∶160），OXK（-)。该患者感染的病原体是","o":["变形杆菌","支原体","普氏立克次体","斑疹伤寒立克次体","恙虫病立克次体"],"a":2,"e":"体虱叮咬、高热头痛、全身点状红疹，外斐反应OX19 1∶640、OX2 1∶160、OXK阴性，为普氏立克次体所致流行性斑疹伤寒。斑疹伤寒立克次体（地方性）OX19亦阳性但滴度较低、经鼠蚤传播；恙虫病东方体为OXK阳性；变形杆菌只是外斐反应的交叉抗原来源，并非病原；支原体外斐反应阴性"},{"q":"患儿，男，5岁。急性起病，发热、咳嗽，手掌、脚掌部、臀部及膝盖出现斑丘疹，皮疹周围有炎性红晕，疱内液体较少，口腔黏膜出现散在的疱疹，疼痛明显。同时伴有肌阵挛，急性迟缓性麻痹。患儿最可能感染的病原体是","o":["风疹病毒","恙虫病东方体","麻疹病毒","埃可病毒","新肠道病毒71型"],"a":4,"e":"肠道病毒71型好发于6个月至5岁儿童，表现为发热及手、足、臀部皮疹与口腔疱疹，可并发脑干脑炎、肌阵挛与急性弛缓性麻痹。柯萨奇A16型亦致手足口病但重症少；埃可病毒多引起无菌性脑膜炎与皮疹；麻疹病毒以科氏斑和全身斑丘疹为特征"},{"q":"出生后10天新生儿，因眼睑水肿、有脓性分泌物就诊。检查发现患儿睑结膜弥漫性红肿，结膜炎症性乳头增生，初步诊断为新生儿化脓性结膜炎。涂片革兰染色未见革兰阴性双球菌，眼结膜刮片示多核白细胞增多，碘染色直接镜检发现包涵体。以下最可能的是","o":["淋球菌感染","沙眼衣原体感染","金葡菌感染","腺病毒感染","梅毒螺旋体感染"],"a":1,"e":"新生儿经产道感染，眼睑水肿、脓性分泌物，结膜刮片碘染色见包涵体，为沙眼衣原体所致包涵体结膜炎。淋球菌感染涂片应见革兰阴性双球菌，本例阴性；金黄色葡萄球菌为革兰阳性球菌、无包涵体；腺病毒引起咽结膜热、无包涵体；梅毒螺旋体需镀银染色"},{"q":"患者，高热，剧烈头痛，肌肉酸痛，入院。经实验室检查诊断该病人为立克次体感染。协助诊断立克次体病的交叉凝集试验是","o":["反向间接血凝试验","正向间接血凝试验","冷凝集试验","外斐反应","肥达试验"],"a":3,"e":"立克次体与变形杆菌OX19、OX2、OXK菌株有共同抗原，用后者菌体抗原检测患者血清抗体的交叉凝集试验即外斐反应。肥达试验用于肠热症；冷凝集试验用于支原体肺炎；正向与反向间接血凝试验检测抗原或抗体，均非立克次体病的专用交叉凝集试验"},{"q":"患者，女，65岁。每日口服泼尼松15～30mg治疗膝关节肿痛，5个月后于颈部及腹股沟见1cm×2cm左右红斑各一块，其上散在丘疹；1年后皮损增多并融合，红斑上覆有鳞屑，取鳞屑及结痂经棉蓝染色可见大量有隔菌丝，棍棒状大分子孢子及散在小分生孢子，沙保培养基上生长出产生红色色素的丝状菌落。该患者最可能感染的真菌是","o":["石膏样小孢子菌","絮状表皮癣菌","红色毛癣菌","铁锈色小孢子菌","石膏样毛癣菌"],"a":2,"e":"长期糖皮质激素治疗致免疫低下，皮损融合成片伴鳞屑，棉蓝染色见有隔菌丝与棍棒状大分生孢子，沙保培养基产生红色色素，为红色毛癣菌。石膏样小孢子菌与铁锈色小孢子菌的菌落不产红色色素；絮状表皮癣菌不侵犯甲板、大分生孢子形态不同；石膏样毛癣菌菌落呈粉末状、色素非红色"},{"q":"患者，男，50岁。反复上腹疼痛不适8年，加重1天入院。患者于入院8年前开始，遇饥饿时偶感上腹隐痛不适，进食后缓解。入院7年前开始，上诉症状发作较为频繁且以胀痛、灼痛为主，多以辛辣刺激及不消化饮食为诱因，伴反酸嗳气，春季及秋冬季节交替时易发生，伴夜间痛，每次发作后进食可缓解。入院前1天，吃冷饮后上腹痛症状再次复发，伴黑便，糊状，共4次，每次约250g左右，渐感头昏心悸，不伴恶心呕血及畏寒发热。经查，以“消化性溃疡”收入住院。引起此患者“消化性溃疡”的病原菌生化反应结果是","o":["凝固酶试验阳性","尿素酶试验阳性","甲基红试验阳性","硫化氢试验阳性","VP试验阳性"],"a":1,"e":"消化性溃疡的病原菌为幽门螺杆菌，其产生大量尿素酶分解尿素产氨以中和胃酸，是尿素酶试验阳性的生化基础，也是尿素呼气试验诊断的依据。凝固酶阳性为金黄色葡萄球菌特征；甲基红与VP试验用于肠杆菌科鉴定；硫化氢阳性见于沙门菌与变形杆菌，均与幽门螺杆菌无关"},{"q":"一青年近3日咳嗽，高热39℃，铁锈色痰，WBC 18.5×109/L，X线胸片发现右肺中叶有大片阴影。临床诊断为大叶性肺炎，该病致病菌是","o":["肺炎杆菌","肺炎链球菌","肺炎衣原体","肺炎支原体","嗜肺军团菌"],"a":1,"e":"铁锈色痰、寒战高热、右肺中叶大片阴影，为大叶性肺炎，病原为肺炎链球菌。肺炎克雷伯菌多咳砖红色胶冻样痰、叶间裂下坠；肺炎衣原体与支原体肺炎症状轻、以干咳为主；嗜肺军团菌肺炎常伴腹泻、意识障碍与低钠血症"},{"q":"患者，男，18岁。因发热14天、皮疹9天入院就诊，伴咽痛，按感冒治疗未见好转。查体：浅表淋巴结肿大，肝脾大，IgM异嗜性抗体阳性。最可能的诊断是","o":["肠热症","巨细胞病毒单核细胞增多症","链球菌咽峡炎","传染性单核细胞增多症","急性感染性淋巴细胞增多症"],"a":3,"e":"EB病毒经唾液传播，感染B淋巴细胞，引起发热、咽痛、淋巴结及肝脾大，异嗜性抗体阳性为辅助诊断依据。巨细胞病毒所致单核细胞增多症异嗜性抗体阴性；链球菌咽峡炎ASO升高、无肝脾大与异嗜性抗体"},{"q":"20岁男性患者咳嗽数周。1个月前开始感到疲劳，食欲减少，发热2周后咳痰中带血丝，体重减轻。体温38℃，非急性面容，右上肺有啰音，WBC 11×109/L，多形核63%。临床怀疑患肺结核，取痰做标本培养，常用哪种培养基","o":["血琼脂平板","罗氏（Lowenstein-Jensen）培养基","Border-Gengou培养基","巧克力色培养基","亚碲酸钾培养基"],"a":1,"e":"肺结核痰标本培养常用罗氏培养基，含蛋黄、甘油与孔雀绿，可抑制杂菌；结核分枝杆菌生长缓慢，需2～4周形成菜花状菌落。血琼脂平板用于一般细菌；鲍-金培养基用于百日咳鲍特菌；巧克力平板用于奈瑟菌与流感嗜血杆菌；亚碲酸钾培养基用于白喉棒状杆菌"},{"q":"患者，男，38岁，因间断咳嗽气喘2个月，加重1周就诊。经检查初步诊断为支原体肺炎。下列哪种药物不能用于该患者治疗","o":["青霉素","红霉素","克拉霉素","阿奇霉素","诺氟沙星"],"a":0,"e":"支原体无细胞壁，β-内酰胺类抗生素失去作用靶点，故青霉素治疗无效。红霉素、克拉霉素与阿奇霉素属大环内酯类，作用于50S核糖体亚基抑制蛋白质合成，为治疗支原体肺炎的首选；诺氟沙星抑制DNA拓扑异构酶，对支原体亦有效；四环素类同样可选"},{"q":"某患者发热3天，恶心呕吐，食欲减退。头痛四肢酸痛，腰痛。球结膜充血，尿少，尿蛋白（＋＋＋）。该病例可考虑的诊断为","o":["败血症","钩体病","肾综合征出血热","肠热症","溶血性尿毒综合征"],"a":2,"e":"汉坦病毒病早期即出现发热、头痛腰痛、恶心呕吐、球结膜充血及大量蛋白尿，肾功能迅速受损。钩端螺旋体病以腓肠肌压痛、黄疸与淋巴结肿大为特点；败血症多有原发感染灶及白细胞显著升高；溶血尿毒综合征以贫血、血小板减少为主"},{"q":"患者，男，35岁。间歇性发热12天，高热和低热交替出现，高热时伴有头痛、乏力，最高体温39.5℃，无咳嗽。患者于两周前到牧区旅游，曾饮用未消毒的鲜牛奶，无蚊虫叮咬史。X光检查肺部未见异常。该病例的可能诊断是","o":["钩端螺旋体病","斑疹伤寒","布鲁菌病","肺结核","恙虫病"],"a":2,"e":"布鲁菌经消化道（未消毒乳制品）或破损皮肤侵入，热型呈波浪状起伏，伴多汗、关节痛与肝脾大。钩端螺旋体病有腓肠肌压痛与眼结膜充血，经疫水接触感染；斑疹伤寒由虱或蚤传播，有皮疹且外斐反应阳性"},{"q":"患者，男，20岁。20天前无明显诱因出现前额部持续性疼痛，伴恶心呕吐、头晕目眩、颈部强直、精神淡漠，同时出现斜视、共济失调等中枢神经系统症状，且伴有发热。实验室检查：腰穿脑脊液（CSF）清亮，墨汁负染色，结果如图所示。白色箭头所指为","o":["厚膜孢子","关节孢子","芽生孢子","孢子囊孢子","分生孢子"],"a":2,"e":"本题原题配有图片，图片未随文档保留，以下解析依文字线索推断：题干涉及图片/信息缺失，无法作答。脑脊液墨汁负染见厚荚膜酵母型菌体，其繁殖方式为出芽，芽体脱离母细胞即为芽生孢子，是隐球菌形态鉴定的要点。厚膜孢子为壁厚的休眠孢子；关节孢子由菌丝断裂形成；孢子囊孢子生于孢子囊内；分生孢子生于分生孢子梗顶端\n\n官方题库中缺失图片"},{"q":"某托幼机构突发公共卫生事件，多名2岁以下幼儿出现发热、腹泻症状，粪便电镜下可见大量车轮状、具双层衣壳的球形病毒颗粒。对该病毒感染不具有诊断价值的微生物学检测方法是","o":["细胞培养分离病毒","RT-PCR检测病毒核酸","聚丙烯酰胺凝胶电泳检测","红细胞吸附试验","ELISA法检测病毒抗原"],"a":3,"e":"车轮状、双层衣壳的球形病毒为轮状病毒，诊断可用电镜、RT-PCR、PAGE检测核酸、ELISA检测抗原以及细胞培养分离。红细胞吸附试验用于检测流感病毒等具血凝素的包膜病毒增殖，轮状病毒无血凝素、不产生红细胞吸附，故无诊断价值"},{"q":"患者，男，40岁，农民。因“突起发热、头晕与头痛1周”就诊。查体：眼结膜充血、轻度黄疸、腓肠肌有明显压痛，初诊为钩体病。为协助诊断，下列检查方法，不正确的是","o":["取血标本做核酸检测","取血标本做显微镜凝集试验","取血标本接种Korthof培养基做病原培养","取血标本做快速血浆反应素试验（RPR试验）","血标本直接显微镜镜检"],"a":3,"e":"钩端螺旋体病可取血做核酸检测、显微镜凝集试验、Korthof培养基培养及暗视野镜检，各法敏感性随病程而异。RPR检测反应素，为非特异性试验，用于梅毒筛查，与钩端螺旋体无关，故该项检查不正确"},{"q":"某患者血液标本“二对半”的检测结果为：HBsAg（＋），抗-HBs（-），HBeAg（＋），抗-HBe（-），抗-HBc（＋）。最有可能的诊断是","o":["乙型肝炎潜伏期","乙型肝炎急性期","乙型肝炎恢复期","HBV病毒既往感染","接种过乙肝疫苗"],"a":1,"e":"乙肝两对半中HBsAg、HBeAg、抗-HBc同时阳性，称大三阳，提示病毒复制活跃、传染性强，见于急性感染或慢性感染急性发作。接种疫苗者仅抗-HBs阳性；既往感染已恢复者为抗-HBs、抗-HBe与抗-HBcIgG阳性而HBsAg阴性"},{"q":"患儿，男，1岁，因抽搐入院。上呼吸道感染2天，昨夜发热嗜睡。查体：颈强，体温40℃。WBC 17×109/L，腰穿脑脊液细胞数4×109/L，中性粒细胞占88%。诊断为细菌性脑膜炎。细菌培养时发现在预加的金葡菌菌落周围生长旺盛，出现卫星现象，G染色为G－杆菌。试问所感染的细菌可能是","o":["肺炎克雷伯菌","A群链球菌","脑膜炎奈瑟菌","流感嗜血杆菌","铜绿假单胞菌"],"a":3,"e":"脑膜炎患儿培养见金黄色葡萄球菌菌落周围生长旺盛的卫星现象，且为革兰阴性杆菌，为流感嗜血杆菌；其生长需X因子与V因子，金葡菌可提供V因子。肺炎克雷伯菌为革兰阴性杆菌但无卫星现象、菌落黏稠；A群链球菌为革兰阳性；脑膜炎奈瑟菌为双球菌；铜绿假单胞菌产绿色素"},{"q":"患者，男，15岁，学生。3天前突然高热达39℃，伴发冷和寒战，同时出现剧烈头痛，频繁呕吐，呈喷射性，吐出食物和胆汁，无上腹部不适，进食少，二便正常。查体可见皮肤散在少量出血点和脑膜刺激征。既往体健，无胃病和结核病史，无药物过敏史，所在学校有类似患者发生。请问可能感染的病原体是","o":["乙型脑炎病毒","脑膜炎奈瑟菌","肠侵袭性大肠杆菌","肺炎链球菌","金黄色葡萄球菌"],"a":1,"e":"脑膜炎奈瑟菌经飞沫传播，儿童与学生聚集发病，突发高热、喷射性呕吐、皮肤瘀点及脑膜刺激征为流脑典型表现。乙型脑炎有严格季节性、由蚊传播，皮肤瘀点少见；肺炎链球菌脑膜炎多继发于肺炎或中耳炎，无聚集性"},{"q":"自然灾害过后，当地农村断水断电，生活陷入困境。居民在饮用河水后，许多人出现恶心、呕吐和腹泻症状，排泄物呈“米泔水”样。经当地医疗机构检测后发现，该疾病是由一种可激活腺苷酸环化酶系统、导致cAMP水平增加的毒素引起的。可产生这种毒素的细菌是","o":["布鲁氏菌","伤寒沙门菌","志贺菌","大肠埃希菌","霍乱弧菌"],"a":4,"e":"霍乱肠毒素B亚单位结合肠上皮细胞GM1受体，A亚单位进入细胞激活腺苷酸环化酶，cAMP升高致肠液过度分泌。肠产毒素型大肠埃希菌不耐热肠毒素机制相同，但所致为轻型旅行者腹泻；志贺菌靠侵袭力与内毒素致脓血便；伤寒沙门菌以持续发热、玫瑰疹为特点"},{"q":"患者，男，32岁。因车祸致右胫腓骨中段开放性骨折1小时入院治疗，入院后急诊行切开钢板内固定、石膏托外固定术。术后第3天查房时发现小腿中部有明显捻发感，伤口周围皮肤大部分呈紫红色，局部呈黑紫色，立即拆除缝线，见有暗红色的恶臭液体溢出，涂片检查显示革兰阳性粗大杆菌，急诊行截肢，残肢端缝合术，初步怀疑该男子是由哪种病原体感染致病","o":["破伤风梭菌","产气荚膜梭菌","肉毒梭菌","结核分枝杆菌","淋病奈瑟菌"],"a":1,"e":"开放性骨折术后伤口捻发感、皮肤紫红发黑、溢出恶臭暗红液体，涂片见革兰阳性粗大杆菌，为产气荚膜梭菌所致气性坏疽，α毒素即磷脂酶C分解细胞膜，引起组织坏死与气肿。破伤风梭菌引起肌强直痉挛而无气肿；肉毒梭菌引起弛缓性麻痹；结核分枝杆菌为抗酸杆菌；淋病奈瑟菌为革兰阴性双球菌"},{"q":"患者，男，15岁。持续低热3天，同时4天前颜面部出现充血性斑丘疹，疹间皮肤正常，可见皮疹融合，就诊时皮疹消退，无色素沉着。双侧颊黏膜光滑，耳后、枕后、颈部可触及淋巴结增大，偶有咳嗽，无流泪症状。该患者最可能的诊断是","o":["风疹","麻疹","猩红热","伤寒","莱姆病"],"a":0,"e":"风疹病毒经呼吸道传播，表现为低热、面部及躯干淡红色斑丘疹，伴耳后、枕下与颈部淋巴结肿大，皮疹消退后不留色素沉着、无黏膜斑。麻疹有科氏斑且退疹后留色素沉着与糠麸样脱屑；猩红热有杨梅舌、口周苍白圈与帕氏线"},{"q":"患者，男，40岁，农民，突起发热、头晕与头痛一周就诊。查体：眼结膜充血、轻度黄疸、腓肠肌有明显压痛，初诊为钩体病。请问进行病原学检查的最适标本是","o":["尿液","脑脊液","外周血","眼结膜分泌物","唾液"],"a":2,"e":"钩端螺旋体病发病7～10天处于菌血症期，取外周血可直接检出螺旋体，阳性率最高；两周后菌体随尿排出，应取尿液；有脑膜刺激征者取脑脊液。眼结膜分泌物与唾液不是钩体的排出途径，检出率低。血清学检查宜取发病1周与3～4周双份血清"},{"q":"患者，女，32岁，近10天出现畏寒发热，高热持续1周。血常规：白细胞3.2×109/L。肥达反应：TO 1∶320，TH 1∶320，PA 1∶40，PB 1∶40。最可能诊断为","o":["霍乱","疟疾","钩端螺旋体病","副伤寒","伤寒"],"a":4,"e":"肥达反应O效价1∶320、H效价1∶320，伴白细胞减少与持续高热，提示伤寒沙门菌感染。副伤寒的H抗体为PA、PB、PC，本例均1∶40无升高；疟疾靠血涂片查疟原虫；钩端螺旋体病以显微镜凝集试验阳性"},{"q":"患者，男，33岁，家住伦敦市郊，喜食牛排。近期出现严重进行性神经系统症状如精神异常、小脑共济失调、痴呆等，经诊断为变异型克罗伊茨费尔特-雅各布病。关于该类疾病，以下说法错误的是","o":["潜伏期长，可达10～30年","具备传染性","致病因子只存在于患者中枢神经系统中","该致病因子还可引起牛海绵状脑病","由朊粒引起"],"a":2,"e":"朊粒病为传染性海绵状脑病，潜伏期可达数十年，具传染性；朊粒除中枢神经系统外还存在于脾、扁桃体、淋巴结及血液中，故只存在于中枢神经系统的说法错误。vCJD与食用疯牛病牛肉有关，其致病因子即牛海绵状脑病朊粒"},{"q":"某幼儿园3岁小朋友，以发热、咽痛、呼吸困难入院。查体：体温38.5℃，口腔黏膜上散在白色斑点，咽部及扁桃体有一层灰白色膜。试问感染细菌经奈瑟染色后，观察到哪一结构有助于白喉的进一步诊断","o":["质粒","异染颗粒","荚膜","芽孢","鞭毛"],"a":1,"e":"白喉棒状杆菌菌体一端或两端有浓染的异染颗粒，主要成分为多偏磷酸盐与RNA，奈瑟染色呈深紫色，是形态学诊断的重要依据。质粒为胞内核酸、常规染色不可见；荚膜为抗吞噬结构，白喉杆菌无荚膜；芽孢见于厌氧芽胞杆菌；鞭毛与运动有关，白喉杆菌无鞭毛"},{"q":"患儿，女，3岁9个月。发热5天，双侧颈部淋巴结肿大，咽部充血，扁桃体肿大，眼睑水肿，异嗜性抗体阳性。最可能的诊断是","o":["急性扁桃体炎","传染性单核细胞增多症","颈部淋巴结炎","链球菌咽峡炎","巨细胞单核细胞增多症"],"a":1,"e":"发热、咽峡炎、双侧颈部淋巴结肿大、眼睑水肿，异嗜性抗体阳性，为EBV所致传染性单核细胞增多症。链球菌咽峡炎有脓性渗出、抗链O升高而异嗜性抗体阴性；急性扁桃体炎与颈部淋巴结炎为局部细菌感染，无全身淋巴结与肝脾受累；巨细胞病毒单核细胞增多症异嗜性抗体阴性"},{"q":"某年秋季，某幼儿园出现轮状病毒性腹泻的流行，对于该病毒感染的防控措施不包括","o":["避免饮用未经煮沸的水","加强洗手","污染物消毒","注射丙种球蛋白","口服减毒活疫苗"],"a":3,"e":"轮状病毒经粪-口途径传播，防控以煮沸饮水、加强洗手、污染物消毒切断传播途径，以及口服减毒活疫苗建立主动免疫为主。丙种球蛋白为人工被动免疫，抗体半衰期短，对消化道传播的轮状病毒腹泻无预防价值"},{"q":"患者，女，18岁，因“3天前饮食不洁，出现剧烈腹泻和呕吐，排泄物呈米泔水样”急诊入院。体温正常，皮肤干燥，眼窝内陷，请问致病菌可能是","o":["痢疾志贺菌","伤寒沙门菌","霍乱弧菌","副溶血性弧菌","肠产毒性大肠埃希菌"],"a":2,"e":"饮食不洁后剧烈吐泻、米泔水样便、皮肤干燥与眼窝内陷，为霍乱弧菌。痢疾志贺菌引起脓血便与里急后重；伤寒沙门菌为持续发热与玫瑰疹；副溶血性弧菌多与海产品有关、呈洗肉水样便；肠产毒性大肠埃希菌为水样泻，但无米泔水样便与重度脱水"},{"q":"患儿，女，5岁。发烧5日，咽痛，免疫接种史不详。在咽后壁、腭弓和悬雍垂等处发现灰白色膜状物，血白细胞数1.5×109/L。初步诊断最可能的病原体为","o":["细菌","病毒","真菌","支原体","衣原体"],"a":0,"e":"咽后壁、腭弓灰白色假膜不易擦去，伴发热、咽痛而白细胞不高，为白喉棒状杆菌感染，属细菌性感染，需抗毒素加青霉素治疗。真菌性鹅口疮假膜呈白色凝乳状、可擦去，多见于免疫低下者；病毒性咽炎无假膜，仅充血与疱疹"},{"q":"患儿，女，10 岁。右眼眶周红斑、鳞屑10天。查体见右眶周有约5cm×6cm 大小红斑，红斑表面可见散在黄色小脓疱及白色的鳞屑。家中长期养狗。用胶带粘取病变部位鳞屑，拟进行显微镜观察以初步诊断，观察前对鳞屑的处理方法是","o":["高压蒸汽灭菌","紫外线照射30分钟","80℃加热30分钟","10% KOH微加热","10% H2SO4 微加热"],"a":3,"e":"含角质的鳞屑、病发、甲屑需用10%KOH微加热消化角质，使真菌菌丝与孢子清晰显露后直接镜检。高压蒸汽灭菌、紫外线照射与80℃加热均为消毒灭菌手段，会破坏标本中的真菌；10%硫酸微加热用于弱抗酸染色脱色，不是真菌镜检的预处理"},{"q":"患者，男，27岁，因心悸、严重头痛、疲劳、游走性关节痛以及周围神经根神经症状就医。自诉3个月前有过一次野营旅游，回来后腿上出现红疮，但他记忆中没被硬蜱叮咬过，红疮微微隆起，逐渐扩大形成一片圆形皮损，外缘鲜红，发热，直径大约5cm，约3周后消退。住院检查脑脊液显示有淋巴细胞，没有发现中性粒细胞。该患者最可能的疾病是","o":["猩红热","恙虫病","莱姆病","钩端螺旋体病","皮肤炭疽"],"a":2,"e":"伯氏疏螺旋体经硬蜱叮咬传播，叮咬处出现逐渐扩大的慢性移行性红斑，伴头痛、肌痛，可发生面神经麻痹、脑膜炎与慢性关节炎。恙虫病有焦痂及恙螨叮咬史；钩端螺旋体病以腓肠肌压痛、结膜充血为主，无环形红斑"},{"q":"患者，女，70岁，因尿路感染于5天前开始服用氨苄西林。现出现腹泻。取粪便标本培养，培养出大量革兰阳性葡萄球菌。请问腹泻发生的可能机制是","o":["菌群失调","细菌产生肠毒素","细菌侵袭肠黏膜所致","细菌内毒素作用于肠黏膜","抗生素使用时间不够"],"a":0,"e":"长期使用氨苄西林杀灭肠道正常菌群中的敏感菌，耐药的金黄色葡萄球菌大量繁殖并产生肠毒素，属抗生素诱发的菌群失调性腹泻。细菌侵袭肠黏膜见于侵袭性大肠埃希菌与志贺菌感染；内毒素作用于肠黏膜引起发热与全身反应，不造成菌群更替；肠毒素单独作用为食物中毒，与用药5天后发病不符"},{"q":"患者，男，30岁。3周前出现为尿道内不适，刺痛及烧灼感，并伴有不同程度的尿频、尿急、尿痛。尿道口轻度红肿并有浆液分泌物，附睾肿大，有触痛，分泌物镜检未见革兰阴性双球菌，最有可能是何种病原体感染","o":["沙眼衣原体","淋球菌","梅毒螺旋体","人巨细胞病毒","白假丝酵母菌"],"a":0,"e":"沙眼衣原体D～K型引起非淋菌性尿道炎，分泌物呈浆液性、镜检无革兰阴性双球菌，可合并附睾炎与前列腺炎。淋球菌感染为脓性分泌物、中性粒细胞内可见革兰阴性双球菌；梅毒螺旋体以硬下疳和梅毒疹为主，需镀银染色查螺旋体"},{"q":"患者，女，30岁。月经期突发高热、呕吐、腹泻，并出现明显皮疹，紧急到医院就诊。主诉未接触不洁食物，近期也无外伤、手术史，个人生活习惯良好，但在月经期习惯使用月经塞。为确定该患者是否为金黄色葡萄球菌感染，最应该进行下列哪项检测","o":["革兰染色","药敏试验","甘露醇发酵实验","肥达反应","外斐反应"],"a":2,"e":"金黄色葡萄球菌分解甘露醇产酸，表皮葡萄球菌与腐生葡萄球菌均不分解，甘露醇发酵是三种常见葡萄球菌定种的关键生化依据。革兰染色只能显示革兰阳性葡萄串状球菌，无法区分菌种；药敏试验用于指导选药，不具鉴定价值；肥达反应用于肠热症，外斐反应用于立克次体病"},{"q":"患者，男，20岁，在广东务工2年，10月22日起出现高热，头痛、乏力伴肌肉酸痛3天入院。查体：体温39℃，下肢及前胸皮肤可见较多红色斑丘疹，结膜充血。血常规示血小板轻度减少，肝肾功能正常。患者近半个月来无外出活动史和野生动物接触史，无外来亲友探访，未接触过发热病人。应进一步进行病原学和血清学检查的病原体是","o":["登革病毒","乙型脑炎病毒","森林脑炎病毒","钩端螺旋体","汉坦病毒"],"a":0,"e":"广东10月、高热头痛肌痛、结膜充血、躯干四肢红色斑丘疹伴血小板减少，为登革病毒，经伊蚊叮咬传播。乙型脑炎以意识障碍为主、无皮疹；森林脑炎有蜱咬史与地区性；钩端螺旋体病有腓肠肌压痛与黄疸；汉坦病毒引起出血热并伴肾损害"},{"q":"患者，男，49岁。3年来双下肢乏力，步态不稳，间有发麻，日渐加重。近3个月来加重，晚间无法行走。大小便不畅，便秘。查体：双下肢肌张力高，肌力3～4度，胸6以下痛觉稍减退，音叉觉及双足关节位置觉消失，腱反射活跃，双侧Babinski（＋）。曾按脊髓炎、亚急性联合变性治疗，病情继续发展，后发现双瞳孔不等圆，左2mm，右2.5mm，光反应极弱，调节反应灵敏。追问出冶游性病史（硬下疳）。对该患者进行实验室诊断，需做下列哪项筛查试验","o":["TPI","RPR","FTA-TBS","MHA-TP","TPHA"],"a":1,"e":"有硬下疳史、双下肢无力伴深感觉障碍与瞳孔异常，血RPR 1∶32、TPHA 1∶2560，提示神经梅毒，初筛应选RPR。TPI、FTA-ABS、MHA-TP与TPHA均为特异性密螺旋体抗原试验，用于确认而非筛查，操作繁、成本高。RPR以心磷脂抗原检测反应素，滴度随病情升降，便于判断疗效"},{"q":"某校多名学生在食堂进餐后数小时出现恶心、呕吐症状。取剩余食物作细菌培养，革兰染色并在显微镜下观察到革兰阳性的球菌，培养物可分解甘露醇，检测血浆凝固酶和耐热核酸酶试验阳性。该致病菌还有何其他特点","o":["SPA是重要的抗原和致病物质","不耐低温和干燥","属于条件致病菌","可形成双层溶血环","有鞭毛，有芽孢"],"a":0,"e":"葡萄球菌A蛋白（SPA）能与IgG的Fc段结合，具抗吞噬作用，是金黄色葡萄球菌重要的表面抗原与致病物质。本菌抵抗力强、耐干燥，故不耐低温干燥的说法错误；本菌为致病菌而非条件致病菌；双层溶血环为产气荚膜梭菌的特点"},{"q":"患者，女，26岁，因发热、咳嗽、眼结膜炎、米糠样皮疹在市传染病院诊断为麻疹，否认麻疹接触史，否认幼时患过麻疹。其有3月龄婴儿，平时因带娃喂奶等与婴儿密切接触。针对该婴儿可采取的预防措施是","o":["抗病毒治疗","接种减毒活疫苗","注射丙种球蛋白","接种灭活疫苗","防止硬蜱叮咬"],"a":2,"e":"3月龄婴儿未到麻疹疫苗初种月龄，接触麻疹病人后应尽早注射丙种球蛋白获得被动免疫。减毒活疫苗受母体抗体干扰且此时接种风险大，不宜使用；灭活疫苗对麻疹无保护作用；麻疹亦无有效抗病毒预防用药"},{"q":"患儿，男，2岁。因不对称下肢就诊。其母诉说患儿3个月前患持续性发热，头痛，腹泻，之后自然消失。查体示右下肢细短，软弱无力不能行走，右腿深部腱反射消失，但无感觉障碍。上肢活动正常，头部神经反射正常。肌电图（EMG）呈慢性部分神经切除改变，并伴有静脉肌肉异常自发活动。引起患儿疾病最可能的病原体是","o":["脊髓灰质炎病毒","脑膜炎奈瑟菌","新型隐球菌","流行性乙型脑炎病毒","埃可病毒"],"a":0,"e":"脊髓灰质炎病毒主要侵犯脊髓前角运动神经元，呈不对称性弛缓性麻痹，腱反射消失而感觉正常，晚期出现肌肉萎缩。乙型脑炎以高热、意识障碍与脑膜刺激征为主，瘫痪多为痉挛性；埃可病毒多致无菌性脑膜炎与皮疹，极少遗留肢体萎缩"},{"q":"患者，女，26岁，洗浴中心工作。近10日出现尿频、尿痛、并有轻微尿道灼烧感。查体可见外阴红肿，有脓性分泌物，自诉曾有不洁性交史，建议采集何种标本检测","o":["血液","尿道脓性分泌物","尿液","唾液","粪"],"a":1,"e":"淋病奈瑟菌侵犯尿道柱状上皮，取尿道口脓性分泌物涂片革兰染色，见中性粒细胞内革兰阴性双球菌即可初诊。血液标本仅在淋菌性菌血症时有意义；尿液需离心取沉渣且阳性率低；唾液与粪便不含该菌。女性应取宫颈口分泌物，本例为外阴脓性分泌物"},{"q":"患者，男，28岁，因持续高热入院2周，诊断为急性粒细胞性白血病，化疗1周后，患者口腔黏膜上出现白色膜状物，该患者最可能感染的病原体是","o":["奋森螺旋体","白喉棒状杆菌","白假丝酵母菌","厌氧菌","变异链球菌"],"a":2,"e":"白念珠菌为条件致病真菌，白血病化疗后免疫功能低下时在口腔黏膜形成白色假膜，即鹅口疮，涂片可见芽生孢子与假菌丝。白喉棒状杆菌假膜不易擦去并伴全身中毒症状；奋森螺旋体致坏死性龈口炎，有腐败臭味；变异链球菌致龋齿"},{"q":"2岁患儿，因发热、呕吐、腹泻1天入院。起病6小时以来共呕吐2次，腹泻4次，为蛋花汤样水样便，无脓血，无咳嗽，无咽痛，体温38.5℃。初步判断最可能的病原体是","o":["痢疾志贺菌","肠侵袭性大肠埃希菌","轮状病毒","伤寒沙门菌","肠道腺病毒"],"a":2,"e":"轮状病毒是婴幼儿秋季腹泻的首位病原，典型表现为蛋花汤样水样便、呕吐与发热，无脓血，经粪-口传播。肠侵袭性大肠埃希菌与痢疾志贺菌侵袭肠黏膜，粪便带黏液脓血并有里急后重；肠道腺病毒腹泻较轻，多伴咽痛、咳嗽"},{"q":"一位医生在给一名HBeAg阳性患者采血时，不小心刺破自己手指。下列处理最为紧要的是","o":["接种乙肝疫苗","进行酒精消毒","肌注高效价乙肝免疫球蛋白","肌注高效价乙肝表面抗原","定期复查肝功能和HBV-IgM"],"a":2,"e":"HBeAg阳性提示病毒复制活跃、传染性强，职业暴露后应立即肌注高效价乙肝免疫球蛋白中和病毒，并同时接种乙肝疫苗。酒精消毒只能减少局部污染，不能阻断已进入血流的病毒；单用疫苗需数周才产生抗-HBs，不能应急"},{"q":"患者，女，自述双侧腰部疼痛不适伴有尿频、尿急、尿痛、寒战、头痛，门诊以大肠埃希菌感染引起的“急性肾盂肾炎”收治入院。取患者尿液做培养时，IMViC试验结果应为","o":["＋ ＋ － －","＋ － － －","－ － － －","＋ ＋ ＋ ＋","－ － ＋ ＋"],"a":0,"e":"大肠埃希菌IMViC结果为吲哚阳性、甲基红阳性、VP阴性、枸橼酸盐阴性，即加加减减，因该菌不能利用枸橼酸盐为碳源。产气肠杆菌为减减加加；志贺菌不发酵乳糖、无动力，与大肠埃希菌的乳糖发酵和动力特征不同"},{"q":"患儿，男，5岁，咳嗽1个月。初起有发热、喷嚏、轻咳等症。现已不发热，但咳嗽日渐加重，尤夜间为重，为阵发性痉挛性咳嗽，伴呕吐。查体：患儿精神萎靡，面部水肿，眼结膜出血，舌系带溃疡，肺部未闻及啰音。实验室检查：白细胞总数达18×109/L。经红霉素治疗3天后症状减轻。其感染的病原菌最可能是","o":["肺炎链球菌","呼吸道合胞菌","腺病毒","肺炎支原体","百日咳鲍特菌"],"a":4,"e":"阵发性痉咳、夜间为重、咳后呕吐，伴面部水肿、结膜出血与舌系带溃疡，白细胞显著升高且红霉素有效，符合百日咳鲍特菌感染。肺炎链球菌肺炎有高热与肺实变；呼吸道合胞病毒与腺病毒多引起毛细支气管炎、咽结膜热，无痉咳与舌系带溃疡；肺炎支原体肺炎以干咳为主，无鸡鸣样吼声"},{"q":"患者，女，25岁，已婚。最近发现阴道分泌物增多，呈淡黄色，污秽裤裆。白带镜检发现白细胞较多，淋球菌培养阴性。沙眼衣原体PCR检测阴性。取尿沉渣做支原体培养，生化反应显示能分解精氨酸，但不能分解尿素，在固体培养基上能长出“荷包蛋”样菌落。请问该患者最可能感染了以下哪种微生物","o":["解脲脲原体","生殖支原体","人型支原体","肺炎嗜衣原体","肺炎支原体"],"a":2,"e":"人型支原体分解精氨酸、不分解尿素，固体培养基上呈荷包蛋样菌落，引起阴道炎、盆腔炎。解脲脲原体分解尿素而不分解精氨酸；生殖支原体与肺炎支原体均发酵葡萄糖，前者致生殖道感染，后者致呼吸道感染"},{"q":"患者，女，30岁，持续发热10天，体温呈稽留热。查体：精神萎靡，反应淡漠，体温39.5℃，心率76次/min，肝肋下1.5cm，脾肋下2cm。白细胞3、2×109/L。肥达反应O 1∶320，H 1∶320。ALT 80U/L，血胆红素24μmol/L。该患者最可能的诊断是","o":["急性黄疸性肝炎","急性血吸虫病","伤寒合并中毒性肝炎","钩端螺旋体病","病毒性肝炎合并胆道感染"],"a":2,"e":"稽留热、表情淡漠、相对缓脉、肝脾大，白细胞减少，肥达反应O与H均1∶320，伴转氨酶与胆红素升高，为伤寒合并中毒性肝炎。急性黄疸性肝炎以乏力、纳差、黄疸为主，无稽留热与脾大；急性血吸虫病有疫水接触与嗜酸性粒细胞增多；钩端螺旋体病有腓肠肌压痛与结膜充血"},{"q":"患者，女，22岁。入院前2周持续性发热，体温高达39～40℃，发热期间伴食欲缺乏。体检肝、脾略大，腹部见玫瑰疹。血白细胞3.5×109/L。肝功正常，血培养阴性，肥达试验结果：TO 1∶320，TH 1∶320，PA 1∶40，PB 1∶40。该患者最可能的诊断是","o":["病毒性肠胃炎","上呼吸道感染","细菌性痢疾","淋巴结炎","伤寒"],"a":4,"e":"持续发热、脾大、玫瑰疹伴白细胞减少，肥达反应O效价1∶320、H效价1∶320，符合伤寒。细菌性痢疾以脓血便与里急后重为主；病毒性胃肠炎病程短、无玫瑰疹。副伤寒甲、乙、丙的H抗体分别为PA、PB、PC，本例二者仅1∶40，无升高"},{"q":"一位24岁男青年近日出现恶心、呕吐和腹泻症状，且吐泻次数逐日多，每日达10～20次。大便呈米泔水样，有一定程度的脱水。血压降低（收缩压为9.31～12kPa）（90～70mmHg），脉搏细速，血浆比重为1.031～1.040，24小时尿量在500ml以下。经问诊，该青年一周前从洪水疫区归来，曾饮用过生水。请问该男青年最可能感染哪种病原体","o":["产气荚膜梭菌","霍乱弧菌","金黄色葡萄球菌","伤寒沙门菌","变形杆菌"],"a":1,"e":"霍乱弧菌经污染水源经口感染，在碱性肠液中大量繁殖并释放霍乱肠毒素，使肠黏膜上皮细胞cAMP升高、分泌亢进，排出米泔水样便，随之脱水与循环衰竭。产气荚膜梭菌产生α毒素引起气性坏疽与坏死性肠炎，不引起米泔水样泻；金黄色葡萄球菌肠毒素所致食物中毒潜伏期仅1～6小时、以呕吐为主；伤寒沙门菌表现为持续发热、相对缓脉与玫瑰疹；变形杆菌多为条件致病菌"},{"q":"患者，女，22岁。受凉后出现寒战、发热，咳嗽，咳少许黏痰3天，自服感冒药后热退，查体：T39.5℃，急性病容，右肺呼吸音减弱，语音震颤增强，下肺大片状模糊音影。该患者抗感染治疗不宜使用的是","o":["青霉素","左氧氟沙星","阿莫西林","头孢曲松","阿米卡星"],"a":4,"e":"本例为大叶性肺炎，病原以肺炎链球菌为主，青霉素、阿莫西林为治疗首选，头孢曲松肺组织浓度高、左氧氟沙星亦有效。氨基糖苷类阿米卡星对肺炎链球菌天然活性差，肺内浓度低且有耳肾毒性，故不宜选用"},{"q":"某幼儿园，多名儿童相继出现低热、咳嗽等感冒症状，严重者出现阵发性痉挛性咳嗽，伴有呼吸困难、发绀等症状，咳时常呈鸡鸣样吼声。最可能感染的病原体是","o":["流感病毒","结核分枝杆菌","大肠埃希菌","百日咳鲍特菌","麻疹病毒"],"a":3,"e":"低热、咳嗽后出现阵发性痉咳伴鸡鸣样吼声、呼吸困难与发绀，为百日咳鲍特菌所致，该菌经飞沫传播、黏附于气管纤毛上皮。流感病毒以高热与全身酸痛为主；结核分枝杆菌为慢性低热、盗汗；大肠埃希菌引起肠道感染；麻疹病毒有卡他症状、科氏斑与皮疹"},{"q":"患者，女，52岁，农民。咳嗽、胸闷、气喘进行性加重9个月入院。病前有霉谷尘吸入史。查体：呼吸稍促，唇甲轻度发绀，两下肺闻及清脆、响亮湿啰音。X线胸片示两肺弥漫性斑片、结节、网状密度增高影，以中下肺为著。支气管肺泡灌洗液细胞分类检查：M 0.37，L 0.41，N 0.22。肺功能检查提示患者运动耐量、最大摄氧能力降低，呼吸频率明显增加，而潮气量增加受限，通气过度、通气效率降低，符合限制性肺病的特征。因有吸入霉谷尘病史，诊断为“农民肺”，该病的发病机制为","o":["真菌毒素中毒","致病真菌感染","条件致病真菌感染","真菌性超敏反应","真菌的侵袭性致病作用"],"a":3,"e":"农民肺为吸入霉谷尘中嗜热放线菌与真菌孢子后引发的Ⅲ型及Ⅳ型超敏反应，属外源性变应性肺泡炎。致病真菌感染有菌丝侵袭与肉芽肿形成；真菌毒素中毒由食入毒素引起肝、肾损害，均无弥漫性间质病变与限制性通气障碍"},{"q":"患者，女，高热，剧烈头痛，肌肉酸痛。入院检查，体格检查、外斐反应结果表明该病人为普氏立克次体感染。下列哪项为普氏立克次体感染的传播媒介","o":["人虱","鼠蚤","蚊子","蜱","恙螨"],"a":0,"e":"普氏立克次体以人虱（体虱）为传播媒介，虱叮咬时立克次体随粪便排于皮肤，经搔抓破损处侵入，引起流行性斑疹伤寒。鼠蚤传播斑疹伤寒立克次体所致地方性斑疹伤寒；恙螨传播恙虫病东方体；蜱传播斑点热群立克次体"},{"q":"患儿，女，1岁，咳嗽1月、发热3天入院。体温最高39℃，伴咳嗽、干咳、气促、胸痛，输青霉素、头孢曲松等药物6天，无缓解。查体：咽充血，右肺呼吸音粗，左肺下呼吸音减低。诊断为支原体肺炎。下列哪项不是该病原体的致病因素","o":["顶端结构的P1蛋白","过氧化氢等代谢产物","超抗原作用","微荚膜","内毒素"],"a":4,"e":"支原体无细胞壁、不含脂多糖，故不产生内毒素，不是其致病因素。P1蛋白为黏附素，介导支原体与呼吸道上皮结合；过氧化氢等代谢产物损伤上皮细胞与红细胞；超抗原激活大量T细胞引起免疫损伤；微荚膜抗吞噬，均参与致病"},{"q":"成年男性，东北某地林场职工，春季植树后主诉发热、头痛、肌肉及关节疼痛。体温38.5℃，左背皮肤有暗红色椭圆形斑块，直径约18cm，中央颜色较深，腋下淋巴结肿大，肝脾触诊正常，白细胞8.5×109/L。该男子可能的诊断是","o":["钩端螺旋体病","风湿性关节炎","感冒","莱姆病","回归热"],"a":3,"e":"林区职工、蜱叮咬后出现慢性移行性红斑，伴发热、头痛、肌痛与局部淋巴结肿大，为伯氏疏螺旋体所致莱姆病。钩端螺旋体病有疫水接触、腓肠肌压痛与结膜充血；风湿性关节炎无皮疹与蜱咬史；回归热由虱或蜱传播，表现为反复发热与菌血症，无慢性移行性红斑"},{"q":"某患者是一名羊毛加工者，2周前突发高热、寒战，3日后发热消退，然后再次出现高烧和寒战，随后出现肝脾大、腹泻和关节疼痛，革兰染色可见阴性短小杆菌，该患者可能感染的病原体是","o":["肺炎链球菌","沙门氏菌","霍乱弧菌","布鲁氏菌","大肠埃希菌"],"a":3,"e":"羊毛加工者经呼吸道或皮肤接触染菌，波状热、肝脾大、关节痛，革兰染色见阴性短小杆菌，为布鲁氏菌。肺炎链球菌为革兰阳性双球菌；沙门菌与霍乱弧菌经消化道传播、以腹泻为主；大肠埃希菌为肠道常驻菌，不引起波状热与肝脾大"},{"q":"患儿，女，5岁，因高热、意识模糊而入院。查体发现该患儿面色苍白，昏迷，时有惊厥，呼吸微弱。粪便：白细胞4个/HP。血常规：白细胞数16×109/L。脑脊液正常。粪便取材培养，革兰染色为阴性杆菌，动力试验阴性。诊断患儿感染","o":["鼠伤寒沙门菌","肠产毒型大肠埃细菌","肠致病型大肠埃细菌","轮状病毒","痢疾志贺菌"],"a":4,"e":"中毒型菌痢多见于儿童，高热、惊厥、昏迷而肠道症状轻，粪便白细胞少，培养为革兰阴性、动力阴性的杆菌。鼠伤寒沙门菌动力阳性、硫化氢阳性；肠产毒型与肠致病型大肠埃希菌动力阳性，不引起中毒性脑病；轮状病毒为病毒，革兰染色无细菌可见"},{"q":"某男性游客，在东南亚旅游因天热饮用不洁河水后半日，呕吐并腹泻6～7次，排泄物呈米泔水样物，外观呈脱水状。怀疑可能感染了霍乱弧菌，应采用的检查方法是","o":["血液检查","排泄物行细菌培养","排泄物直接涂片观察","排泄物行乳糖发酵试验","悬滴法镜下观察排泄物中细菌动力"],"a":4,"e":"米泔水样泻伴重度脱水，疑霍乱时应取吐泻物作悬滴法或暗视野镜检，见鱼群状穿梭运动的活泼弧菌即可快速初诊，再以制动试验鉴定血清群。血液检查无病原学意义；直接涂片革兰染色仅见阴性弧菌、不显示动力；乳糖发酵试验不用于弧菌鉴定；细菌培养可确诊但耗时较长"},{"q":"张某，男，45岁。近半个月来尿道口轻度红肿，晨起有少许稀薄分泌物。淋球菌培养阴性，沙眼衣原体检查阴性，疑为解脲脲原体感染引起的非淋菌性尿道炎，拟行病原体培养协助诊断。下列不符合培养要求的是","o":["培养基中加入10%～20%的人或动物血清","培养基中加入酵母浸液","培养基pH为7.6～8","在微氧条件培养","用固体培养基培养"],"a":2,"e":"解脲脲原体最适pH为5.5～6.5，而pH 7.6～8.0适合多数支原体，故该项不符合其培养要求。其培养需10%～20%人或动物血清提供胆固醇、酵母浸液提供核苷前体，并在含5%CO₂的微氧环境中于固体培养基上形成油煎蛋样菌落"},{"q":"患者，男，28岁。右大腿清创缝合术后6天，发热，局部伤口红肿，范围较大，疼痛明显。伤口局部见稀薄脓液，淡红色，量多，无异味。最可能感染的致病菌是","o":["大肠埃希菌","铜绿假单胞菌","溶血性链球菌","金黄色葡萄球菌","无芽孢厌氧菌"],"a":2,"e":"术后伤口红肿范围大、脓液稀薄呈淡红色、量多而无臭味，为乙型溶血性链球菌感染；其透明质酸酶与链激酶使病灶易于扩散、脓汁稀薄。金黄色葡萄球菌脓汁稠厚呈金黄色、界限较清；大肠埃希菌与铜绿假单胞菌为革兰阴性杆菌，后者脓液呈绿色；无芽孢厌氧菌脓液多有恶臭"},{"q":"部分儿童以“血便和血小板减少”入院，其中一名4岁女孩死于肾脏衰竭。流行病学调查显示所有患者都在同一家快餐店吃过牛肉汉堡。可能导致这次疾病爆发的病原体是","o":["空肠弯曲菌","非O1血清群霍乱弧菌","大肠埃希菌O157:H7","痢疾志贺菌","伤寒沙门菌"],"a":2,"e":"肠出血性大肠埃希菌O157∶H7经污染牛肉传播，产志贺毒素，引起血便及溶血尿毒综合征，儿童可因急性肾衰竭死亡。空肠弯曲菌多经禽肉传播、需微需氧培养；非O1群霍乱弧菌致散发性腹泻，不引起血便与肾衰"},{"q":"患者，女，68岁。自述1周前无明显诱因出现右侧腰部疼痛，夜间为甚；2日前疼痛加剧，痛如火燎，疼痛部位出现成簇疱疹。该患者可能患有","o":["麻疹","水痘","斑疹伤寒","带状疱疹","单纯疱疹"],"a":3,"e":"单侧肋间神经分布区疼痛后出现成簇水疱、沿神经节段排列，为潜伏于脊神经后根神经节的水痘-带状疱疹病毒再激活所致。水痘为全身向心性分布的斑丘疹与水疱疹；单纯疱疹多在口唇或生殖器成群水疱、不沿神经节段；麻疹有卡他症状与科氏斑；斑疹伤寒为全身斑丘疹伴高热"},{"q":"一女患者，36岁，已确诊为AIDS患者，外周血中CD4＋ T细胞为300个/μl。对此患者进行抗病毒治疗的最佳治疗方案为","o":["蛋白酶抑制剂＋抗病毒中药制剂","2种核苷类药＋蛋白酶抑制剂","联用2种核苷类药","选用一种核苷类逆转录酶抑制剂","选用一种非核苷类逆转录酶抑制剂"],"a":1,"e":"艾滋病期或CD4下降者应联合抗逆转录病毒治疗，标准方案为2种核苷类逆转录酶抑制剂加1种蛋白酶抑制剂或非核苷类逆转录酶抑制剂，从不同环节抑制病毒复制。单用1种核苷类或非核苷类药物易诱导耐药；抗病毒中药制剂无确切疗效；单药不能持久抑制病毒载量"},{"q":"某乙肝患者，近期两对半检查结果为：血清HBsAg（＋）、HBeAg（＋）及抗HBc IgM（＋）。对此结果解释不正确的是","o":["急性乙型肝炎","慢性乙型肝炎","乙型肝炎恢复期","无症状抗原携带者","血清有强传染性"],"a":2,"e":"HBsAg、HBeAg与抗-HBc IgM同时阳性，提示病毒复制活跃，见于急性乙肝、慢性乙肝活动期或无症状抗原携带者，血清传染性强，唯不符合恢复期。恢复期应见HBeAg阴转、抗-HBe阳转且抗-HBc IgM转阴。抗-HBc IgM是近期感染与复制活跃的指标"},{"q":"患者，女，55岁。乏力、食欲缺乏半个月，发热、咳嗽、痰中带血6天，以“右上肺继发性肺结核，痰结核菌涂片检查（＋）”收住院治疗。致病菌的生物学特点是","o":["专性厌氧菌","繁殖速度缓慢","革兰染色阳性","合成大量尿素酶","能够产生硫化氢"],"a":1,"e":"结核分枝杆菌代时为18～24小时，繁殖缓慢，培养需2～4周才见菌落，是结核病病程迁延的原因。专性厌氧为梭菌属特点，本菌为专性需氧；革兰染色不易着色，须用抗酸染色；脲酶与硫化氢非其鉴别要点"},{"q":"患儿，男，8岁，临床隔离期间出现呼吸道卡他症状，其父母均确诊为甲型流感H7N9感染病重收治入院。其姐姐（12岁）于7天前发热、咳嗽、呼吸困难，因重症肺炎及急性呼吸窘迫综合征（ARDS）抢救无效死亡，后其咽拭子核酸检测为H5N1阳性。对于该儿童（为重症病例的高危人群），一旦出现流感样症状，应采取的措施是","o":["确诊后48小时内给奥司他韦抗病毒药","确诊后给奥司他韦抗病毒药","在72小时之内给奥司他韦抗病毒药","在48小时内给奥司他韦抗病毒药","慎重，不急于给药"],"a":3,"e":"流感重症高危儿童一旦出现流感样症状，应在48小时内尽早给予奥司他韦，不必等待核酸检测确诊，以争取抗病毒时机。确诊后才给药会延误治疗；72小时已超过最佳窗口，重症虽仍可给药但获益下降"},{"q":"患儿，女，10岁。咽痛、咳嗽、发热后15天出现全身水肿，尿量减少，血压157/98mmHg。血常规：血红蛋白125g/L，白细胞5.7×109/L。尿常规：尿蛋白（＋），红细胞（＋＋＋＋），白细胞0个/HP，管型0个/HP。此病症由何种病原体感染所致","o":["金黄色葡萄球菌","A群链球菌","14型肺炎链球菌","脑膜炎奈瑟菌","淋球菌"],"a":1,"e":"咽痛发热后15天出现水肿、少尿、高血压与大量蛋白尿、血尿，为急性肾小球肾炎，由A群链球菌致肾炎株的抗原抗体复合物沉积肾小球所致。金黄色葡萄球菌可引起感染相关肾炎但非本型；14型肺炎链球菌引起大叶性肺炎；脑膜炎奈瑟菌与淋球菌不引起链球菌感染后肾炎"},{"q":"患者，男，14岁，学生。4天前无明显诱因突起头痛，进行性加重，伴畏寒、发热；1天前非喷射性呕吐内容物1次，无咖啡色液，无咳嗽咳痰。急性病容，嗜睡，咽稍红，皮肤黏膜无出血点，双侧扁桃体Ⅰ度肿大，左侧腮腺肿大及颌下腺肿大。脑膜刺激征阳性。血常规示白细胞总数及中性粒细胞无升高。查血、尿淀粉酶明显升高。脑脊液涂片墨汁负染阴性。该患者最可能的诊断是","o":["流行性乙型脑炎","结核性脑膜炎","流行性腮腺炎并发脑膜炎","新型隐球菌脑膜炎","脊髓灰质炎"],"a":2,"e":"腮腺炎病毒经飞沫侵入，先在呼吸道上皮与淋巴结增殖，经病毒血症侵犯腮腺及中枢神经系统，表现为腮腺肿大伴脑膜刺激征，血尿淀粉酶升高支持腮腺受累。乙型脑炎有高热与意识障碍而无腮腺肿大；结核性脑膜炎脑脊液呈毛玻璃样、蛋白明显增高；隐球菌脑膜炎墨汁负染应见厚荚膜酵母，本例阴性；脊髓灰质炎为不对称弛缓性麻痹"},{"q":"李某，男，60岁。上午6时到医院就诊，主诉在头天晚上18时左右食用羊肉火锅，4小时后出现腹痛腹泻症状。至就诊时，腹泻4～5次，尿液呈现深红色，肾叩痛，体温38℃；给予补液及抗生素治疗。8时许，患者腹痛加剧，手脚发麻，颈项僵直；9时30分抢救无效死亡。当日下午尸体迅速肿胀，颜面呈现紫褐色。晚5时解剖时呈巨人观。该患者的死亡可能是哪种疾病造成的","o":["金黄色葡萄球菌感染","甲型溶血性链球菌感染","结核分枝杆菌感染","肉毒梭菌感染","产气荚膜梭菌感染"],"a":4,"e":"进食羊肉后腹痛腹泻，迅速出现血红蛋白尿、肾损害与颈项强直，数小时内死亡，尸检见组织肿胀与巨人观，为产气荚膜梭菌大量繁殖产毒所致的败血症与气性坏疽样病变。金黄色葡萄球菌食物中毒病程短、不致死；甲型溶血链球菌与结核分枝杆菌不引起急速肿胀；肉毒梭菌以弛缓性麻痹为主、无明显气肿"},{"q":"患儿，女，12岁，学生。因外阴瘙痒、分泌物增多1个月余，加重2周来我科门诊就诊。查体：外阴、阴阜可见对称性片状红斑，境界清楚，边缘可见散在红色丘疹。外阴分泌物多，实验室检查：取外阴阴道口分泌物，经10%KOH压片直接镜检，可见如图所示微生物。该患儿最可能感染的病原体是","o":["螺旋体","细菌","真菌","支原体","衣原体"],"a":2,"e":"外阴瘙痒、境界清楚的片状红斑伴边缘丘疹，10%KOH压片见菌丝与孢子，为念珠菌所致真菌性外阴阴道炎。螺旋体需镀银染色或暗视野观察；细菌在KOH中无特征性菌丝；支原体无细胞壁、需培养或核酸检测；衣原体形成包涵体，并非KOH可查见的结构"},{"q":"7岁儿童，近日因皮肤不适到医院皮肤科门诊就诊。患儿家长诉患病初期皮肤表面出现红斑，并且在1～2天时皮肤表面出现褶皱，随后出现清亮的水泡。触碰患儿皮肤表面时，患儿哭闹不止，并有皮屑脱落。取皮肤样本进行微生物学检测，培养物能发酵甘露醇，在血琼脂平板上形成的菌落周围有完全透明的溶血环，此病原体最有可能是","o":["鼠疫耶尔森菌","霍乱弧菌","金黄色葡萄球菌","解脲脲原体","梅毒螺旋体"],"a":2,"e":"红斑转为表皮褶皱、继而出现清亮水疱与大片脱屑伴触痛，为金黄色葡萄球菌表皮剥脱毒素所致烫伤样皮肤综合征；该菌发酵甘露醇，在血平板上呈完全透明的β溶血环。鼠疫耶尔森菌与霍乱弧菌不分解甘露醇、不呈β溶血；解脲脲原体无细胞壁、革兰染色不着色；梅毒螺旋体需镀银染色"},{"q":"某患者，发热头痛3天，伴恶心、呕吐和腹痛。查体：双侧肾区叩痛，低血压，右侧肘窝抽血部位可见瘀斑。尿常规示血尿、蛋白尿和白细胞尿。可考虑诊断的疾病是","o":["斑疹伤寒","猩红热","肾综合征出血热","钩体病","登革热"],"a":2,"e":"汉坦病毒感染后表现为发热、头痛、腰痛、恶心呕吐、球结膜充血及大量蛋白尿，肾区叩痛与皮肤瘀斑提示血管损伤，即肾综合征出血热。斑疹伤寒有外斐反应阳性与皮疹而无明显肾损害；猩红热有咽峡炎、杨梅舌与弥漫充血疹"},{"q":"患者，女，24岁，药物流产10日后再次就诊，诉近几日白带增多，带血丝，有异味。妇检：子宫附件正常，扩阴器暴露阴道，见后穹隆部有豆腐渣样块状分泌物，宫颈口有少量血性黏液。分泌物涂片镜检发现如图所示病原体该病原体最可能为","o":["单细胞真菌","多细胞真菌","丝状真菌","支原体","沙眼衣原体"],"a":0,"e":"本题原题配有图片，图片未随文档保留，以下解析依文字线索推断：题干涉及图片/信息缺失，无法作答。白念珠菌为单细胞真菌，圆形或卵圆形，芽生繁殖，组织内形成芽生孢子与假菌丝，引起豆腐渣样白带。多细胞真菌有菌丝与孢子，如毛癣菌；支原体无细胞壁、呈油煎蛋样菌落；沙眼衣原体专性细胞内寄生，见包涵体\n\n官方题库中缺失图片"},{"q":"患者，女，20岁。主诉近1个多月来咳嗽，痰中时有血丝。消瘦并常感疲乏无力，午后微热，手心脚心热，心悸，盗汗，食欲缺乏。医生高度怀疑其为肺结核，欲进行痰标本微生物学检查。试问痰标本集菌涂片后，应选用的染色方法是","o":["革兰染色法","抗酸染色法","奈瑟染色法","墨汁染色法","镀银染色法"],"a":1,"e":"肺结核痰标本集菌后行抗酸染色，结核分枝杆菌保留石炭酸复红而呈红色，为病原学诊断的首选方法。革兰染色对分枝杆菌着色不良、无鉴别意义；墨汁染色用于观察隐球菌荚膜；镀银染色用于螺旋体"},{"q":"患者，女，35岁。突起头痛，眼眶痛，腰痛，胸颈部点状瘀斑，尿量少，色红，浑浊。最可能的诊断是","o":["血小板减少性紫癜","猩红热","急性肾小球肾炎","肾综合征出血热","波浪热"],"a":3,"e":"突起头痛、眼眶痛、腰痛三痛，胸颈部点状瘀斑，少尿与血尿，为汉坦病毒所致肾综合征出血热。血小板减少性紫癜无发热与肾损害；猩红热有草莓舌与弥漫充血性皮疹；急性肾小球肾炎有水肿、高血压与血尿，但无出血热的三痛；波浪热为布鲁氏菌病的波状热"},{"q":"患者，男，腿部皮肤被叮咬，突发高热，局部出现溃疡。入院体格检查、实验室检查诊断为斑疹伤寒立克次体感染。斑疹伤寒立克次体的传染源与储存宿主是","o":["人虱","鼠蚤","鼠","蜱","恙螨"],"a":2,"e":"斑疹伤寒立克次体即莫氏立克次体，引起地方性斑疹伤寒，鼠是其主要传染源与储存宿主，鼠蚤为传播媒介，蚤粪污染叮咬伤口而感染。人虱是普氏立克次体的传播媒介与储存宿主；蜱为莱姆病与斑点热的媒介；恙螨传播恙虫病东方体"},{"q":"患儿，男，4岁。急发高热，呕吐，肌肉疼痛，继之出现急性迟缓性麻痹。查体示左上肢能轻微运动，右侧下肢不能运动，巴宾斯基征阴性，腱反射消失，肌张力下降，其他无异常。3个月后随访，右下肢近端大肌群麻痹，肌肉严重萎缩，功能受限，跛行。该患儿感染的最可能的途径是","o":["呼吸道","消化道","血液和血制品","母婴传播","恙螨叮咬"],"a":1,"e":"脊髓灰质炎病毒经粪-口途径传播，先在咽部与肠道淋巴组织增殖，经病毒血症侵犯脊髓前角运动神经元。呼吸道是流感、麻疹等病毒的传播途径；血液及血制品传播见于乙肝、丙肝与艾滋病；母婴传播见于HIV与HBV"},{"q":"患者，男，50岁。1个月前出现间歇性发烧、游走性关节疼痛、全身乏力，发烧时体温38.5℃左右，退烧时体温可恢复正常；1周前病情加重就诊。患者从事农场牧羊工作，养殖的多只羊有流产现象。实验室检查，患者血清抗链O试验阴性，该患者最可能感染的是","o":["肺炎链球菌","布鲁氏菌","A族链球菌","流感病毒","风疹病毒"],"a":1,"e":"牧羊且羊群有流产史，间歇发热、游走性关节痛、乏力，抗链O阴性，为布鲁氏菌病。A族链球菌感染后抗链O升高，引起咽炎、风湿热与肾炎；肺炎链球菌引起大叶性肺炎；流感病毒与风疹病毒表现为呼吸道症状与皮疹，均不伴羊接触史与波状热"},{"q":"患者，男，39岁，无烟酒嗜好，于15日前出差回来后出现乏力，恶心呕吐，排便每日4～5次。体温逐日上升，服用乳酸菌素和黄连素未见缓解，近一周持续在39、5～40℃。躯干隐约可见淡红色皮疹，直径2～3mm，压之褪色，右下腹压痛。下列除哪项检测外，结果为阳性均有助于诊断","o":["骨髓培养","血液培养","肥达反应","粪便培养","咽拭子培养"],"a":4,"e":"持续高热、相对缓脉、淡红色皮疹、右下腹压痛，白细胞减少，符合伤寒；骨髓与血培养阳性率最高，肥达反应与粪便培养亦有助诊断。咽拭子培养用于白喉与链球菌咽炎，对伤寒无诊断价值。尿培养仅在病程后期可阳性，不作为常规首选"}];
